window.PM_DATA={"secciones":[{"nombre":"الأساسيات","grupos":[{"nombre":"أساسيات علم الحركة","icono":"🧭","temas":[1,2,3,4]},{"nombre":"التقييم","icono":"📋","temas":[5,6,7,8,9]}]},{"nombre":"الاختبارات الخاصة حسب المنطقة","grupos":[{"nombre":"الكتف","icono":"💪","temas":[10,11,12]},{"nombre":"المرفق والرسغ واليد","icono":"✋","temas":[13,14]},{"nombre":"العمود الفقري والحوض","icono":"🦴","temas":[15,16,17]},{"nombre":"الورك والركبة","icono":"🦵","temas":[18,19,20]},{"nombre":"الكاحل والقدم","icono":"🦶","temas":[21]},{"nombre":"الاختبارات العصبية","icono":"🧠","temas":[22]}]},{"nombre":"الإصابات وإعادة التأهيل","grupos":[{"nombre":"الكتف","icono":"💪","temas":[23,24,25]},{"nombre":"الرياضة والأوتار والعضلات","icono":"🏃","temas":[26,27,28,29,30]},{"nombre":"جراحة العظام والإصابات","icono":"🦴","temas":[31,32,33]},{"nombre":"العمود الفقري","icono":"🧍","temas":[34,35,36]},{"nombre":"الأمراض العصبية","icono":"🧠","temas":[37,38,39,40,41]}]},{"nombre":"العلاجات والتدخلات","grupos":[{"nombre":"التقنيات والعلاج بالوسائل الفيزيائية","icono":"🤲","temas":[42,43,44,45,46,47]},{"nombre":"العلاج بالحركة والتخصصات","icono":"🩺","temas":[48,49,50,51,52,53]},{"nombre":"حالات سريرية","icono":"🧩","temas":[54]}]}],"temas":{"1":{"id":1,"title":"المستويات والمحاور","lead":"تُوصف حركات الجسم بثلاثة مستويات أساسية وبمحاور الحركة العمودية عليها. وربط كل مستوى بمحوره هو أساس كل فحص وتوثيق وتحليل للحركة.","sheet":{"kind":"basics","items":[{"h":"الوضع المرجعي","t":"تُعرَّف المستويات والمحاور انطلاقًا من الوضع التشريحي. أما الصفر في قياس مدى الحركة فهو الوضع المحايد (الساعد في الوضع المتوسط)، لذا انتبه للفرق بينهما."},{"h":"المستوى السهمي","t":"يقسم الجسم إلى نصف أيمن ونصف أيسر. تحدث فيه حركات الثني والبسط، والعطف الظهري والعطف الأخمصي للكاحل؛ ومحور الحركة هو المحور الجبهي (المستعرض)."},{"h":"المستوى الجبهي","t":"يقسم الجسم إلى جزء أمامي وجزء خلفي. تحدث فيه حركات التبعيد والتقريب والانحناء الجانبي للجذع؛ ومحور الحركة هو المحور السهمي."},{"h":"المستوى المستعرض","t":"يقسم الجسم إلى جزء علوي وجزء سفلي. يحدث فيه الدوران الداخلي والخارجي ودوران الجذع والثني والبسط الأفقيان للكتف؛ والمحور هو المحور الطولي."},{"h":"علاقة المستوى بالمحور","t":"يمر محور الحركة دائمًا عموديًا على مستوى الحركة. إذا حفظت كل مستوى مع محوره، يسهل عليك تصنيف أي حركة جديدة."},{"h":"الحركات المركبة","t":"تحدث الحركات الحقيقية في أكثر من مستوى. يُلاحَظ المشي أو الرمي في كل مستوى على حدة، ثم يُحلَّل ككل."}]},"keypoints":["المستوى السهمي = ثني وبسط، والمحور: المحور الجبهي (المستعرض)","المستوى الجبهي = تبعيد وتقريب، والمحور: المحور السهمي","المستوى المستعرض = دوران، والمحور: المحور الطولي","محور الحركة عمودي دائمًا على مستوى الحركة","في تحليل الحركة، لاحظ كل مستوى على حدة"],"case":{"text":"رياضي عمره 20 عامًا. في وضع الاستلقاء على الظهر يرفع الطرف السفلي مستقيمًا إلى الأمام (مفصل الورك). تريد توثيق هذه الحركة. في أي مستوى وحول أي محور تصفها؟","answer":"رفع الورك إلى الأمام هو ثني: حركة في المستوى السهمي، ومحورها المحور الجبهي (المستعرض). ولكي لا تخلط بينها وبين التبعيد في المستوى الجبهي، تحقق هل تحدث الحركة في المستوى الذي يقسم الجسم إلى نصف أيمن ونصف أيسر."},"questions":[{"level":"أساسي","q":"في أي مستوى يحدث التبعيد والتقريب؟","options":["المستوى السهمي","المستوى الجبهي","المستوى المستعرض","مستوى مائل"],"answer":1,"exp":"يقسم المستوى الجبهي الجسم إلى جزء أمامي وجزء خلفي، وفيه يحدث التبعيد والتقريب. ومحور الحركة هو المحور السهمي."},{"level":"أساسي","q":"ما محور الدوران الذي يحدث في المستوى المستعرض؟","options":["المحور الجبهي (المستعرض)","المحور السهمي","محور مائل","المحور الطولي"],"answer":3,"exp":"تحدث الحركة في المستوى المستعرض (الدوران) حول المحور الطولي العمودي على هذا المستوى."},{"level":"متوسط","q":"أي حركة تحدث في المستوى السهمي؟","options":["الانحناء الجانبي للجذع","العطف الظهري للكاحل","الدوران الخارجي للورك","تبعيد الكتف"],"answer":1,"exp":"العطف الظهري والعطف الأخمصي، مثل الثني والبسط، حركتان في المستوى السهمي. أما الانحناء الجانبي والتبعيد ففي المستوى الجبهي، والدوران الخارجي في المستوى المستعرض."},{"level":"متوسط","q":"في أي مستوى يحدث الثني الأفقي للكتف؟","options":["المستوى السهمي","المستوى الجبهي","المستوى المستعرض","لا ينتمي إلى أي مستوى"],"answer":2,"exp":"في الثني والبسط الأفقيين يتحرك الطرف العلوي المُبعَد بزاوية 90° في المستوى المستعرض، والمحور هو المحور الطولي."},{"level":"سريري","q":"تقيس الدوران الخارجي للكتف والعضد متدلٍّ والمرفق مثني بزاوية 90°. أي زوج مستوى ومحور صحيح؟","options":["المستوى السهمي – المحور الجبهي","المستوى الجبهي – المحور السهمي","المستوى المستعرض – المحور الطولي","المستوى المستعرض – المحور الجبهي"],"answer":2,"exp":"مع تدلي الذراع، يكون الدوران الداخلي والخارجي للكتف حركة في المستوى المستعرض حول المحور الطولي للعضد."},{"level":"سريري","q":"عند ملاحظة المشي، يهبط الحوض في مرحلة الارتكاز نحو جهة الساق المتأرجحة. أي مستوى تلاحظ أساسًا؟","options":["المستوى الجبهي","المستوى السهمي","المستوى المستعرض","لا يمكن تحديد المستوى"],"answer":0,"exp":"الميل الجانبي للحوض حركة في المستوى الجبهي، وتُلاحَظ من الأمام أو الخلف. ويشير إلى ضعف العضلة الألوية الوسطى (gluteus medius)."}],"seccion":"الأساسيات","grupo":"أساسيات علم الحركة","icono":"🧭","mapa":"img/mapas/t01.jpg","fichas":[],"secuencias":[]},"2":{"id":2,"title":"الميكانيكا الحيوية","lead":"تفسّر الميكانيكا الحيوية حركة الجسم من خلال العلاقة بين القوة والحركة. ومعرفة الروافع وعزم الدوران ومركز الكتلة تجعل تحميل التمارين العلاجية أدق.","sheet":{"kind":"basics","items":[{"h":"عزم الدوران","t":"التأثير الذي يُدير المفصل هو عزم الدوران. وهو حاصل ضرب مقدار القوة في ذراع القوة (المسافة العمودية بين محور الدوران وخط عمل القوة)."},{"h":"أنواع الروافع الثلاثة","t":"في الرافعة من النوع الأول يكون الارتكاز في الوسط، وفي الثاني المقاومة، وفي الثالث القوة. تعمل معظم العضلات كروافع من النوع الثالث: مناسبة للسرعة ولمدى الحركة."},{"h":"مركز الكتلة","t":"في الوقوف يقع مركز كتلة الجسم في الحوض، أمام الفقرة S2 بقليل. كلما وقع خط الثقل داخل قاعدة الارتكاز أكثر، كان الوضع أكثر ثباتًا."},{"h":"السلسلة الحركية","t":"في السلسلة الحركية المفتوحة (OKC) يتحرك الجزء البعيد بحرية، وفي المغلقة (CKC) يكون مثبتًا على الأرض أو سطح آخر. يُختار النوع حسب الهدف."},{"h":"أنماط الانقباض العضلي","t":"في الانقباض المركزي تبذل العضلة القوة وهي تقصر، وفي اللامركزي وهي تطول. أما الانقباض متساوي القياس فيحدث دون حركة في المفصل."},{"h":"التطبيق السريري","t":"كلما كان الثقل أبعد، طال ذراع القوة وزاد التحميل. يمكن ضبط تحميل التمرين ليس بالوزن فقط، بل بمكان وضعه أيضًا."}]},"keypoints":["عزم الدوران = القوة × ذراع القوة","معظم العضلات روافع من النوع الثالث (مناسبة للسرعة)","الوضع مستقر إذا وقع خط الثقل داخل قاعدة الارتكاز","يتحكم الانقباض اللامركزي في معظم حركات الإنزال","يمكن ضبط التحميل بمكان وضع الثقل أيضًا"],"case":{"text":"امرأة عمرها 65 عامًا مصابة بالفُصال العظمي في الركبة. في الاستلقاء على الظهر تؤدي تمرين SLR بثقل مثبت على الكاحل، لكنها تتعب بسرعة وتظهر حركات تعويضية.","answer":"إذا وضعت الثقل على الجزء القريب من الساق، يقصر ذراع القوة، فيقل عزم ثني الورك بالوزن نفسه. ارفع التحميل تدريجيًا مع مراقبة الألم والتعويض؛ ولا تكتفِ بزيادة عدد التكرارات."},"questions":[{"level":"أساسي","q":"في أي رافعة تقع نقطة الارتكاز بين القوة والمقاومة؟","options":["رافعة من النوع الأول","رافعة من النوع الثاني","رافعة من النوع الثالث","العجلة والمحور"],"answer":0,"exp":"في الرافعة من النوع الأول تكون نقطة الارتكاز في الوسط؛ والمثال النموذجي توازن الرأس للأمام والخلف."},{"level":"أساسي","q":"ثني المرفق بالعضلة ذات الرأسين العضدية مثال نموذجي على أي نوع من الروافع؟","options":["رافعة من النوع الأول","رافعة من النوع الثاني","رافعة من النوع الثالث","البكرة"],"answer":2,"exp":"يقع ارتكاز العضلة (القوة) بين مفصل المرفق (الارتكاز) والثقل في اليد (المقاومة)، لذا فهي رافعة من النوع الثالث."},{"level":"متوسط","q":"أي زوج يحدد مقدار عزم الدوران في المفصل؟","options":["مقدار القوة والسرعة","طول العضلة ومقطعها العرضي","مقدار القوة وذراع القوة","الكتلة ودرجة الحرارة"],"answer":2,"exp":"عزم الدوران هو حاصل ضرب مقدار القوة في المسافة العمودية بين محور الدوران وخط عمل القوة (ذراع القوة)."},{"level":"متوسط","q":"ما نوع الانقباض الذي تؤديه العضلة رباعية الرؤوس الفخذية أساسًا في مرحلة النزول في القرفصاء؟","options":["انقباض مركزي","انقباض متساوي القياس","انقباض متساوي الحركة","انقباض لامركزي"],"answer":3,"exp":"عند النزول تنثني الركبة، وتحمل العضلة رباعية الرؤوس وزن الجسم وهي تطول، وهذا انقباض لامركزي."},{"level":"سريري","q":"يفقد مريض مسن توازنه عندما يمد يده نحو شيء أمامه. ما أفضل تفسير من حيث مركز الكتلة؟","options":["اقترب خط الثقل من حافة قاعدة الارتكاز","اتسعت قاعدة الارتكاز أكثر من اللازم","انخفض مركز الكتلة أكثر من اللازم","زاد الانقباض المركزي"],"answer":0,"exp":"عند المد للأمام يقترب خط الثقل من الحافة الأمامية لقاعدة الارتكاز، فيقل الثبات."},{"level":"سريري","q":"تجعل المريض يؤدي بسط الركبة جالسًا بثقل مثبت. كيف تقلل التحميل دون تغيير الوزن؟","options":["أضع الثقل على الكاحل","أضع الثقل على الجزء القريب من الساق","أسرّع الحركة","أطيل الثبات في الوضع النهائي"],"answer":1,"exp":"إذا قرّبت الثقل من الركبة، يقصر ذراع القوة، فيقل عزم الدوران بالوزن نفسه."}],"seccion":"الأساسيات","grupo":"أساسيات علم الحركة","icono":"🧭","mapa":"img/mapas/t02.jpg","fichas":[],"secuencias":[]},"3":{"id":3,"title":"مدى الحركة (قياس الزوايا)","lead":"عند قياس مدى الحركة (ROM) نسجّل مدى حركة المفصل بالدرجات باستخدام مقياس الزوايا. وهذا أساس تقييم الإعاقة وتحديد الأهداف وتقييم فعالية العلاج.","sheet":{"kind":"basics","items":[{"h":"القواعد الأساسية","t":"الوضع المحايد هو 0°، ويُسجَّل القياس بخطوات من 5°. يُقاس أساسًا بالحركة السلبية؛ وإذا قست بالحركة الإيجابية فاذكر ذلك صراحة."},{"h":"الذراع الثابت والمتحرك","t":"طابق ذراعي مقياس الزوايا مع الجزء الثابت والجزء المتحرك المحددين لهذا المفصل، وضع مركزه على محور حركة المفصل."},{"h":"القيم المرجعية","t":"قيم مرجعية عامة (طريقة الوضع المحايد): الكتف ثني 180° وتبعيد 180°؛ المرفق ثني 150°؛ الورك ثني 120° وتبعيد 45°؛ الركبة ثني 135°. قارن دائمًا بالجهة المقابلة."},{"h":"الحركات التعويضية","t":"ميل الجذع للخلف أو ميل الحوض يعطيان قيمة أكبر من الحقيقية. ثبّت الجزء القريب جيدًا، وقِس بعد استبعاد التعويض."},{"h":"الشعور النهائي (end feel)","t":"تحقق من طبيعة المقاومة في نهاية المدى (عظمية، نسيج رخو، نسيج ضام) ومن الألم، واستنتج منها العامل الذي يحد الحركة."},{"h":"التوثيق وإعادة القياس","t":"سجّل وضع القياس، وهل كان القياس سلبيًا أم إيجابيًا، والزاوية التي يظهر عندها الألم. إعادة القياس بنفس الوضع والطريقة تسمح بالمقارنة."}]},"keypoints":["0° هو الوضع المحايد، وسجّل بخطوات من 5°","القياس سلبي في الأصل؛ وإذا كان إيجابيًا فاذكر ذلك","ثبّت الجزء القريب واستبعد التعويض","القيمة المرجعية استرشادية فقط، قارن دائمًا بالجهة المقابلة","استنتج العامل المحدد من الشعور النهائي والألم"],"case":{"text":"رجل عمره 40 عامًا مصاب بالتهاب ما حول مفصل الكتف. أثناء قياس ثني الكتف يميل الجذع للخلف، والقيمة المقاسة تكاد تساوي قيمة الجهة السليمة.","answer":"على الأرجح القيمة كبيرة بسبب تعويض ببسط الجذع. ثبّت الجذع وأعد القياس، وسجّل أيضًا زاوية ظهور الألم والشعور النهائي. لا تحكم بالتحسن بناءً على قيمة قيست مع التعويض."},"questions":[{"level":"أساسي","q":"ما القيمة المرجعية لثني الكتف؟","options":["90°","120°","150°","180°"],"answer":3,"exp":"القيمة المرجعية لثني الكتف وتبعيده كلاهما 180°."},{"level":"أساسي","q":"ما القيمة المرجعية للعطف الظهري للكاحل؟","options":["10°","20°","30°","45°"],"answer":1,"exp":"القيمة المرجعية للعطف الظهري للكاحل 20° (والعطف الأخمصي 50°). قِس دائمًا من الوضع المحايد (0°)."},{"level":"متوسط","q":"ما المبدأ الصحيح في قياس مدى الحركة؟","options":["نقيس بالحركة الإيجابية","نسجّل بخطوات من 1°","الوضع المحايد هو 0°","لا حاجة للمقارنة بالجهة المقابلة"],"answer":2,"exp":"الوضع المحايد هو 0°؛ ونقيس أساسًا بالحركة السلبية، بخطوات من 5°، مع المقارنة بالجهة المقابلة."},{"level":"متوسط","q":"علامَ يدل الشعور النهائي العظمي الصلب الذي يتوقف فجأة في نهاية المدى؟","options":["تشنج عضلي","تلامس عظم بعظم","شد محفظة المفصل","تلامس الأنسجة الرخوة"],"answer":1,"exp":"الشعور النهائي العظمي هو التوقف المحسوس عند تصادم العظام؛ ومثاله الطبيعي النموذجي بسط المرفق."},{"level":"سريري","q":"أثناء قياس تبعيد الورك يميل الحوض فتحصل على قيمة كبيرة جدًا. ما أول ما تفعله؟","options":["أسجّل القيمة كما هي","أثبّت الحوض وأعيد القياس","أقيس بالحركة الإيجابية","أوقف القياس"],"answer":1,"exp":"تعويض الحوض يعطي زاوية تبعيد كبيرة جدًا. ثبّت الحوض وأعد القياس."},{"level":"سريري","q":"بعد جراحة في الركبة يظهر ألم في نهاية الثني السلبي. ما التوثيق الأنسب؟","options":["أسجّل الزاوية فقط","أسجّل قيمة الجهة السليمة","لا أسجّل شيئًا ما دام هناك ألم","أسجّل أيضًا زاوية ظهور الألم"],"answer":3,"exp":"إلى جانب قيمة مدى الحركة، تساعد زاوية بدء الألم وطبيعته في تقييم العامل المحدد وفي إعادة التقييم."}],"seccion":"الأساسيات","grupo":"أساسيات علم الحركة","icono":"🧭","mapa":"img/mapas/t03.jpg","fichas":[],"secuencias":[]},"4":{"id":4,"title":"تقييم القوة العضلية 0–5","lead":"يقيّم اختبار القوة العضلية اليدوي (MMT) قوة العضلة على مقياس من ست درجات بين 0 و5، بالاستعانة بالجاذبية والمقاومة اليدوية. ويُظهر درجة الضعف وتوزيعه.","sheet":{"kind":"basics","items":[{"h":"الدرجات الست","t":"0: لا انقباض؛ 1: انقباض فقط؛ 2: مدى حركة كامل مع إلغاء الجاذبية؛ 3: مدى كامل ضد الجاذبية؛ 4: ضد مقاومة متوسطة؛ 5: ضد مقاومة قصوى، قوة طبيعية."},{"h":"ترتيب الفحص","t":"تحقق أولًا في وضع ضد الجاذبية هل تتحقق الدرجة 3. إذا تحققت، حدّد 4 أو 5 بالمقاومة؛ وإذا لم تتحقق، حدّد الدرجة 2 أو أقل في وضع بلا جاذبية."},{"h":"تطبيق المقاومة","t":"طبّق المقاومة عكس اتجاه الحركة على الجزء البعيد من القطعة الجسمية. لا تطبقها فجأة بل زِدها تدريجيًا، ولاحظ هل يستطيع المريض الثبات."},{"h":"التثبيت والتعويض","t":"ثبّت الجزء القريب، ولاحظ هل تظهر حركة تعويضية من عضلات أخرى. إذا تمت الحركة بالتعويض، لا يمكنك منح تلك الدرجة."},{"h":"معنى الدرجة 3","t":"الدرجة 3 هي الحد الذي تتحرك عنده القطعة ضد وزنها الذاتي: إنها «حد الجاذبية». وهي مرجع أيضًا في تقييم الحركات الوظيفية."},{"h":"الحدود","t":"يتضمن اختبار القوة العضلية اليدوي عناصر ذاتية، ويصعب به تمييز الفروق فوق الدرجة 4. عند وجود ألم أو توتر عضلي غير طبيعي سجّله أيضًا مع النتيجة."}]},"keypoints":["تحقق أولًا من الدرجة 3 ضد الجاذبية","الدرجة 3 هي «حد الجاذبية»","طبّق المقاومة عكس الحركة وعلى الجزء البعيد","ثبّت الجزء القريب ولا تُغفل التعويض","في أمراض الجهاز العصبي المركزي لا يكون MMT القياس الوحيد"],"case":{"text":"رجل عمره 70 عامًا يعاني قلة النشاط بسبب الرقود في المستشفى. جالسًا يبسط ركبته في كامل مدى الحركة، لكنه لا يستطيع مقاومة مقاومة خفيفة على الجزء البعيد من الساق.","answer":"يتحرك في كامل مدى الحركة ضد الجاذبية، لكن ليس ضد المقاومة، لذا فهي الدرجة 3. لا تطبّق مقاومة قوية مفاجئة، وانتبه للتعويض، مثل ميل الجذع للخلف."},"questions":[{"level":"أساسي","q":"أي درجة هي: «الانقباض مرئي أو محسوس، لكن لا توجد حركة في المفصل»؟","options":["الدرجة 0","الدرجة 1","الدرجة 2","الدرجة 3"],"answer":1,"exp":"في الدرجة 1 يكون الانقباض العضلي مرئيًا أو محسوسًا، لكن لا تحدث حركة في المفصل."},{"level":"أساسي","q":"أي درجة هي: مدى حركة كامل ضد الجاذبية، لكن ليس ضد المقاومة؟","options":["الدرجة 4","الدرجة 2","الدرجة 3","الدرجة 5"],"answer":2,"exp":"في الدرجة 3 يتحرك الجزء في كامل مدى الحركة ضد الجاذبية؛ وهذا هو «حد الجاذبية»."},{"level":"متوسط","q":"أي درجة نتحقق منها عادةً أولًا في اختبار القوة العضلية اليدوي؟","options":["الدرجة 1","الدرجة 5","الدرجة 0","الدرجة 3"],"answer":3,"exp":"نبدأ بالدرجة 3 في وضع ضد الجاذبية؛ وعلى نتيجتها يتوقف هل نطبّق مقاومة أم ننتقل إلى وضع بلا جاذبية."},{"level":"متوسط","q":"أين تطبّق المقاومة في اختبار القوة العضلية اليدوي؟","options":["فوق المفصل مباشرة","على الجزء القريب من القطعة","على الجزء البعيد من القطعة","على الجزء المثبَّت"],"answer":2,"exp":"نطبّق المقاومة عكس اتجاه الحركة على الجزء البعيد من القطعة، حيث يكون ذراع القوة أطول."},{"level":"سريري","q":"في الاستلقاء الجانبي لا يستطيع رفع الطرف السفلي بالتبعيد، لكنه في الاستلقاء على الظهر يُبعده في كامل المدى. ما الدرجة؟","options":["الدرجة 1","الدرجة 2","الدرجة 3","الدرجة 4"],"answer":1,"exp":"لا ينجح في وضع ضد الجاذبية (الاستلقاء الجانبي)، وينجح في كامل المدى بلا جاذبية (الاستلقاء على الظهر): الدرجة 2."},{"level":"سريري","q":"تريد قياس قوة الطرف العلوي لمريض بشلل نصفي مع تشنج شديد. ما أفضل نهج؟","options":["يصعب تقييم MMT وحده","يكون الهدف الدرجة 5","أحدد الدرجة بمقاومة قوية","لا حاجة لفحص الجهة السليمة"],"answer":0,"exp":"في أمراض الجهاز العصبي المركزي لا تتحقق شروط MMT بسبب التوتر العضلي والتآزرات الحركية؛ استخدم مقياسًا آخر أيضًا لتقييم الشلل."}],"seccion":"الأساسيات","grupo":"أساسيات علم الحركة","icono":"🧭","mapa":"img/mapas/t04.jpg","fichas":[],"secuencias":[]},"5":{"id":5,"title":"التاريخ المرضي","lead":"في التاريخ المرضي نسأل عن مسار الشكوى وطبيعتها وظروف حياة المريض، ونضع فرضية. وهذا يحدد اختيار الفحوص التالية والفرز من حيث السلامة.","sheet":{"kind":"basics","items":[{"h":"الهدف","t":"نضع فرضية من الشكوى الرئيسية ومسارها، ونرتّب الفحوص حسب الأولوية. وفي الوقت نفسه نفرز علامات الخطر التي تستلزم الإحالة الطبية."},{"h":"الشكوى والمرض الحالي","t":"سجّل الشكوى الرئيسية بكلمات المريض. اسأل عن البداية والسبب (إصابة أو تدريجي)، ثم عن المسار (يتحسن، يسوء، ثابت)."},{"h":"تقييم الألم","t":"حدّد مكان الألم وطبيعته وشدته (مثل NRS)، والعوامل المفاقمة والمخففة، والتقلب اليومي والألم الليلي."},{"h":"السوابق والأدوية","t":"اسأل عن الأمراض والعمليات السابقة والأمراض المصاحبة والأدوية. تناول مضادات التخثر والستيرويدات يستلزم الحذر أثناء العلاج."},{"h":"ظروف الحياة","t":"اسأل عن العمل والدور الأسري وبيئة السكن والنشاط. أدرج احتياجات المريض وأسرته وأهدافهم في تحديد الأهداف."},{"h":"أسلوب الأسئلة","t":"ابدأ بأسئلة مفتوحة، ودقّق بأسئلة مغلقة. تجنب المصطلحات المتخصصة؛ وإذا لخّصت ما قاله وأعدته عليه، تتجنب سوء الفهم."}]},"keypoints":["سجّل الشكوى الرئيسية بكلمات المريض نفسه","اسأل دائمًا عن السبب والمسار","افرز علامات الخطر: الألم الليلي، نقص الوزن","الأدوية (مثل مضادات التخثر) تستلزم الحذر","ابدأ بسؤال مفتوح ودقّق بسؤال مغلق"],"case":{"text":"رجل عمره 55 عامًا يعاني ألمًا أسفل الظهر منذ شهرين. يقول: «مؤخرًا لا أستطيع النوم ليلًا من الألم. ومع أني لم أفعل شيئًا، نقص وزني 5 كيلوغرامات».","answer":"الألم الليلي الذي لا يخف بالراحة ونقص الوزن غير المبرر من العلامات الحمراء. قبل بدء العلاج بالحركة أبلغ الطبيب ونسّق معه. ولا تُلغِ علامة الخطر التي ظهرت في التاريخ المرضي نتيجةُ فحص لاحق."},"questions":[{"level":"أساسي","q":"ماذا تسأل أولًا وتسجّله بكلمات المريض نفسه؟","options":["الأمراض السابقة","الشكوى الرئيسية","التاريخ العائلي","الأدوية"],"answer":1,"exp":"الشكوى الرئيسية هي أكثر ما يزعج المريض؛ ونسجّلها دون تفسير، بكلماته هو."},{"level":"أساسي","q":"بأي طريقة تطلب من المريض أن يحدد شدة الألم برقم بين 0 و10؟","options":["MMT","ROM","NRS","ADL"],"answer":2,"exp":"يعبّر مقياس التقييم الرقمي (NRS) عن شدة الألم برقم بين 0 و10."},{"level":"متوسط","q":"أي سؤال مفتوح؟","options":["«هل يؤلمك في الجهة اليمنى؟»","«هل يؤلمك ليلًا؟»","«هل تتناول أدوية؟»","«متى يظهر الألم عادةً؟»"],"answer":3,"exp":"لا يمكن الإجابة عن السؤال المفتوح بنعم أو لا، لذا تحصل على معلومات أكثر من المريض."},{"level":"متوسط","q":"أي معلومة يجب أن توضحها خاصةً في التاريخ المرضي لأنها تستلزم الحذر في العلاج؟","options":["تناول مضادات التخثر","اليد المسيطرة","وسيلة الذهاب إلى العمل","الهوايات"],"answer":0,"exp":"مضادات التخثر تحمل خطر النزف والكدمات، لذا تستلزم الحذر، مثلًا في التقنيات اليدوية."},{"level":"سريري","q":"مريض بألم أسفل الظهر: «لا أستطيع النوم ليلًا من الألم، ونقص وزني 5 كيلوغرامات». ما التصرف الأنسب؟","options":["أبدأ العلاج بالحركة فورًا","أتابع المسار مع العلاج الحراري","أبلغ الطبيب وأنسّق معه","أنتظر حتى الجلسة التالية"],"answer":2,"exp":"الألم الليلي الذي لا يخف بالراحة ونقص الوزن غير المبرر علامتان حمراوان؛ نسّق مع الطبيب قبل العلاج."},{"level":"سريري","q":"امرأة عمرها 70 عامًا مصابة بهشاشة العظام. منذ سقوطها يؤلمها الورك ولا تستطيع المشي. بماذا تفكر أولًا؟","options":["ألم ناتج عن ضعف عضلي","احتمال وجود كسر","تفاقم الفُصال العظمي","عوامل نفسية"],"answer":1,"exp":"في هشاشة العظام، عند وجود ألم وعجز عن المشي بعد السقوط فكّر في الكسر، والفحص الطبي هو الأولوية."}],"seccion":"الأساسيات","grupo":"التقييم","icono":"📋","mapa":"img/mapas/t05.jpg","fichas":[],"secuencias":[]},"6":{"id":6,"title":"العلامات الحمراء","lead":"العلامات الحمراء إشارات تحذيرية قد تدل على مرض خطير خفي. إذا لاحظت إحداها، نسّق مع الطبيب قبل متابعة العلاج الطبيعي.","sheet":{"kind":"basics","items":[{"h":"التعريف","t":"علامات تشير إلى حالة مرضية عاجلة (ورم، عدوى، كسر، متلازمة ذيل الفرس). وزنها أقل منفردة، وأكبر عندما تجتمع."},{"h":"الورم","t":"اسأل عن سابقة مرض ورمي، ونقص الوزن غير المبرر، والألم الليلي الذي لا يخف بالراحة. وخذ في الاعتبار العمر والحالة العامة أيضًا."},{"h":"العدوى","t":"انتبه لألم الظهر وأسفل الظهر المصحوب بحمى، وحالة كبت المناعة، والعدوى الحديثة أو الإجراء الجراحي التداخلي الحديث."},{"h":"الكسر","t":"فكّر في الكسر بعد إصابة قوية، أو عند الألم بعد سقوط بسيط في حالة هشاشة العظام. واسأل أيضًا عن تناول الستيرويدات لفترة طويلة."},{"h":"متلازمة ذيل الفرس","t":"اضطراب المثانة والمستقيم وفقدان الإحساس في منطقة السرج وضعف الطرف السفلي المتزايد حالة عاجلة: إحالة فورية للفحص الطبي."},{"h":"التصرف","t":"وثّق النتيجة والمسار، وأبلغ الطبيب ونسّق معه. لا تُخِف المريض؛ اشرح له بهدوء لماذا يلزم الفحص الطبي."}]},"keypoints":["الألم الليلي الذي لا يخف بالراحة علامة تحذيرية","نقص الوزن غير المبرر قد يدل على ورم","اضطراب المثانة والمستقيم وفقدان إحساس السرج: عاجل","عند الإصابة أو هشاشة العظام فكّر في الكسر","عند وجود علامة حمراء نسّق مع الطبيب قبل العلاج"],"case":{"text":"امرأة عمرها 45 عامًا تعاني ألمًا أسفل الظهر وألمًا في الطرف السفلي الأيمن. تقول إنها منذ صباح اليوم تتبول بصعوبة، وتشعر بخدر حول فتحة الشرج.","answer":"اضطراب المثانة والمستقيم واضطراب الإحساس في منطقة السرج يشيران إلى متلازمة ذيل الفرس. لا تتابع الفحص أو التمارين، وأبلغ الطبيب فورًا: إحالة فورية للفحص الطبي. يجب تجنب موقف «ننتظر ونراقب» هنا."},"questions":[{"level":"أساسي","q":"أي مما يلي علامة حمراء في ألم الظهر وأسفل الظهر؟","options":["ألم أسفل الظهر يزداد بالحركة","نقص الوزن غير المبرر","ألم يزداد بالجلوس الطويل","ألم العضلات بعد التمرين"],"answer":1,"exp":"نقص الوزن غير المبرر من العلامات الحمراء، وقد يدل على مرض ورمي."},{"level":"أساسي","q":"ما التصرف الصحيح عند ملاحظة علامة حمراء؟","options":["أتابع بشدة أقل","أنتقل إلى العلاج الفيزيائي","أنتظر حتى الجلسة التالية","أنسّق مع الطبيب قبل العلاج"],"answer":3,"exp":"عند وجود علامة حمراء، نسّق مع الطبيب قبل متابعة العلاج الطبيعي."},{"level":"متوسط","q":"أي زوج من النتائج يشير إلى متلازمة ذيل الفرس؟","options":["اضطراب المثانة والمستقيم وفقدان إحساس السرج","ألم الرقبة وتيبس الكتف","تورم الركبة وألم عند صعود الدرج","ألم الكتف الليلي وصعوبة الرفع"],"answer":0,"exp":"اضطراب المثانة والمستقيم وفقدان الإحساس في منطقة السرج (العجان وحول فتحة الشرج) علامة عاجلة على انضغاط ذيل الفرس."},{"level":"متوسط","q":"في أي حالة تفكر في الكسر أكثر من غيرها؟","options":["شد أسفل الظهر بعد عمل مكتبي","ألم العضلات بعد التمرين","ألم ظهر بعد سقوط لمريض بهشاشة العظام","تيبس الركبة في الأيام الباردة"],"answer":2,"exp":"في هشاشة العظام قد ينكسر العظم بقوة بسيطة، لذا فكّر في الكسر عند الألم بعد السقوط."},{"level":"سريري","q":"مريض بألم أسفل الظهر: «منذ صباح اليوم أتبول بصعوبة، وأشعر بخدر حول فتحة الشرج». ما التصرف؟","options":["أُكمل الفحص","أبدأ تمارين الجذع","أبلغ الطبيب فورًا","أراقب المسار أسبوعًا"],"answer":2,"exp":"اضطراب المثانة والمستقيم واضطراب إحساس السرج يشيران إلى متلازمة ذيل الفرس: إحالة فورية للفحص الطبي."},{"level":"سريري","q":"رجل عمره 68 عامًا لديه سابقة ورمية. منذ شهر يعاني ألم ظهر ليليًا لا يخف بالراحة. ما تقييمك؟","options":["ألم ناتج عن القوام","علامة تستلزم التنسيق مع الطبيب","ألم يتحسن بالتقوية","ألم يمكن متابعته بالعلاج الحراري"],"answer":1,"exp":"السابقة الورمية مع ألم ليلي لا يخف بالراحة لا تستبعدان النقائل، لذا يلزم التنسيق مع الطبيب."}],"seccion":"الأساسيات","grupo":"التقييم","icono":"📋","mapa":"img/mapas/t06.jpg","fichas":[],"secuencias":[]},"7":{"id":7,"title":"تقييم القوام","lead":"في تقييم القوام نلاحظ اصطفاف الجسم وقوفًا وجلوسًا، ونبحث عن مؤشرات للمشكلة. ويجب دائمًا تأكيد علاقتها بالأعراض بفحوص أخرى.","sheet":{"kind":"basics","items":[{"h":"الهدف","t":"نقيّم انحرافات القوام، ونضع فرضية عن علاقتها بقِصَر العضلات وضعفها وبالألم."},{"h":"المرجع في المنظر الجانبي","t":"في الوقوف المثالي يمر خط الثقل بشحمة الأذن والأخرم والمدور الكبير والجزء الأمامي من مفصل الركبة (خلف الرضفة) وأمام الكعب الوحشي."},{"h":"المنظر الخلفي","t":"لاحظ ميل الرأس وارتفاع الكتفين والحوض والانحراف الجانبي للعمود الفقري وعدم تناظر الطرفين السفليين. وعند الحاجة تحقق في وضع الانحناء للأمام أيضًا."},{"h":"أنماط القوام الخاطئة","t":"منها الظهر المستدير، وتقدّم الرأس، والقوام مع زيادة ميل الحوض والتقعر القطني، والظهر المسطح. قيّمها مع قِصَر العضلات المعنية وضعفها."},{"h":"التفسير","t":"لدى كثيرين انحرافات في القوام دون أعراض، لذا فالنتيجة وحدها لا تثبت سبب الألم. أكّدها بفحص مدى الحركة والقوة العضلية."},{"h":"التوثيق","t":"سجّل اتجاه الملاحظة ووضع الجسم ومواضع النقاط المرجعية. وعند التصوير التقط الصور دائمًا في الظروف نفسها لتسهل المقارنة."}]},"keypoints":["لاحظ من الجانب والخلف والأمام","يمر خط الثقل بشحمة الأذن والأخرم والمدور الكبير","من الخلف لاحظ فرق ارتفاع الكتفين والحوض بين الجهتين","حدبة الأضلاع عند الانحناء للأمام تدل على جنف بنيوي","لا تحدد سبب الألم بناءً على القوام"],"case":{"text":"امرأة عمرها 30 عامًا تعمل في مكتب. تعاني ألمًا في الرقبة، ومن المنظر الجانبي تقع شحمة الأذن بوضوح أمام الأخرم.","answer":"هذا تقدّم في وضع الرأس. لكن لا تحدد السبب من القوام: افحص مدى حركة الرقبة والحركات المثيرة للعرض والعلامات العصبية (خدر، ضعف). عند وجود عرض عصبي نسّق مع الطبيب."},"questions":[{"level":"أساسي","q":"في الوقوف المثالي، أين يمر خط الثقل من المنظر الجانبي؟","options":["بطرف الأنف","بالزاوية السفلية للوح الكتف","بشحمة الأذن","بالحافة الخلفية لعظم العقب"],"answer":2,"exp":"في الوضع المثالي يمر خط الثقل بشحمة الأذن والأخرم والمدور الكبير والجزء الأمامي من الركبة وأمام الكعب الوحشي."},{"level":"أساسي","q":"ماذا تفحص أساسًا في المنظر الخلفي؟","options":["تقدّم وضع الرأس","فرق ارتفاع الكتفين والحوض","مقدار التقعر القطني","فرط بسط الركبة"],"answer":1,"exp":"من الخلف نلاحظ الفروق بين الجهتين: ارتفاع الكتفين والحوض والانحراف الجانبي للعمود الفقري."},{"level":"متوسط","q":"في الوقوف المثالي، ما الصحيح بشأن خط الثقل في المنظر الجانبي؟","options":["يمر خلف الكعب الوحشي","يمر خلف مفصل الركبة","يمر بالحافة الإنسية للوح الكتف","يمر بالمدور الكبير"],"answer":3,"exp":"يمر خط الثقل بالمدور الكبير والجزء الأمامي من مفصل الركبة وأمام الكعب الوحشي."},{"level":"متوسط","q":"ما التفسير الصحيح لتقييم القوام؟","options":["الانحراف هو سبب الألم","أؤكد العلاقة بفحص آخر","تكفي الملاحظة من اتجاه واحد","ألتقط الصور دائمًا في ظروف مختلفة"],"answer":1,"exp":"انحرافات القوام موجودة أيضًا لدى أشخاص بلا أعراض، لذا أكّد العلاقة بفحص مدى الحركة والقوة العضلية."},{"level":"سريري","q":"لدى مريض بألم الرقبة تقع شحمة الأذن بوضوح أمام الأخرم. ما الخطوة التالية الأنسب؟","options":["أفحص مدى حركة الرقبة والعلامات العصبية","أكتفي بنصائح لتصحيح القوام","أطبّق الشد فورًا","أكتفي بمراقبة المسار"],"answer":0,"exp":"تقدّم وضع الرأس مجرد مؤشر. افحص مدى الحركة والعلامات العصبية، وقيّم علاقته بالأعراض."},{"level":"سريري","q":"من الخلف يظهر فرق في ارتفاع الكتفين والحوض، وعند الانحناء للأمام حدبة أضلاع في جهة واحدة. بماذا تفكر؟","options":["تقدّم وضع الرأس","الظهر المستدير","جنف بنيوي","الظهر المسطح"],"answer":2,"exp":"حدبة الأضلاع الظاهرة عند الانحناء للأمام تدل على جنف بنيوي مصحوب بدوران الفقرات؛ ويلزم فحص طبي."}],"seccion":"الأساسيات","grupo":"التقييم","icono":"📋","mapa":"img/mapas/t07.jpg","fichas":[],"secuencias":[]},"8":{"id":8,"title":"تحليل المشي","lead":"في تحليل المشي نلاحظ حركات المفاصل وعمل العضلات في كل مرحلة من دورة المشي، ونحدد المشكلة. وهذا يوجّه الوقاية من السقوط وتحسين الحركة.","sheet":{"kind":"basics","items":[{"h":"دورة المشي","t":"تمتد الدورة من التلامس الأولي لإحدى القدمين حتى التلامس التالي للقدم نفسها. وتنقسم إلى مرحلة ارتكاز ومرحلة تأرجح، وتتضمن فترتي ارتكاز مزدوج."},{"h":"المراحل","t":"الارتكاز: التلامس الأولي، تحمّل الوزن، منتصف الارتكاز، نهاية الارتكاز، ما قبل التأرجح. التأرجح: التأرجح المبكر، منتصف التأرجح، التأرجح المتأخر."},{"h":"خطوات الملاحظة","t":"لاحظ من الأمام والخلف والجانب، مع التركيز على مفصل واحد أو مرحلة واحدة في كل مرة. سجّل أيضًا السرعة وطول الخطوة والإيقاع والأداة المساعدة."},{"h":"أنماط المشي المرضية","t":"مشية ترندلنبرغ (العضلة الألوية الوسطى)، والمشية الخطوية (steppage) لتعويض هبوط القدم، والمشية الدائرية، وتجمّد بدء المشي (freezing)، والمشية بخطوات قصيرة."},{"h":"عمل العضلات","t":"عند تحمّل الوزن تكبح العضلة رباعية الرؤوس ثني الركبة، والعضلة الظنبوبية الأمامية هبوط القدم، بانقباض لامركزي. وفي نهاية الارتكاز تعمل العضلة ثلاثية الرؤوس الربلية."},{"h":"الاختبارات القابلة للقياس","t":"باختبار المشي 10 أمتار واختبار TUG يمكنك قياس السرعة والقدرة على الحركة كميًا. ومع الملاحظة تقيّم أيضًا خطر السقوط."}]},"keypoints":["الدورة: من التلامس حتى التلامس التالي للقدم نفسها","الارتكاز نحو 60%، والتأرجح نحو 40%","لاحظ من ثلاثة اتجاهات، ونقطة واحدة في كل مرة","في مشية ترندلنبرغ فكّر في العضلة الألوية الوسطى","المشية الخطوية تعويض لهبوط القدم (ضعف الظنبوبية الأمامية)"],"case":{"text":"رجل عمره 60 عامًا مصاب بشلل العصب الشظوي. في مرحلة التأرجح يثني الورك والركبة بشدة ويرفع قدمه عاليًا عند الخطو. ويتعثر بشكل متزايد.","answer":"هذه مشية خطوية (steppage) تعوّض هبوط القدم. افحص قوة العطف الظهري والإحساس وخطر السقوط. وناقش الجبيرة مع الطبيب وأخصائي الأجهزة التقويمية، ولا تقرر وحدك."},"questions":[{"level":"أساسي","q":"كم تشكّل مرحلة الارتكاز تقريبًا من دورة المشي؟","options":["نحو 40%","نحو 50%","نحو 60%","نحو 80%"],"answer":2,"exp":"في المشي الطبيعي تشكّل مرحلة الارتكاز نحو 60% ومرحلة التأرجح نحو 40%."},{"level":"أساسي","q":"في أي مرحلة يُحمل وزن الجسم على ساق واحدة ويكون مركز الثقل في أعلى نقطة؟","options":["التلامس الأولي","منتصف الارتكاز","ما قبل التأرجح","منتصف التأرجح"],"answer":1,"exp":"في منتصف الارتكاز يمر الجسم فوق ساق الارتكاز، وعندها يكون مركز الثقل في أعلى نقطة."},{"level":"متوسط","q":"أي عضلة تكبح ثني الركبة بانقباض لامركزي عند تحمّل الوزن؟","options":["العضلة رباعية الرؤوس الفخذية","عضلات أوتار الركبة الخلفية","العضلة الحرقفية القطنية","العضلة ثلاثية الرؤوس الربلية"],"answer":0,"exp":"عند تحمّل الوزن تنثني الركبة قليلًا لامتصاص الصدمة، وتكبح ذلك العضلة رباعية الرؤوس بانقباض لامركزي."},{"level":"متوسط","q":"ضعف أي عضلة تشك فيه في مشية ترندلنبرغ؟","options":["العضلة الألوية الكبرى","العضلة رباعية الرؤوس الفخذية","العضلة الظنبوبية الأمامية","العضلة الألوية الوسطى"],"answer":3,"exp":"عند ضعف العضلة الألوية الوسطى يهبط الحوض في جهة الساق المتأرجحة أثناء الارتكاز: علامة ترندلنبرغ."},{"level":"سريري","q":"في مرحلة التأرجح يثني الورك والركبة أكثر من اللازم ويرفع قدمه عاليًا. ما السبب المحتمل؟","options":["ضعف العضلة رباعية الرؤوس","ضعف العضلة الظنبوبية الأمامية","ضعف العضلة الألوية الوسطى","ضعف العضلة الألوية الكبرى"],"answer":1,"exp":"بسبب ضعف العضلة الظنبوبية الأمامية تهبط القدم؛ ولكي لا تعلق الأصابع بالأرض يرفعها عاليًا: مشية خطوية."},{"level":"سريري","q":"لدى مريض باركنسون، عند بدء المشي والالتفاف تبدو القدم كأنها ملتصقة بالأرض فلا تنطلق. ما هذا؟","options":["المشية الدائرية","المشية الخطوية","تجمّد بدء المشي (freezing)","مشية البطة"],"answer":2,"exp":"التجمّد سمة من سمات مرض باركنسون؛ ويظهر أساسًا عند بدء المشي والالتفاف وفي الأماكن الضيقة."}],"seccion":"الأساسيات","grupo":"التقييم","icono":"📋","mapa":"img/mapas/t08.jpg","fichas":[],"secuencias":[]},"9":{"id":9,"title":"الفحص العصبي","lead":"في الفحص العصبي نفحص الإحساس والقوة العضلية والمنعكسات لكل قطعة عصبية، ونستنتج موضع الإصابة ومستواها. وهو ضروري أيضًا للكشف المبكر عن الأعراض العصبية المتفاقمة.","sheet":{"kind":"basics","items":[{"h":"الهدف","t":"بتقييم نتائج الإحساس والقوة العضلية والمنعكسات معًا نحدد هل الإصابة في عصب طرفي أو جذر عصبي أو الحبل الشوكي أو الدماغ."},{"h":"فحص الإحساس","t":"افحص اللمس والإحساس بالألم والحرارة والوضع والاهتزاز، وقارن الجهتين على امتداد القطاعات الجلدية، وكذلك الجزء القريب بالبعيد."},{"h":"العضلات الدالة","t":"C5: تبعيد الكتف؛ C6: العطف الظهري للرسغ (بسط)؛ C7: بسط المرفق؛ L4: العطف الظهري للكاحل؛ L5: بسط إصبع القدم الكبير؛ S1: العطف الأخمصي للكاحل."},{"h":"المنعكسات العميقة","t":"المنعكسات الأساسية: منعكس ذات الرأسين (C5)، والمنعكس العضدي الكعبري (C6)، ومنعكس ثلاثية الرؤوس (C7)، والمنعكس الرضفي (L4)، ومنعكس أكيلس (S1)."},{"h":"العصبون العلوي والسفلي","t":"في إصابة العصبون الحركي العلوي تكون المنعكسات الوترية زائدة مع منعكسات مرضية، وفي إصابة السفلي تكون المنعكسات ضعيفة أو غائبة مع ضمور عضلي."},{"h":"تحذير","t":"عند تدهور سريع في القوة العضلية أو اضطراب إحساس منتشر أو اضطراب المثانة والمستقيم: إحالة فورية للفحص الطبي. ووثّق النتائج مع متابعتها زمنيًا."}]},"keypoints":["قارن الإحساس والقوة والمنعكسات دائمًا بين الجهتين","المنعكس الرضفي: L4، ومنعكس أكيلس: S1","قيّم L5 بقوة بسط إصبع القدم الكبير وبالإحساس","منعكس زائد ومنعكس مرضي: العصبون الحركي العلوي","عند ضعف عضلي متفاقم أبلغ الطبيب فورًا"],"case":{"text":"رجل عمره 50 عامًا يعاني ألمًا أسفل الظهر وخدرًا من الجانب الوحشي للساق اليمنى حتى ظهر القدم. بسط إصبع القدم الكبير ضعيف في اليمين، ولا يوجد فرق بين الجهتين في المنعكس الرضفي ومنعكس أكيلس.","answer":"الأرجح إصابة الجذر العصبي L5. ليس لـ L5 منعكس وتري مميز، لذا تعتمد على الإحساس وقوة بسط إصبع القدم الكبير. عند تدهور القوة العضلية أو اضطراب المثانة والمستقيم أبلغ الطبيب فورًا."},"questions":[{"level":"أساسي","q":"أي منعكس مرضي يدل على إصابة العصبون الحركي العلوي؟","options":["المنعكس الرضفي","منعكس جلد البطن","منعكس بابنسكي","منعكس القرنية"],"answer":2,"exp":"منعكس بابنسكي منعكس مرضي: عند تنبيه باطن القدم يتجه إصبع القدم الكبير إلى العطف الظهري؛ ويدل على إصابة العصبون الحركي العلوي."},{"level":"أساسي","q":"في أي فحص تقارن الجهتين على امتداد القطاعات الجلدية؟","options":["المنعكسات الوترية","فحص الإحساس","MMT","قياس مدى الحركة"],"answer":1,"exp":"القطاع الجلدي هو منطقة الجلد التي تعصّبها قطعة عصبية واحدة؛ وفي فحص الإحساس نقارن بين الجهتين ومن القريب إلى البعيد."},{"level":"متوسط","q":"أي قطعة عصبية يعكسها منعكس أكيلس أساسًا؟","options":["L3","L4","L5","S1"],"answer":3,"exp":"يعكس منعكس أكيلس أساسًا القطعة S1، والمنعكس الرضفي أساسًا القطعة L4."},{"level":"متوسط","q":"ما النتيجة المميزة لإصابة العصبون الحركي السفلي؟","options":["منعكسات وترية زائدة","منعكس مرضي إيجابي","ضمور عضلي","تشنج (spasticity)"],"answer":2,"exp":"في إصابة العصبون الحركي السفلي تظهر منعكسات وترية ضعيفة أو غائبة وضمور عضلي ونقص في التوتر العضلي."},{"level":"سريري","q":"خدر من الجانب الوحشي للساق حتى ظهر القدم، وضعف بسط إصبع القدم الكبير، ولا فرق في المنعكسات. ما مستوى الإصابة؟","options":["L3","L4","L5","S1"],"answer":2,"exp":"الإحساس من الجانب الوحشي للساق حتى ظهر القدم وبسط إصبع القدم الكبير نتيجة خاصة بـ L5. وليس لـ L5 منعكس وتري مميز."},{"level":"سريري","q":"مع ألم الرقبة وخدر اليدين كلتيهما، المنعكسات الوترية في الطرف السفلي زائدة وعلامة بابنسكي إيجابية. بماذا تفكر؟","options":["اعتلال النخاع العنقي (myelopathy)","إصابة جذر عصبي واحد","متلازمة النفق الرسغي","ألم عضلي لفافي"],"answer":0,"exp":"المنعكسات الزائدة والمنعكس المرضي في الطرف السفلي تدل على إصابة العصبون الحركي العلوي؛ فكّر في انضغاط الحبل الشوكي العنقي وأحِل المريض إلى الطبيب."}],"seccion":"الأساسيات","grupo":"التقييم","icono":"📋","mapa":"img/mapas/t09.jpg","fichas":[],"secuencias":[]},"10":{"id":10,"title":"الكفة المدورة","lead":"الكفة المدورة أوتار أربع عضلات تثبّت مفصل الكتف. وتمييز العضلة المصابة بالاختبارات هو نقطة انطلاق الفحص والعلاج الطبيعي.","sheet":{"kind":"tests","tests":[{"name":"اختبار جوب","alias":"اختبار العلبة الفارغة","steps":"يحمل المريض ذراعه في مستوى لوح الكتف بتبعيد 90° ودوران داخلي والإبهام للأسفل؛ ويطبّق الفاحص مقاومة من الأعلى إلى الأسفل.","positive":"ألم أو ضعف: لا يستطيع تثبيت الذراع ضد المقاومة","tissue":"العضلة فوق الشوكة (supraspinatus)","point":"سجّل الألم والضعف كلًا على حدة. وقد يسبب الانحشار أيضًا ألمًا في هذا الاختبار."},{"name":"الدوران الخارجي ضد مقاومة","alias":"","steps":"المرفق مثني 90° والعضد متدلٍّ بجانب الجسم، يدير المريض للخارج؛ ويطبّق الفاحص على الساعد مقاومة نحو الداخل.","positive":"ألم في الدوران الخارجي أو قوة أقل بوضوح من الجهة السليمة","tissue":"العضلة تحت الشوكة والعضلة المدورة الصغرى","point":"إذا لم يستطع تثبيت الدوران الخارجي المضبوط سلبيًا (تأخر الدوران الخارجي)، فكّر في تمزق كبير."},{"name":"اختبار الرفع عن الظهر","alias":"اختبار غيربر (lift-off)","steps":"يستقر ظهر يد المريض على منطقة أسفل الظهر؛ اطلب منه أن يرفع يده للخلف بعيدًا عن ظهره.","positive":"لا يستطيع رفع يده عن ظهره، أو يظهر ألم","tissue":"العضلة تحت الكتف (subscapularis)","point":"إذا لم تصل اليد خلف الظهر بسبب نقص مدى الدوران الداخلي، فاستبدله باختبار الضغط على البطن."},{"name":"اختبار سقوط الذراع","alias":"","steps":"يرفع الفاحص الذراع سلبيًا حتى تبعيد 90° تقريبًا، ثم يُنزلها المريض ببطء.","positive":"لا يستطيع تثبيتها في منتصف الطريق فتسقط الذراع، أو ألم شديد","tissue":"تمزق الكفة المدورة (خاصة فوق الشوكة)","point":"علامة تشير إلى تمزق كبير. لا تشخّص به وحده؛ قارنه باختبارات أخرى وبالتصوير."}]},"keypoints":["سجّل الألم والضعف كلًا على حدة، وقارن دائمًا بالجهة السليمة","اختبار جوب في مستوى لوح الكتف والإبهام للأسفل يفحص العضلة فوق الشوكة","الدوران الخارجي ضد مقاومة: تحت الشوكة والمدورة الصغرى؛ الرفع: تحت الكتف","لا تستنتج حكمًا نهائيًا من اختبار واحد؛ اجمع النتائج","إذا عجز فجأة عن رفع الذراع بعد إصابة، أحِله للفحص الطبي"],"case":{"text":"رجل عمره 58 عامًا. سقط واستند على يده اليمنى، ومنذ ذلك الحين لا يستطيع رفع كتفه الأيمن. مدى الحركة السلبي محفوظ تقريبًا، والرفع الإيجابي صعب. اختبار جوب: ضعف؛ اختبار سقوط الذراع إيجابي.","answer":"بما أن مدى الحركة السلبي محفوظ والحركة الإيجابية وحدها صعبة، نفكر في تمزق الكفة المدورة لا في التيبس. لا تشخّص بناءً على الاختبارات؛ أحِله للفحص الطبي والتصوير. وتجنب تكرار تمارين المقاومة القوية المثيرة للألم."},"questions":[{"level":"أساسي","q":"أي عضلة يفحصها أساسًا اختبار جوب (90° في مستوى لوح الكتف، والإبهام للأسفل)؟","options":["العضلة فوق الشوكة","العضلة تحت الشوكة","العضلة تحت الكتف","العضلة المدورة الصغرى"],"answer":0,"exp":"بالمقاومة في تبعيد 90° في مستوى لوح الكتف والإبهام للأسفل نفحص العضلة فوق الشوكة."},{"level":"أساسي","q":"أي عضلة يفحصها اختبار غيربر للرفع عن الظهر، حيث يُرفع ظهر اليد الموضوع على أسفل الظهر؟","options":["العضلة المدورة الكبرى","العضلة فوق الشوكة","العضلة تحت الكتف","العضلة الدالية"],"answer":2,"exp":"رفع اليد عن الظهر دوران داخلي، لذا يفحص العضلة الرئيسية للدوران الداخلي، أي العضلة تحت الكتف."},{"level":"متوسط","q":"ماذا يفحص الدوران الخارجي ضد مقاومة والمرفق مثني 90° والعضد متدلٍّ؟","options":["العضلة فوق الشوكة فقط","تحت الشوكة والمدورة الصغرى","العضلة تحت الكتف","الرأس الطويل للعضلة ذات الرأسين"],"answer":1,"exp":"يُظهر الدوران الخارجي ضد مقاومة ألم وضعف عضلات الدوران الخارجي، أي العضلة تحت الشوكة والمدورة الصغرى."},{"level":"متوسط","q":"علامَ يدل اختبار سقوط الذراع الإيجابي أكثر من غيره؟","options":["عدم ثبات أمامي في الكتف","التهاب غمد وتر الرأس الطويل للعضلة ذات الرأسين","إصابة المفصل الأخرمي الترقوي","تمزق الكفة المدورة"],"answer":3,"exp":"إذا عجز المريض عن إنزال الذراع المرفوعة ببطء فسقطت، فهذا يدل على تمزق الكفة المدورة (خاصة فوق الشوكة)."},{"level":"سريري","q":"امرأة عمرها 62 عامًا. تستطيع وضع يدها خلف ظهرها، لكن لا تستطيع رفعها عنه. والدوران الخارجي ضد مقاومة طبيعي. أين الإصابة على الأرجح؟","options":["العضلة فوق الشوكة","العضلة تحت الكتف","العضلة تحت الشوكة","العضلة المدورة الصغرى"],"answer":1,"exp":"اختبار الرفع عن الظهر إيجابي والدوران الخارجي طبيعي. نفكر أساسًا في إصابة العضلة تحت الكتف المسؤولة عن الدوران الداخلي."},{"level":"سريري","q":"رجل عمره 65 عامًا يرفع كتفه بصعوبة. مدى الحركة السلبي محفوظ، ويوجد ضعف واضح في اختبار جوب. ما التصرف الأنسب؟","options":["البدء بتقوية بمقاومة قصوى","إعلام المريض وطلب فحص طبي","تكرار تمارين إطالة قوية","نصحه بالانتظار"],"answer":1,"exp":"هناك اشتباه في تمزق الكفة المدورة؛ ويلزم فحص طبي وتصوير للتشخيص ووضع الخطة. تجنب التحميل العالي."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"الكتف","icono":"💪","mapa":"img/mapas/t10.jpg","fichas":[{"nombre":"اختبار جوب","img":"img/fichas/jobe.jpg"}],"secuencias":[{"nombre":"اختبار جوب","rotulo":"يقيّم","texto":"العضلة فوق الشوكة (supraspinatus)","frames":["img/mov/teste-jobe-1.jpg","img/mov/teste-jobe-2.jpg","img/mov/teste-jobe-3.jpg"]}]},"11":{"id":11,"title":"الانحشار وعدم الثبات","lead":"الألم عند رفع الذراع يشير إلى انحشار تحت الأخرم، والإحساس بعدم الأمان عند الدوران الخارجي يشير إلى عدم ثبات أمامي. ومن المهم التمييز بين الألم والإحساس بعدم الأمان.","sheet":{"kind":"tests","tests":[{"name":"اختبار نير","alias":"علامة نير للانحشار","steps":"ثبّت لوح الكتف من الأعلى، وارفع الطرف العلوي سلبيًا إلى الأمام إلى أقصى حد والذراع في دوران داخلي.","positive":"ألم في الجزء الأمامي العلوي من الكتف عند الرفع","tissue":"الكفة المدورة والجراب تحت الأخرم","point":"تنضغط الحدبة الكبرى تحت الأخرم فتسبب الألم. والاختبار الإيجابي لا يحسم وجود تمزق."},{"name":"اختبار هوكينز-كينيدي","alias":"","steps":"الكتف والمرفق في ثني 90°؛ يدفع الفاحص الساعد للأسفل فيدير الكتف سلبيًا إلى الدوران الداخلي.","positive":"ألم عند الدوران الداخلي في الجزء الأمامي العلوي أو الجانبي من الكتف","tissue":"وتر فوق الشوكة والجراب تحت الأخرم","point":"قيّمه مع اختبار نير. وتحقق من مكان الألم وقابليته للتكرار."},{"name":"اختبار التوجس (apprehension)","alias":"اختبار التوجس الأمامي","steps":"في الاستلقاء على الظهر، الكتف في تبعيد 90° والمرفق مثني 90°؛ يدير الفاحص الكتف ببطء إلى الدوران الخارجي.","positive":"خوف من الخلع، وتوتر عضلي دفاعي","tissue":"المحفظة الأمامية والشفا لمفصل الكتف","point":"الحاسم هو الإحساس بعدم الأمان لا الألم. وبعد الخلع أجرِه ببطء ولطف."},{"name":"اختبار إعادة التموضع","alias":"","steps":"في وضع اختبار التوجس، ادفع رأس العضد من الأمام إلى الخلف وأجرِ الدوران الخارجي.","positive":"يقل الإحساس بعدم الأمان، ويمكن مواصلة الدوران الخارجي","tissue":"عدم الثبات الأمامي لمفصل الكتف","point":"أجرِه بعد اختبار التوجس؛ وتغيّر الإحساس بعدم الأمان يؤكد عدم الثبات الأمامي."}]},"keypoints":["اختبار نير وهوكينز-كينيدي يفحصان ألم الانحشار تحت الأخرم","في اختبارات عدم الثبات، ظهور عدم الأمان أهم من الألم","حتى الاختبار الإيجابي لا يبيّن وجود تمزق الكفة المدورة ولا حجمه","بعد الخلع أجرِ الدوران الخارجي ببطء ودون إجبار","قيّم التاريخ المرضي والاختبارات الأخرى والتصوير معًا"],"case":{"text":"لاعب رغبي عمره 19 عامًا. أثناء الالتحام أُجبرت ذراعه على التبعيد والدوران الخارجي؛ ومنذ ذلك الحين يشعر في الوضع نفسه أن كتفه «سيخرج». اختبار التوجس يثير عدم الأمان، واختبار إعادة التموضع يقلله.","answer":"نتائج تشير إلى عدم ثبات أمامي في الكتف؛ ميّزها عن ألم الانحشار. تجنب الحركات التي تُجبر التبعيد والدوران الخارجي؛ وبالاستناد إلى الفحص الطبي تقدّم بتثبيت الكفة المدورة والعضلات حول لوح الكتف."},"questions":[{"level":"أساسي","q":"أي بنية تنحشر غالبًا في الانحشار تحت الأخرم؟","options":["وتر العضلة ثلاثية الرؤوس العضدية","العضلة المدورة الكبرى","وتر العضلة فوق الشوكة","العضلة الظهرية العريضة"],"answer":2,"exp":"عند الرفع ينحشر وتر فوق الشوكة والجراب تحت الأخرم تحت الأخرم ويسببان الألم."},{"level":"أساسي","q":"ما الحركة التي تجريها للكتف في اختبار هوكينز-كينيدي؟","options":["دوران داخلي في ثني 90°","دوران خارجي والذراع متدلية","تبعيد أفقي","بسط"],"answer":0,"exp":"الدوران الداخلي السلبي من ثني الكتف والمرفق 90° يضغط الحدبة الكبرى تحت القوس الغرابي الأخرمي."},{"level":"متوسط","q":"ما النتيجة الإيجابية لاختبار التوجس؟","options":["ألم أمامي علوي في الكتف عند الرفع","خوف من الخلع","ألم عند ثني المرفق","سقوط الذراع"],"answer":1,"exp":"الخوف من الخلع أو التوتر العضلي الدفاعي في التبعيد مع الدوران الخارجي نتيجة إيجابية تدل على عدم ثبات أمامي."},{"level":"متوسط","q":"علامَ يدل نقص الإحساس بعدم الأمان في اختبار إعادة التموضع؟","options":["تمزق الكفة المدورة","إصابة المفصل الأخرمي الترقوي","الكتف المتجمد","عدم ثبات أمامي في الكتف"],"answer":3,"exp":"إذا قلّ عدم الأمان بدفع رأس العضد للخلف، فهذا يؤكد عدم الثبات الأمامي."},{"level":"سريري","q":"رجل عمره 45 عامًا يؤلمه كتفه من الأمام والأعلى عند العمل فوق الرأس. اختبار نير وهوكينز مؤلمان، والقوة محفوظة. ما الأرجح؟","options":["عدم ثبات أمامي","انحشار تحت الأخرم","اعتلال جذر عصبي عنقي","خلع أخرمي ترقوي"],"answer":1,"exp":"بناءً على الألم الأمامي العلوي عند الرفع والدوران الداخلي مع قوة محفوظة، فإن الانحشار تحت الأخرم هو الأرجح."},{"level":"سريري","q":"امرأة عمرها 20 عامًا تعرضت لخلع أمامي في الكتف مرتين. ما الأنسب عند إجراء اختبار التوجس؟","options":["الإدارة السريعة إلى أقصى دوران خارجي","التوقف فور ظهور عدم الأمان","مواصلة الدوران الخارجي حتى الألم","إجراؤه بحركة اندفاعية"],"answer":1,"exp":"الهدف هو رصد الإحساس بعدم الأمان، لذا توقف عند ظهوره. فالإجبار يحمل خطر تكرار الخلع."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"الكتف","icono":"💪","mapa":"img/mapas/t11.jpg","fichas":[{"nombre":"اختبار نير","img":"img/fichas/neer.jpg"},{"nombre":"اختبار هوكينز-كينيدي","img":"img/fichas/hawkins.jpg"}],"secuencias":[]},"12":{"id":12,"title":"العضلة ذات الرأسين والشفا الحقاني","lead":"يمر وتر الرأس الطويل للعضلة ذات الرأسين العضدية في التلم بين الحدبتين، ويرتكز على الشفا العلوي. ويُصاب كثيرًا في الرمي والسحب؛ لذا افحص الوتر والشفا كلًا على حدة.","sheet":{"kind":"tests","tests":[{"name":"اختبار سبيد","alias":"","steps":"المرفق مبسوط والساعد في استلقاء، يرفع المريض كتفه للأمام؛ ويطبّق الفاحص على الساعد مقاومة نحو الأسفل.","positive":"ألم في منطقة التلم بين الحدبتين","tissue":"وتر الرأس الطويل للعضلة ذات الرأسين العضدية","point":"قد تسبب إصابة الشفا العلوي ألمًا أيضًا. قيّمه مع نقطة الإيلام عند الضغط."},{"name":"اختبار ييرغاسون","alias":"","steps":"المرفق مثني 90° والساعد في كب، يقلب المريض الساعد إلى الاستلقاء ضد مقاومة الفاحص.","positive":"ألم في التلم بين الحدبتين، أو إحساس بانزلاق الوتر","tissue":"وتر الرأس الطويل والرباط العضدي المستعرض","point":"قد تصاحبه طقطقة عند خلع الوتر الجزئي. تحقق دائمًا من مكان الألم."},{"name":"اختبار أوبراين","alias":"اختبار الضغط الإيجابي","steps":"الكتف في ثني 90° وتقريب أفقي خفيف والإبهام للأسفل، طبّق مقاومة نحو الأسفل؛ ثم كرّر والكف للأعلى.","positive":"الإبهام للأسفل: ألم عميق أو طقطقة؛ الكف للأعلى: يخف","tissue":"الشفا العلوي والمفصل الأخرمي الترقوي","point":"الألم أعلى الكتف يشير إلى المفصل الأخرمي الترقوي، والألم العميق إلى الشفا. ميّز مكانه."},{"name":"اختبار الكرنك (crank)","alias":"","steps":"والكتف مرفوع بقوة، اضغط على امتداد المحور الطولي للعضد وأجرِ دورانًا داخليًا وخارجيًا.","positive":"إثارة ألم أو طقطقة (إحساس بالانحشار)","tissue":"الشفا الحقاني","point":"يصعب إثبات إصابة الشفا باختبار وحده؛ قيّمه مع التصوير."}]},"keypoints":["يمر وتر الرأس الطويل في التلم ويرتكز على الحديبة فوق الحقانية والشفا العلوي","اختبارا سبيد وييرغاسون يتحققان من ألم التلم بين الحدبتين","اختبار أوبراين يميّز بين الشفا والمفصل الأخرمي الترقوي حسب مكان الألم","سجّل أيضًا وجود طقطقة أو إحساس بالانحشار","لا تثبت إصابة الشفا بالاختبار وحده؛ قارنه بالتصوير"],"case":{"text":"لاعب بيسبول (رامٍ) عمره 22 عامًا. عند الرمي يشعر بألم عميق في الكتف وإحساس بالانحشار. اختبار أوبراين والإبهام للأسفل يسبب ألمًا عميقًا، ويخف والكف للأعلى. واختبار سبيد مؤلم أيضًا.","answer":"نشتبه في إصابة الشفا العلوي (SLAP). إذا كان الألم أعلى الكتف ففكّر في منشأ من المفصل الأخرمي الترقوي. لا تقرر وحدك استمرار الرمي؛ أحِله إلى الطبيب، واطلب منه تجنب حركة الرمي المثيرة للألم."},"questions":[{"level":"أساسي","q":"في أي تلم يمر وتر الرأس الطويل للعضلة ذات الرأسين العضدية؟","options":["التجويف الحقاني","التلم بين الحدبتين","تلم العصب الكعبري","الأخرم"],"answer":1,"exp":"يمر وتر الرأس الطويل إلى المفصل في التلم بين الحدبتين الواقع بين الحدبة الكبرى والصغرى لعظم العضد."},{"level":"أساسي","q":"إلى جانب الحديبة فوق الحقانية، على أي بنية يرتكز وتر الرأس الطويل؟","options":["الشفا العلوي","الرباط الحقاني العضدي السفلي","الرباط الأخرمي الترقوي","الرباط الغرابي الترقوي"],"answer":0,"exp":"يرتكز الرأس الطويل على الحديبة فوق الحقانية والشفا العلوي، لذا تجتمع إصابة الوتر والشفا كثيرًا."},{"level":"متوسط","q":"ضد أي حركة تطبّق المقاومة في اختبار ييرغاسون؟","options":["تبعيد الكتف","العطف الظهري للرسغ","استلقاء الساعد","بسط المرفق"],"answer":2,"exp":"مقاومة لاستلقاء الساعد مع ثني المرفق 90°؛ وألم التلم يشير إلى إصابة وتر الرأس الطويل."},{"level":"متوسط","q":"بماذا تفكر إذا سبّب اختبار أوبراين ألمًا أعلى الكتف؟","options":["إصابة الشفا العلوي","إصابة المفصل الأخرمي الترقوي","تمزق الكفة المدورة","عدم ثبات أمامي"],"answer":1,"exp":"الألم أعلى الكتف يشير إلى المفصل الأخرمي الترقوي، والألم العميق في الكتف إلى إصابة الشفا العلوي."},{"level":"سريري","q":"لاعب كرة طائرة عمره 25 عامًا. عند الضرب الساحق يشعر بألم عميق في الكتف وطقطقة؛ واختبار أوبراين يسبب ألمًا عميقًا. ما الأرجح؟","options":["إصابة المفصل الأخرمي الترقوي","الكتف المتجمد","داء الفقار العنقي","إصابة SLAP"],"answer":3,"exp":"ألم عميق وطقطقة في الحركات فوق الرأس، مع اختبار أوبراين إيجابي (ألم عميق): نشتبه في إصابة SLAP."},{"level":"سريري","q":"رجل عمره 40 عامًا سمع صوت تمزق في مقدمة العضد عند رفع شيء ثقيل، وانخفض بطن العضلة ذات الرأسين. ما أفضل تصرف؟","options":["تقوية بمقاومة قصوى","تكرار اختبار ييرغاسون","إحالته للفحص الطبي","تدفئة وانتظار"],"answer":2,"exp":"علامات تشير إلى تمزق وتر الرأس الطويل؛ ويلزم أولًا فحص طبي. تجنب الفحوص والتمارين التي تحمّل الوتر."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"الكتف","icono":"💪","mapa":"img/mapas/t12.jpg","fichas":[],"secuencias":[]},"13":{"id":13,"title":"المرفق","lead":"فكّر في ألم المرفق مقسّمًا: في الجانب الوحشي العضلات الباسطة، وفي الإنسي العضلات القابضة والأربطة، إضافة إلى العصب الزندي. واربط مكان الألم بالاختبار المناسب.","sheet":{"kind":"tests","tests":[{"name":"اختبار تومسن","alias":"","steps":"المرفق مبسوط والرسغ في عطف ظهري خفيف، يقبض المريض يده؛ ويدفع الفاحص ظهر اليد نحو العطف الراحي.","positive":"ألم حول اللقيمة الوحشية لعظم العضد","tissue":"منشأ العضلة الباسطة الكعبرية القصيرة للرسغ","point":"فحص التهاب اللقيمة الوحشية. اجمعه مع اختبار بسط الإصبع الوسطى واختبار الكرسي."},{"name":"اختبار بسط الإصبع الوسطى","alias":"","steps":"والمرفق مبسوط، يبسط المريض إصبعه الوسطى؛ ويدفع الفاحص السلامية القريبة نحو الجهة الراحية.","positive":"ألم حول اللقيمة الوحشية لعظم العضد","tissue":"منشأ ECRB والعضلة الباسطة للأصابع","point":"يكون إيجابيًا في التهاب اللقيمة الوحشية مثل اختبار تومسن. تحقق من مكان ظهور الألم."},{"name":"اختبار إجهاد الأروح","alias":"","steps":"والمرفق مثني قليلًا، ثبّت العضد وطبّق على الساعد حملًا باتجاه الأروح.","positive":"ألم إنسي في المرفق أو انفتاح أكبر من الجهة السليمة","tissue":"الرباط الجانبي الزندي (الرباط الإنسي)","point":"لفحص مرفق الرامي. قارن دائمًا بالجهة السليمة؛ وسجّل الألم والرخاوة كلًا على حدة."},{"name":"علامة تينيل (النفق المرفقي)","alias":"","steps":"انقر بلطف بطرف الإصبع أو بمطرقة المنعكسات على النفق المرفقي بين اللقيمة الإنسية والزج.","positive":"خدر ينتشر إلى الخنصر والجانب الزندي من البنصر","tissue":"العصب الزندي (النفق المرفقي)","point":"فحص متلازمة النفق المرفقي. قيّمه مع اختبار ثني المرفق وعلامة فرومان."}]},"keypoints":["عند ألم اللقيمة الوحشية فكّر في منشأ باسطات الرسغ والأصابع","أجرِ اختبار إجهاد الأروح في ثني خفيف، وقارن بالجهة السليمة","أعراض العصب الزندي: خدر الخنصر والجانب الزندي من البنصر","سجّل الألم والرخاوة (عدم الثبات) كلًا على حدة","عند خدر مستمر أو ضمور عضلات اليد أحِله إلى الطبيب"],"case":{"text":"امرأة عمرها 45 عامًا تعمل في مكتب. يؤلمها المرفق في الجانب الوحشي عند عصر المنشفة ورفع الحقيبة. اللقيمة الوحشية مؤلمة بالضغط، واختبار تومسن واختبار بسط الإصبع الوسطى يثيران الألم.","answer":"نتائج تشير إلى التهاب اللقيمة الوحشية لعظم العضد. لتتجنب تكرار حركات القبض المثيرة للألم، وعليك ضبط جرعة التحميل. وإذا صاحبه خدر أو تورم أو ألم ليلي شديد، ففكّر في مرض آخر وأحِلها إلى الطبيب."},"questions":[{"level":"أساسي","q":"أي مجموعة عضلية تنشأ من اللقيمة الوحشية لعظم العضد؟","options":["قابضات الرسغ","باسطات الرسغ","العضلة ذات الرأسين العضدية","العضلة الكابة المدورة"],"answer":1,"exp":"من اللقيمة الوحشية تنشأ باسطات الرسغ والأصابع، ومن الإنسية القابضات والعضلة الكابة المدورة."},{"level":"أساسي","q":"أي عصب يمر عبر النفق المرفقي؟","options":["العصب المتوسط","العصب الكعبري","العصب الزندي","العصب العضلي الجلدي"],"answer":2,"exp":"يمر العصب الزندي في النفق المرفقي خلف اللقيمة الإنسية، لذا يسبب النقر على الجانب الإنسي للمرفق خدرًا نحو الخنصر."},{"level":"متوسط","q":"ضد أي حركة تطبّق المقاومة في اختبار تومسن؟","options":["العطف الظهري للرسغ","العطف الراحي للرسغ","كب الساعد","ثني المرفق"],"answer":0,"exp":"المقاومة ضد العطف الظهري للرسغ تثير الألم حول اللقيمة الوحشية (منشأ الباسطات)."},{"level":"متوسط","q":"أي بنية يفحصها اختبار إجهاد الأروح أساسًا؟","options":["الرباط الجانبي الوحشي","الرباط الحلقي للكعبرة","رأس الكعبرة","الرباط الجانبي الإنسي"],"answer":3,"exp":"الحمل باتجاه الأروح على الساعد يشد الجانب الإنسي للمرفق، فيفحص ألم الرباط الجانبي الإنسي ورخاوته."},{"level":"سريري","q":"فتى عمره 14 عامًا يرمي في البيسبول. عند الرمي يشعر بألم إنسي في المرفق، واختبار إجهاد الأروح يسبب ألمًا إنسيًا. ما الأرجح؟","options":["التهاب اللقيمة الوحشية لعظم العضد","مرفق الرامي من النوع الإنسي","مرفق المربية","كسر رأس الكعبرة"],"answer":1,"exp":"تكرار حركة الرمي والألم الإنسي عند حمل الأروح يشيران إلى مرفق الرامي الإنسي (إصابة الرباط أو المشاشة)."},{"level":"سريري","q":"رجل عمره 50 عامًا. النقر على الجانب الإنسي للمرفق يسبب خدرًا يمتد إلى الخنصر، والحركات الدقيقة للأصابع صعبة أيضًا. ما أفضل تصرف؟","options":["إبقاء المرفق مثنيًا لفترة طويلة","مراقبة الخدر","إبلاغ الطبيب","تدليك قوي للجانب الإنسي للمرفق"],"answer":2,"exp":"إصابة العصب الزندي المصحوبة بنقص المهارة تستلزم فحصًا طبيًا. والثني المطوّل للمرفق والضغط يفاقمان الأعراض."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"المرفق والرسغ واليد","icono":"✋","mapa":"img/mapas/t13.jpg","fichas":[],"secuencias":[]},"14":{"id":14,"title":"الرسغ واليد","lead":"عند خدر اليد وألمها استنتج من التوزيع أي عصب أو وتر مصاب. ومتلازمة النفق الرسغي والتهاب غمد الوتر شائعان في الممارسة السريرية وفي الاختبارات النهائية والاختبار العملي (OSCE).","sheet":{"kind":"tests","tests":[{"name":"اختبار فالين","alias":"","steps":"يُلصق المريض ظهري يديه ويثبّت الرسغين في أقصى عطف راحي مدة من الوقت؛ لاحظ ظهور الخدر.","positive":"خدر من الإبهام حتى الجانب الكعبري من البنصر، أو ازدياده","tissue":"العصب المتوسط (النفق الرسغي)","point":"فحص متلازمة النفق الرسغي. تحقق هل يطابق الخدر منطقة العصب المتوسط."},{"name":"علامة تينيل (الرسغ)","alias":"","steps":"انقر بلطف بطرف الإصبع أو بمطرقة المنعكسات على النفق الرسغي في الجهة الراحية من الرسغ.","positive":"خدر ينتشر إلى أطراف الأصابع في منطقة العصب المتوسط","tissue":"العصب المتوسط (النفق الرسغي)","point":"يُستخدم أيضًا لتقدير موضع انضغاط العصب وتجدده. لا تنقر بقوة زائدة."},{"name":"اختبار فينكلستين","alias":"","steps":"يضم المريض إبهامه داخل قبضته (أو يمسك الفاحص الإبهام)، ثم تحرّك الرسغ سلبيًا إلى الانحراف الزندي.","positive":"ألم شديد في منطقة الناتئ الإبري للكعبرة","tissue":"مبعدة الإبهام الطويلة وباسطة الإبهام القصيرة","point":"فحص داء دي كيرفان. ونسخة القبضة تُسمى اختبار آيكهوف. قارن بالجهة السليمة."},{"name":"علامة فرومان","alias":"","steps":"يمسك المريض ورقة بين الإبهام والسبابة في كلتا اليدين، ويسحبها الفاحص.","positive":"ينثني المفصل بين السلاميات للإبهام ليحافظ على الورقة","tissue":"العصب الزندي (العضلة المقربة للإبهام)","point":"تعوّض العضلةُ القابضة الطويلة للإبهام التي يعصّبها العصب المتوسط ضعفَ العضلة المقربة للإبهام."}]},"keypoints":["ميّز العصب المتوسط والزندي والكعبري حسب توزيع الخدر","اختبار فالين وعلامة تينيل يفحصان العصب المتوسط في النفق الرسغي","اختبار فينكلستين لفحص التهاب غمد أوتار الإبهام","أجرِه في الجهتين، وقيّم بالمقارنة مع الجهة السليمة","عند ضمور الرانفة أو خدر مستمر أحِله إلى الطبيب"],"case":{"text":"امرأة عمرها 52 عامًا. عند الفجر يخدر إبهامها وسبابتها وإصبعها الوسطى، ويخف ذلك بهز اليد. اختبار فالين يثير الخدر في المكان نفسه، وعلامة تينيل فوق النفق الرسغي إيجابية أيضًا.","answer":"نشتبه في متلازمة النفق الرسغي. إذا امتد الخدر إلى الخنصر أو تغيّر بحركة الرقبة، ففكّر في مستوى آخر أيضًا. عند ضمور الرانفة أو الضعف أحِلها إلى الطبيب؛ وتجنب الضغط القوي على الرسغ."},"questions":[{"level":"أساسي","q":"أي عصب يمر عبر النفق الرسغي؟","options":["العصب الزندي","العصب المتوسط","العصب الكعبري","العصب العضلي الجلدي"],"answer":1,"exp":"يمر في النفق الرسغي أوتار قابضات الأصابع والعصب المتوسط؛ وانضغاطه هنا هو متلازمة النفق الرسغي."},{"level":"أساسي","q":"أين يظهر الألم في اختبار فينكلستين؟","options":["الناتئ الإبري للكعبرة","الناتئ الإبري للزند","العظم الحمصي","رأس عظم المشط الخامس"],"answer":0,"exp":"يظهر الألم عند الناتئ الإبري للكعبرة الذي تعبره أوتار الإبهام (مبعدة الإبهام الطويلة وباسطة الإبهام القصيرة)."},{"level":"متوسط","q":"أي عصب تفحصه علامة فرومان؟","options":["العصب المتوسط","العصب الكعبري","العصب الإبطي","العصب الزندي"],"answer":3,"exp":"إذا ضعفت العضلة المقربة للإبهام التي يعصّبها العصب الزندي، تعوّض القابضة الطويلة للإبهام فينثني المفصل بين السلاميات."},{"level":"متوسط","q":"ما النتيجة الإيجابية لاختبار فالين؟","options":["خدر الخنصر","ألم في ظهر اليد كله","خدر من الإصبع 1 حتى نصف الإصبع 4 الكعبري","إحساس بعدم ثبات الرسغ"],"answer":2,"exp":"العطف الراحي المستمر يرفع ضغط النفق، فيظهر خدر في منطقة العصب المتوسط (من الإبهام حتى النصف الكعبري للإصبع الرابعة)."},{"level":"سريري","q":"امرأة عمرها 30 عامًا. منذ الولادة يؤلمها جانب الإبهام من الرسغ عند رعاية الطفل؛ ويؤلمها مع ضم الإبهام في القبضة والانحراف الزندي. ما الأرجح؟","options":["متلازمة النفق الرسغي","إصابة TFCC","داء دي كيرفان","الإصبع الزنادية"],"answer":2,"exp":"الإفراط في استخدام الإبهام والألم عند الناتئ الإبري للكعبرة مع القبضة والانحراف الزندي يشيران إلى داء دي كيرفان."},{"level":"سريري","q":"رجل عمره 60 عامًا. يخدر خنصره والجانب الزندي من بنصره، وعند قرص الورقة ينثني المفصل بين السلاميات للإبهام. إصابة أي عصب تفكر فيها؟","options":["العصب المتوسط","العصب الكعبري","العصب بين العظمي الخلفي","العصب الزندي"],"answer":3,"exp":"خدر الخنصر والجانب الزندي من البنصر مع علامة فرومان الإيجابية يشيران إلى إصابة العصب الزندي."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"المرفق والرسغ واليد","icono":"✋","mapa":"img/mapas/t14.jpg","fichas":[{"nombre":"اختبار فالين","img":"img/fichas/phalen.jpg"},{"nombre":"اختبار فينكلستين","img":"img/fichas/finkelstein.jpg"},{"nombre":"علامة تينيل في الرسغ","img":"img/fichas/tinel-punho.jpg"}],"secuencias":[]},"15":{"id":15,"title":"العمود الفقري العنقي","lead":"قد يكون سبب الألم والخدر الممتدين من الرقبة إلى الذراع انضغاط جذر عصبي. تحقق بالاختبارات المثيرة والمخففة أيضًا هل العرض جذري.","sheet":{"kind":"tests","tests":[{"name":"اختبار سبورلينغ","alias":"اختبار ضغط الثقبة","steps":"في الجلوس تحني الرقبة نحو جهة الألم (مع بسط ودوران خفيفين)، ثم تضغط للأسفل عبر قمة الرأس.","positive":"إثارة ألم أو خدر يمتد إلى ذراع جهة الألم","tissue":"جذر عصبي عنقي (الثقبة بين الفقرية)","point":"إثارة ألم الرقبة وحده ليست نتيجة إيجابية. عند ألم شديد أو دوخة توقف فورًا."},{"name":"اختبار جاكسون","alias":"اختبار الضغط لجاكسون","steps":"في الجلوس ومع بسط خفيف للرقبة، تضغط للأسفل عبر قمة الرأس.","positive":"إثارة ألم أو خدر يمتد إلى الذراع","tissue":"جذر عصبي عنقي","point":"يستفيد من تضيّق الثقبة في البسط. اجمعه مع اختبار سبورلينغ."},{"name":"اختبار الإبعاد العنقي","alias":"اختبار الشد","steps":"في الجلوس، مع إسناد الرأس تحت الفك ومن مؤخرة الرأس، تسحب الرأس للأعلى ببطء.","positive":"يخف الألم أو الخدر الممتد إلى الذراع","tissue":"جذر عصبي عنقي (انضغاط الثقبة)","point":"إيجابي عند التخفيف. وإذا فاقم الشدُّ الأعراضَ ففكّر في سبب آخر وتوقف."},{"name":"اختبار تبعيد الكتف","alias":"علامة باكودي","steps":"في الجلوس يضع المريض يد جهة الألم على قمة رأسه؛ لاحظ تغيّر أعراض الذراع.","positive":"يخف الألم أو الخدر الممتد إلى الذراع","tissue":"جذر عصبي عنقي","point":"يقل شد الجذر العصبي فتخف الأعراض. وقد يتخذ المريض هذا الوضع من تلقاء نفسه."}]},"keypoints":["إثارة ألم أو خدر يمتد إلى الذراع تشير إلى عرض جذري","أجرِ اختبارات الضغط بلطف، وتوقف عند عرض شديد","تحقق أيضًا هل تخف الأعراض بالشد أو بتبعيد الكتف","قدّر المستوى من القطاعات الجلدية والقوة العضلية والمنعكسات الوترية","خدر اليدين معًا أو اضطراب المشي: اشتباه اعتلال النخاع، أحِله للطبيب"],"case":{"text":"رجل عمره 48 عامًا يعمل جالسًا. يعاني ألم الرقبة وخدرًا من الإبهام الأيمن حتى الجانب الكعبري من الساعد. اختبار سبورلينغ يثير الخدر في الذراع اليمنى، ويخف بسحب الرأس.","answer":"نشتبه في اعتلال جذر عصبي عنقي؛ ومن توزيع الخدر في منطقة C6. افحص أيضًا المنعكسات الوترية والقوة العضلية. إذا تدهورت مهارة اليدين أو وُجد اضطراب في المشي ففكّر في اعتلال النخاع وأحِله إلى الطبيب. وتجنب تكرار الضغط القوي."},"questions":[{"level":"أساسي","q":"في أي وضع للرقبة تضغط الرأس للأسفل في اختبار سبورلينغ؟","options":["انحناء جانبي نحو جهة الألم","انحناء جانبي نحو الجهة السليمة","ثني أقصى","وضع متوسط مع شد"],"answer":0,"exp":"بالانحناء نحو جهة الألم (مع بسط خفيف) تضيق الثقبة؛ وضغط الرأس يثير العرض الجذري."},{"level":"أساسي","q":"أي منطقة تضيق في بسط الرقبة والانحناء نحو جهة الألم فتضغط الجذر العصبي بسهولة؟","options":["الحافة الأمامية لجسم الفقرة","الثقبة بين الفقرية","المسافة بين النواتئ الشوكية","طرف الناتئ المستعرض"],"answer":1,"exp":"يخرج الجذر العصبي عبر الثقبة بين الفقرية، لذا فإن تضييقها بالبسط والانحناء الجانبي يضغطه بسهولة."},{"level":"متوسط","q":"ما النتيجة الإيجابية لاختبار الإبعاد العنقي؟","options":["ازدياد أعراض الذراع","ظهور دوخة","تخفيف أعراض الذراع","زيادة مدى حركة الرقبة"],"answer":2,"exp":"يوسّع الشد الثقبة ويقلل انضغاط الجذر العصبي؛ فإذا خف ألم الذراع أو خدرها كان الاختبار إيجابيًا."},{"level":"متوسط","q":"بأي نتيجة تعدّ اختبار سبورلينغ إيجابيًا؟","options":["ألم الرقبة فقط","إحساس بتيبس الكتف","شد عضلات الرقبة","ألم يمتد إلى ذراع جهة الألم"],"answer":3,"exp":"يكون إيجابيًا إذا أمكن إثارة ألم أو خدر يمتد إلى الذراع. أما ألم الرقبة الموضعي وحده فليس إيجابيًا."},{"level":"سريري","q":"امرأة عمرها 50 عامًا تعاني ألم الرقبة وخدر الإصبع الوسطى اليسرى. ومنعكس ثلاثية الرؤوس الأيسر ناقص. أي جذر عصبي تشتبه فيه؟","options":["C5","C6","C7","C8"],"answer":2,"exp":"اضطراب الإحساس في الإصبع الوسطى ونقص منعكس ثلاثية الرؤوس يشيران إلى إصابة الجذر العصبي C7."},{"level":"سريري","q":"رجل عمره 65 عامًا. تخدر يداه كلتاهما، ويزرّر ملابسه بصعوبة، وهو غير ثابت أثناء المشي. ما التصرف الأنسب؟","options":["إبلاغ الطبيب","شد قوي للرقبة","تكرار اختبار سبورلينغ","تصحيح يدوي للرقبة"],"answer":0,"exp":"نقص المهارة في الجهتين واضطراب المشي يشيران إلى اعتلال النخاع العنقي. تجنب الاختبارات المثيرة، وأحِله إلى الطبيب."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"العمود الفقري والحوض","icono":"🦴","mapa":"img/mapas/t15.jpg","fichas":[],"secuencias":[]},"16":{"id":16,"title":"العمود الفقري القطني","lead":"إذا صاحب ألمَ أسفل الظهر ألمٌ أو خدر في الطرف السفلي، فافحص إصابة الجذر العصبي. وقدّر مستوى الإصابة من الأعراض التي تثيرها الاختبارات ومن النتائج العصبية.","sheet":{"kind":"tests","tests":[{"name":"اختبار رفع الساق المستقيمة (SLR)","alias":"علامة لاسيغ","steps":"في الاستلقاء على الظهر والركبة مبسوطة، يرفع الفاحص الطرف السفلي ببطء وبشكل سلبي.","positive":"إثارة ألم أو خدر يمتد إلى الألية والساق","tissue":"الجذران L5 وS1 والعصب الوركي","point":"ميّز شد خلف الفخذ عن إطالة أوتار الركبة الخلفية. وسجّل الزاوية والعرض."},{"name":"اختبار شد العصب الفخذي","alias":"اختبار FNS (لاسيغ المعكوس)","steps":"في الانبطاح، اثنِ الركبة سلبيًا، وعند الحاجة حرّك الورك أيضًا إلى البسط.","positive":"ألم يمتد إلى مقدمة الفخذ","tissue":"الجذور القطنية العليا (L2–L4) والعصب الفخذي","point":"ميّزه عن ألم إطالة العضلة رباعية الرؤوس وعن الألم الناشئ من الورك."},{"name":"اختبار كيمب","alias":"","steps":"وقوفًا أو جلوسًا، يحرك الفاحص الجذع للخلف إلى البسط، ويحنيه في الوقت نفسه ويديره نحو جهة الألم.","positive":"ألم أسفل الظهر أو ألم يمتد إلى ساق جهة الألم","tissue":"المفاصل الوجيهية والجذر العصبي (الثقبة)","point":"عند ألم موضعي أسفل الظهر فكّر في المفاصل الوجيهية، وعند ألم يمتد للساق في إصابة الجذر العصبي."},{"name":"اختبار براغارد","alias":"","steps":"من الزاوية التي أثارت العرض في SLR أنزل الطرف قليلًا، ثم حرّك الكاحل سلبيًا إلى العطف الظهري.","positive":"يعود الألم الممتد إلى الساق أو يزداد","tissue":"العصب الوركي والجذور القطنية العجزية","point":"يساعد على تمييز ألم إطالة أوتار الركبة الخلفية عن العرض العصبي المنشأ."}]},"keypoints":["ميّز أولًا: ألم أسفل الظهر وحده، أم مع أعراض في الساق؟","SLR يفحص الجذور القطنية السفلى، وشد العصب الفخذي العليا","سجّل الإحساس بإطالة العضلة والألم العصبي الممتد كلًا على حدة","قدّر المستوى من القطاعات الجلدية والقوة العضلية والمنعكسات","اضطراب التبول أو التبرز وخدر العجان: إحالة فورية للفحص الطبي"],"case":{"text":"رجل عمره 35 عامًا. منذ رفع شيء ثقيل يعاني ألمًا أسفل الظهر وخدرًا من الجانب الوحشي للساق اليمنى حتى ظهر القدم. اختبار SLR يثير ألمًا يمتد إلى الساق اليمنى، واختبار براغارد يزيده. وقوة العطف الظهري لإصبع القدم الكبير ناقصة.","answer":"نشتبه في عرض جذري في L5 (مثل الانزلاق الغضروفي القطني). تجنب التحميل بالانحناء للأمام الذي يزيد الألم. وعند اضطراب التبول أو التبرز أو خدر العجان أو تدهور سريع في القوة العضلية: إحالة فورية للفحص الطبي."},"questions":[{"level":"أساسي","q":"أي عصب يشدّه اختبار SLR أساسًا؟","options":["العصب الفخذي","العصب الوركي","العصب السدادي","العصب الفرجي"],"answer":1,"exp":"مع بسط الركبة، يشد ثني الورك العصب الوركي الممتد في خلف الطرف والجذرين L5–S1."},{"level":"أساسي","q":"أي مستويات جذرية يفحصها اختبار شد العصب الفخذي أساسًا؟","options":["L2–L4","L5–S1","S2–S4","C5–C6"],"answer":0,"exp":"ينشأ العصب الفخذي من الجذور L2–L4، لذا نستخدمه لفحص الأعراض الجذرية القطنية العليا."},{"level":"متوسط","q":"ما الإجراء الذي تؤديه في اختبار براغارد؟","options":["العطف الأخمصي للكاحل","الدوران الخارجي للورك","ثني الركبة","العطف الظهري للكاحل"],"answer":3,"exp":"من الزاوية التي أثارت العرض في SLR تُنزل الساق قليلًا، ثم تزيد شد العصب بالعطف الظهري للكاحل."},{"level":"متوسط","q":"بماذا تفكر أساسًا إذا سبّب اختبار كيمب ألمًا موضعيًا أسفل الظهر فقط دون أعراض في الساق؟","options":["انضغاط جذر عصبي","إصابة العصب الفخذي","ألم منشؤه المفاصل الوجيهية","متلازمة العضلة الكمثرية"],"answer":2,"exp":"البسط والدوران يحمّلان المفاصل الوجيهية. وعند ألم موضعي فقط فكّر في منشأ وجيهي."},{"level":"سريري","q":"امرأة عمرها 40 عامًا تعاني ألمًا أسفل الظهر وخدرًا من الحافة الوحشية للقدم اليسرى حتى باطنها. ومنعكس أكيلس الأيسر ناقص. أي جذر عصبي تشتبه فيه؟","options":["L3","L4","L5","S1"],"answer":3,"exp":"اضطراب الإحساس في الحافة الوحشية للقدم وباطنها ونقص منعكس أكيلس يشيران إلى إصابة الجذر S1."},{"level":"سريري","q":"رجل عمره 50 عامًا ظهر لديه فجأة، مع ألم أسفل الظهر، خدر في العجان وصعوبة في التبول. ما أفضل تصرف؟","options":["إحالته فورًا إلى الطبيب","إعادة فحص SLR","البدء بتمارين قطنية","علاج حراري وانتظار"],"answer":0,"exp":"خدر العجان واضطراب المثانة والمستقيم علامة حمراء تشير إلى متلازمة ذيل الفرس؛ ويلزم تدخل عاجل."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"العمود الفقري والحوض","icono":"🦴","mapa":"img/mapas/t16.jpg","fichas":[],"secuencias":[]},"17":{"id":17,"title":"المفصل العجزي الحرقفي","lead":"يسهل الخلط بين الألم الناشئ من المفصل العجزي الحرقفي (SI) وألم أسفل الظهر. استنتج بالجمع بين إشارة المريض إلى مكان الألم وعدة اختبارات استثارة.","sheet":{"kind":"tests","tests":[{"name":"اختبار FABER (باتريك)","alias":"","steps":"في الاستلقاء على الظهر تضع قدم جهة الألم على الركبة المقابلة، وتثبّت الحوض المقابل، وتضغط الركبة للأسفل.","positive":"ألم في الألية فوق المفصل العجزي الحرقفي (ألم الأربية: مفصل الورك)","tissue":"المفصل العجزي الحرقفي ومفصل الورك","point":"ميّز حسب مكان الألم: الأربية تعني مفصل الورك، والألية فوق المفصل تعني المفصل العجزي الحرقفي."},{"name":"اختبار غانسلين","alias":"","steps":"في الاستلقاء على الظهر يتدلى أحد الطرفين السفليين من حافة طاولة الفحص (بسط الورك)، ويضم المريض الركبة الأخرى مثنية إليه.","positive":"ألم فوق المفصل العجزي الحرقفي في جهة البسط","tissue":"المفصل العجزي الحرقفي","point":"تجنب فرط بسط العمود القطني؛ وأسند الجذع لتفادي السقوط."},{"name":"اختبار دفع الفخذ (thigh thrust)","alias":"اختبار ضغط الفخذ","steps":"في الاستلقاء على الظهر ومع ثني الورك 90°، تضغط للأسفل على امتداد المحور الطولي للفخذ.","positive":"ألم في الألية من الجهة نفسها فوق المفصل العجزي الحرقفي","tissue":"المفصل العجزي الحرقفي","point":"اطلب من المريض أن يشير إلى مكان الألم، وتحقق هل هو ألمه المعتاد."},{"name":"اختبار ضغط الحوض","alias":"","steps":"في الاستلقاء الجانبي تطبّق ضغطًا من الأعلى إلى الأسفل على العرف الحرقفي العلوي.","positive":"ألم فوق المفصل العجزي الحرقفي","tissue":"المفصل العجزي الحرقفي","point":"لا يكفي وحده. استنتج الألم العجزي الحرقفي من مجموعة عدة اختبارات استثارة."}]},"keypoints":["اطلب من المريض أن يشير بإصبع واحدة إلى مكان الألم","عند الألم حول الشوكة الحرقفية الخلفية العلوية فكّر في منشأ عجزي حرقفي","قرّر بناءً على عدة اختبارات استثارة لا على اختبار واحد","عند ألم الأربية فكّر في الورك، وعند الألم الممتد للساق في الجذر العصبي","عند الحمى أو ألم الراحة الشديد أحِله إلى الطبيب"],"case":{"text":"امرأة عمرها 32 عامًا، بعد الولادة بـ 3 أشهر. ألم في ألية واحدة يزداد عند الالتفاف والوقوف على ساق واحدة. تشير بإصبع واحدة إلى منطقة الشوكة الحرقفية الخلفية العلوية. اختبار دفع الفخذ واختبار غانسلين يثيران الألم.","answer":"نشتبه في ألم منشؤه المفصل العجزي الحرقفي. عند ألم يمتد إلى الساق أو عرض عصبي فكّر أيضًا في منشأ قطني. وعند الحمى أو ألم الراحة الشديد أحِلها إلى الطبيب. وتقدّم بتثبيت حزام الحوض وضبط جرعة التحميل."},"questions":[{"level":"أساسي","q":"في اختبار الإصبع الواحدة، أي منطقة يشير إليها المريض عادةً عند الألم العجزي الحرقفي؟","options":["منطقة الشوكة الحرقفية الأمامية العلوية","منطقة الشوكة الحرقفية الخلفية العلوية","الارتفاق العاني","الحدبة الإسكية"],"answer":1,"exp":"عند الألم الناشئ من المفصل العجزي الحرقفي يشير المريض غالبًا بإصبع واحدة إلى منطقة الشوكة الحرقفية الخلفية العلوية."},{"level":"أساسي","q":"ما العظام التي تكوّن المفصل العجزي الحرقفي؟","options":["العجز وعظم الحرقفة","العجز والعظم الإسكي","عظم الحرقفة والعظم العاني","الفقرة L5 والعجز"],"answer":0,"exp":"المفصل العجزي الحرقفي هو المفصل بين العجز وعظمي الحرقفة؛ ويشكّل الجزء الخلفي من حلقة الحوض."},{"level":"متوسط","q":"بأي مفصل تفكر إذا سبّب اختبار FABER (باتريك) ألمًا في الأربية؟","options":["المفصل العجزي الحرقفي","مفصل الورك","مفصل الركبة","المفاصل الوجيهية"],"answer":1,"exp":"إذا آلمت الأربية مع الثني والتبعيد والدوران الخارجي ففكّر في مفصل الورك، وإذا آلم خلف الألية ففي المفصل العجزي الحرقفي."},{"level":"متوسط","q":"في أي اتجاه تطبّق الضغط في اختبار دفع الفخذ؟","options":["الفخذ نحو الخارج","الحوض نحو الأمام","للأسفل على امتداد المحور الطولي للفخذ","الركبة نحو الداخل"],"answer":2,"exp":"مع ثني الورك 90°، يطبّق الضغط على امتداد المحور الطولي للفخذ حملًا قاصًّا على المفصل العجزي الحرقفي."},{"level":"سريري","q":"امرأة عمرها 28 عامًا تعاني بعد الولادة ألمًا في ألية واحدة. اختبار غانسلين ودفع الفخذ وضغط الحوض تثير الألم. ما الأرجح؟","options":["مفصل الورك","الجذر العصبي L5","العضلة الكمثرية","المفصل العجزي الحرقفي"],"answer":3,"exp":"عدة اختبارات استثارة للمفصل العجزي الحرقفي تثير الألم نفسه، لذا نفكر أساسًا في ألم منشؤه هذا المفصل."},{"level":"سريري","q":"رجل عمره 45 عامًا يعاني ألمًا في ألية واحدة. اختبار FABER (باتريك) وحده سبّب ألم الألية. ما الخطوة التالية الأنسب؟","options":["الحكم بخلل المفصل العجزي الحرقفي","اختبارات استثارة إضافية","إغفال فحص العمود القطني والورك","تصحيح يدوي قوي"],"answer":1,"exp":"لا يمكنك الحكم بناءً على اختبار إيجابي واحد. اجمع عدة اختبارات استثارة مع فحص العمود القطني والورك."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"العمود الفقري والحوض","icono":"🦴","mapa":"img/mapas/t17.jpg","fichas":[],"secuencias":[]},"18":{"id":18,"title":"الورك","lead":"يظهر الألم الناشئ من مفصل الورك غالبًا في الأربية، ويظهر التيبس والضعف العضلي في المشي. تحقق بالاختبارات من التأثير داخل المفصل وعلى العضلات وعلى المشي.","sheet":{"kind":"tests","tests":[{"name":"اختبار توماس","alias":"","steps":"في الاستلقاء على الظهر يضم المريض إحدى ركبتيه إلى صدره فيزول التقعر القطني؛ لاحظ هل يرتفع الفخذ المقابل.","positive":"يرتفع الفخذ المقابل عن السطح (تيبس انثنائي في الورك)","tissue":"قِصَر العضلة الحرقفية القطنية (قابضات الورك)","point":"إذا انبسطت الركبة ففكّر أيضًا في قِصَر العضلة المستقيمة الفخذية. قيّم بعد إزالة التقعر القطني."},{"name":"اختبار FABER (باتريك)","alias":"","steps":"في الاستلقاء على الظهر تحرّك الورك إلى الثني والتبعيد والدوران الخارجي (القدم على الركبة المقابلة)، ثم تضغط الركبة للأسفل.","positive":"ألم في الأربية، أو محدودية في نزول الركبة","tissue":"مفصل الورك والمفصل العجزي الحرقفي","point":"عند ألم الأربية فكّر في الورك، وعند ألم خلف الألية في المفصل العجزي الحرقفي. قارن بالجهة السليمة."},{"name":"اختبار الانحشار الأمامي","alias":"اختبار FADIR","steps":"في الاستلقاء على الظهر، ومن ثني الورك 90°، تطبّق تقريبًا ودورانًا داخليًا بشكل سلبي.","positive":"إثارة ألم الأربية","tissue":"الجزء الأمامي من مفصل الورك (الشفا، حافة الحُق)","point":"غالبًا إيجابي في الانحشار الفخذي الحُقي وإصابة الشفا. قارنه بالتصوير."},{"name":"علامة ترندلنبرغ","alias":"","steps":"يقف المريض على ساق جهة الألم؛ ولاحظ من الخلف ارتفاع الحوض في الجهة المقابلة (المرفوعة).","positive":"يهبط الحوض في الجهة المرفوعة","tissue":"العضلة الألوية الوسطى لساق الارتكاز (مبعدات الورك)","point":"إذا عوّض بميل الجذع نحو ساق الارتكاز فهذه علامة دوشين. أسنده لتفادي السقوط."}]},"keypoints":["يظهر الألم الناشئ من مفصل الورك غالبًا في الأربية","يفحص اختبار توماس التيبس الانثنائي بعد إزالة التقعر القطني","تُظهر علامة ترندلنبرغ قوة العضلة الألوية الوسطى لساق الارتكاز","ميّزه أيضًا عن الألم الناشئ من العمود القطني والمفصل العجزي الحرقفي","العجز عن التحميل بعد إصابة أو ألم راحة متفاقم: أحِله للطبيب"],"case":{"text":"امرأة عمرها 68 عامًا مصابة بالفُصال العظمي في الورك. تعاني ألمًا في الأربية اليمنى عند المشي. عند الوقوف على الساق اليمنى يهبط الحوض الأيسر؛ وعند ضم ركبتها اليسرى إلى صدرها يرتفع الفخذ الأيمن عن السطح.","answer":"نفكر في ضعف العضلة الألوية الوسطى اليمنى وتيبس انثنائي في الورك الأيمن. لاحظ أيضًا التعويض أثناء المشي؛ وأجرِ تقوية المبعدات وتمارين مدى الحركة مع مراعاة الألم. وعند تفاقم مفاجئ في ألم الراحة أحِلها إلى الطبيب."},"questions":[{"level":"أساسي","q":"قِصَر أي عضلة يفحصه اختبار توماس أساسًا؟","options":["العضلة الألوية الكبرى","العضلة الحرقفية القطنية","العضلة الألوية الوسطى","أوتار الركبة الخلفية"],"answer":1,"exp":"ارتفاع الفخذ المقابل يدل على تيبس انثنائي في الورك، فيُظهر قِصَر القابض الرئيسي للورك، أي العضلة الحرقفية القطنية."},{"level":"أساسي","q":"ضعف أي عضلة تدل عليه علامة ترندلنبرغ حين يهبط الحوض المقابل في الوقوف على ساق واحدة؟","options":["الألوية الوسطى لساق التأرجح","رباعية الرؤوس لساق الارتكاز","الألوية الوسطى لساق الارتكاز","الحرقفية القطنية لساق التأرجح"],"answer":2,"exp":"إذا ضعفت العضلة الألوية الوسطى لساق الارتكاز، لا تستطيع إبقاء الحوض أفقيًا، فتهبط الجهة المقابلة (المرفوعة)."},{"level":"متوسط","q":"قِصَر أي عضلة تفكر فيه إذا انبسطت الركبة في اختبار توماس؟","options":["العضلة المستقيمة الفخذية","العضلة الخياطية","العضلة المقربة الكبرى","العضلة ذات الرأسين الفخذية"],"answer":0,"exp":"العضلة المستقيمة الفخذية عضلة ثنائية المفصل تعبر الورك والركبة؛ وعند قِصَرها تنبسط الركبة."},{"level":"متوسط","q":"أي تركيبة من الحركات تجريها في اختبار الانحشار الأمامي (FADIR)؟","options":["ثني وتبعيد ودوران خارجي","بسط وتبعيد ودوران داخلي","بسط وتقريب ودوران خارجي","ثني وتقريب ودوران داخلي"],"answer":3,"exp":"من ثني الورك 90° تطبّق تقريبًا ودورانًا داخليًا، وتلاحظ هل يمكن إثارة ألم الورك الأمامي."},{"level":"سريري","q":"رجل عمره 70 عامًا. كلما خطا على ساقه اليمنى أمال جذعه بشدة نحو اليمين أثناء المشي. ما اسم هذه المشية؟","options":["المشية الخطوية","المشية الدائرية","التجمّد (freezing)","مشية دوشين"],"answer":3,"exp":"إذا عوّض المريض ضعف العضلة الألوية الوسطى بإمالة الجذع نحو ساق الارتكاز، فهذه مشية دوشين."},{"level":"سريري","q":"لاعب كرة قدم عمره 30 عامًا. تؤلمه الأربية عند القرفصاء العميقة، وثني الورك وتقريبه ودورانه الداخلي تثير الألم. ما الأرجح؟","options":["الفُصال العظمي في الركبة","الانحشار الفخذي الحُقي","اعتلال جذري في L5","متلازمة العضلة الكمثرية"],"answer":1,"exp":"ألم الأربية في الثني العميق واختبار الانحشار الأمامي الإيجابي يشيران إلى الانحشار الفخذي الحُقي."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"الورك والركبة","icono":"🦵","mapa":"img/mapas/t18.jpg","fichas":[],"secuencias":[]},"19":{"id":19,"title":"الركبة: الأربطة","lead":"تُميّز اختبارات أربطة الركبة بين إصابة الرباط الصليبي الأمامي والخلفي والرباط الجانبي الإنسي والوحشي. يعتمد القرار على آلية الإصابة والمقارنة مع الجانب السليم.","sheet":{"kind":"tests","tests":[{"name":"اختبار لاكمان","alias":"","steps":"استلقاء على الظهر، الركبة في ثني 20–30°. تمسك إحدى اليدين الجزء البعيد من الفخذ، والأخرى الجزء القريب من الظنبوب وتسحبه إلى الأمام.","positive":"انزياح أمامي أكبر من الجانب السليم أو شعور نهائي غير واضح.","tissue":"الرباط الصليبي الأمامي (ACL)","point":"اختبار حساس لإصابة ACL. لا يحتاج إلى ثني الركبة 90°، لذا يسهل إجراؤه في المرحلة الحادة."},{"name":"اختبار الدرج الأمامي","alias":"","steps":"استلقاء على الظهر، الورك في ثني 45° والركبة في ثني 90°. ثبّت القدم، وامسك الجزء القريب من الظنبوب باليدين واسحبه إلى الأمام.","positive":"انزياح أمامي للظنبوب أكبر مقارنة بالجانب السليم.","tissue":"الرباط الصليبي الأمامي (ACL)","point":"قد يعطي الشد العضلي الوقائي نتيجة سلبية كاذبة. انتبه أيضًا للهبوط الخلفي الناتج عن إصابة PCL."},{"name":"اختبار الدرج الخلفي","alias":"","steps":"استلقاء على الظهر، الورك في ثني 45° والركبة في ثني 90°. ثبّت القدم، وادفع الجزء القريب من الظنبوب إلى الخلف.","positive":"انزياح خلفي للظنبوب أكبر من الجانب السليم، وشعور نهائي غير واضح.","tissue":"الرباط الصليبي الخلفي (PCL)","point":"قبل البدء لاحظ الهبوط الخلفي للظنبوب (علامة sag) حتى لا تخطئ في وضع البداية."},{"name":"اختبار إجهاد الأروح والأفحج","alias":"","steps":"استلقاء على الظهر، الركبة عند 0° وفي ثني 30°. ثبّت الجزء البعيد من الفخذ، وطبّق على الساق قوة باتجاه الأروح (valgus) أو الأفحج (varus).","positive":"ألم في الشق المفصلي أو انفتاح أكبر من الجانب السليم.","tissue":"الأروح = MCL، الأفحج = LCL","point":"إيجابي عند 30° فقط: إصابة معزولة للرباط الجانبي. إيجابي عند 0° أيضًا: اشتباه إصابة مرافقة (كالرباط الصليبي)."}]},"keypoints":["اختبار لاكمان هو الخيار الأول لتقييم ACL، مع المقارنة دائمًا بالجانب السليم","في التاريخ المرضي اسأل عن انخلاع الركبة وصوت الفرقعة والتورم السريع","قبل اختبار الدرج الخلفي تحقق من وضع الظنبوب بعلامة sag","اختبر الأربطة الجانبية عند 0° وفي ثني 30°","الشد الوقائي يعطي نتيجة سلبية كاذبة، لذا افحص المريض وهو مسترخٍ"],"case":{"text":"امرأة عمرها 20 عامًا. أثناء الهبوط في كرة السلة التوت ركبتها إلى الداخل. سمعت صوت فرقعة وتورمت الركبة فورًا. في اختبار لاكمان الانزياح الأمامي أكبر من الجانب السليم والشعور النهائي غير واضح.","answer":"نتيجة تشير إلى إصابة ACL. افحص أيضًا الإصابة المرافقة للغضروف الهلالي والرباط الجانبي، وأحِل المريضة لفحص تصويري طبي. لا تكرر اختبارات الإجهاد القوية أثناء التورم والألم الشديدين."},"questions":[{"level":"أساسي","q":"في الشكل، أي اختبار يسحب الظنبوب إلى الأمام والركبة في ثني 20–30°؟","options":["اختبار الدرج الأمامي","اختبار لاكمان","اختبار الدرج الخلفي","اختبار إجهاد الأروح"],"answer":1,"exp":"يسحب اختبار لاكمان الظنبوب إلى الأمام والركبة في ثني 20–30° ويقيّم ACL. أما اختبار الدرج الأمامي فيُجرى والركبة عند 90°."},{"level":"أساسي","q":"في الشكل، أي رباط يقيّمه اختبار إجهاد الأفحج؟","options":["الرباط الجانبي الإنسي (MCL)","الرباط الصليبي الأمامي (ACL)","الرباط الجانبي الوحشي (LCL)","الرباط الصليبي الخلفي (PCL)"],"answer":2,"exp":"يفتح إجهاد الأفحج الجانب الوحشي للركبة، فيقيّم الرباط الجانبي الوحشي (LCL). أما إجهاد الأروح فيقيّم MCL."},{"level":"متوسط","q":"إلى أي إصابة يشير اختبار الدرج الخلفي الإيجابي؟","options":["إصابة PCL","إصابة ACL","إصابة LCL","خلع الرضفة"],"answer":0,"exp":"يدفع اختبار الدرج الخلفي الظنبوب إلى الخلف والركبة في ثني 90°، ويقيّم الرباط الصليبي الخلفي (PCL)."},{"level":"متوسط","q":"إذا كان اختبار إجهاد الأروح إيجابيًا والركبة عند 0° أيضًا، بماذا تفكر أولًا؟","options":["إصابة MCL خفيفة ومعزولة","إصابة الغضروف الهلالي الوحشي فقط","عدم ثبات الرضفة","إصابة مرافقة (مثل الرباط الصليبي)"],"answer":3,"exp":"في البسط تساهم الأربطة الصليبية والمحفظة المفصلية في الثبات. إذا انفتح الشق عند 0° أيضًا فالاشتباه إصابة مرافقة لا إصابة MCL معزولة."},{"level":"سريري","q":"رجل عمره 25 عامًا. أثناء كرة القدم تلقى ضربة قوية على مقدمة الظنبوب والركبة مثنية. عند ثني 90° هبط الظنبوب إلى الخلف. ما الأرجح؟","options":["إصابة ACL","إصابة PCL","إصابة MCL","إصابة الغضروف الهلالي الإنسي"],"answer":1,"exp":"القوة على السطح الأمامي للظنبوب مع علامة sag نمط نموذجي لإصابة PCL. أكّد ذلك باختبار الدرج الخلفي وأحِل المريض للتشخيص الطبي."},{"level":"سريري","q":"امرأة عمرها 30 عامًا. أثناء التزلج التوت ركبتها إلى الأروح. في إجهاد الأروح يوجد ألم وانفتاح عند ثني 30°، وثبات عند 0°. ما الأرجح؟","options":["إصابة ACL معزولة","إصابة LCL","إصابة MCL معزولة","إصابة PCL"],"answer":2,"exp":"آلية الأروح مع اختبار إيجابي عند 30° فقط تشير إلى إصابة MCL معزولة. إذا كان إيجابيًا عند 0° أيضًا فيجب افتراض إصابة مرافقة."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"الورك والركبة","icono":"🦵","mapa":"img/mapas/t19.jpg","fichas":[{"nombre":"اختبار لاكمان","img":"img/fichas/lachman.jpg"}],"secuencias":[]},"20":{"id":20,"title":"الركبة: الغضاريف الهلالية والرضفة","lead":"تبحث اختبارات الغضروف الهلالي والرضفة عن سبب ألم الركبة والانحشار والإحساس بعدم الثبات عند الالتواء أو الهبوط. يُبنى القرار على مجموعة من النتائج معًا.","sheet":{"kind":"tests","tests":[{"name":"اختبار ماكموري","alias":"","steps":"استلقاء على الظهر. اثنِ الركبة إلى أقصى حد، ثم ابسطها تدريجيًا مع تدوير الساق للخارج أو للداخل.","positive":"طقطقة أو ألم في الشق المفصلي.","tissue":"الغضروف الهلالي (الإنسي والوحشي)","point":"الدوران الخارجي يقيّم الهلالي الإنسي، والدوران الداخلي يقيّم الوحشي. لا يُعدّ دليلًا بمفرده."},{"name":"اختبار آبلي","alias":"اختبار آبلي بالضغط","steps":"استلقاء على البطن، الركبة في ثني 90°. مع ضغط من الكعب إلى الأسفل، دوّر الساق للداخل وللخارج.","positive":"ألم في الشق المفصلي مع الضغط والدوران.","tissue":"الغضروف الهلالي","point":"إذا ظهر الألم مع الدوران أثناء الجذب (distraction) ففكّر في الرباط أو بنية أخرى غير الغضروف الهلالي."},{"name":"اختبار ثيسالي","alias":"","steps":"يمسك الفاحص يدي المريض. في الوقوف على ساق واحدة والركبة في ثني 20°، يدوّر المريض جذعه وركبته للداخل وللخارج. ابدأ بالجانب السليم.","positive":"ألم في الشق المفصلي أو إحساس بالانحشار أو التعلّق.","tissue":"الغضروف الهلالي","point":"اختبار في وضع التحميل. انتبه لخطر السقوط، وأمّن الإسناد باليدين."},{"name":"اختبار التوجس الرضفي","alias":"","steps":"استلقاء على الظهر والركبة مثنية قليلًا. العضلة رباعية الرؤوس الفخذية مسترخية، ادفع الرضفة ببطء نحو الجانب الوحشي.","positive":"يظهر الخوف، ويحمي المريض نفسه بشد العضلة رباعية الرؤوس.","tissue":"مثبتات الرضفة (الرباط الرضفي الفخذي الإنسي)","point":"مفيد لتأكيد خلع أو خلع جزئي سابق للرضفة. نفّذه بحذر ولا تُحدث خلعًا."}]},"keypoints":["ألم الشق المفصلي نتيجة مهمة تشير إلى إصابة الغضروف الهلالي","اختبارات الغضروف الهلالي غير حاسمة منفردة، فقارن بين عدة نتائج","الانحشار الذي يمنع البسط الكامل (locking) يستدعي استشارة طبية","في اختبارات الرضفة راقب رد فعل الخوف ونفّذها بحذر","في اختبارات التحميل أمّن الإسناد للوقاية من السقوط"],"case":{"text":"رجل عمره 35 عامًا. التوت ركبته وهي مثنية، وبعد بضع ساعات تورمت. يشعر بانحشار في الجانب الإنسي للركبة على الدرج. الشق المفصلي الإنسي مؤلم عند الضغط، واختبار ماكموري مؤلم مع طقطقة.","answer":"اشتباه إصابة الغضروف الهلالي الإنسي. افحص أيضًا الإصابة المرافقة للأربطة، وأحِل المريض لفحص تصويري طبي. في حالة الانحشار لا تفرض البسط."},"questions":[{"level":"أساسي","q":"في الشكل، أي اختبار يطبّق الضغط والدوران في الاستلقاء على البطن والركبة عند 90°؟","options":["اختبار ماكموري","اختبار ثيسالي","اختبار آبلي","اختبار التوجس الرضفي"],"answer":2,"exp":"يدوّر اختبار آبلي الساق في الاستلقاء على البطن والركبة في ثني 90° مع ضغط من الكعب، ويقيّم الغضروف الهلالي."},{"level":"أساسي","q":"وفق ملخص الشكل، أي نتيجة تشير إلى إصابة الغضروف الهلالي؟","options":["ألم الشق المفصلي","ألم فوق الرضفة","ألم على حدبة الظنبوب","ألم في السطح الخلفي للفخذ"],"answer":0,"exp":"ألم الشق المفصلي (الشق بين عظم الفخذ والظنبوب) يشير إلى إصابة الغضروف الهلالي."},{"level":"متوسط","q":"في اختبار ماكموري، ماذا يقيّم البسط مع الدوران الخارجي للساق أساسًا؟","options":["الغضروف الهلالي الوحشي","الغضروف الهلالي الإنسي","الرباط الصليبي الأمامي","الرباط الرضفي"],"answer":1,"exp":"الدوران الخارجي يقيّم الغضروف الهلالي الإنسي، والدوران الداخلي يقيّم الوحشي."},{"level":"متوسط","q":"ما النتيجة الإيجابية في اختبار التوجس الرضفي؟","options":["طقطقة عند الرضفة","ألم الشق المفصلي الإنسي","محدودية بسط الركبة","خوف وحماية بالعضلة رباعية الرؤوس"],"answer":3,"exp":"إذا أظهر المريض خوفًا عند دفع الرضفة جانبيًا وحمى نفسه بالعضلة رباعية الرؤوس فالاختبار إيجابي ويشير إلى عدم ثبات الرضفة."},{"level":"سريري","q":"امرأة عمرها 18 عامًا. عند الهبوط من قفزة شعرت بأن رضفتها خرجت من مكانها ثم عادت تلقائيًا. ما الفحص الأنسب؟","options":["اختبار التوجس الرضفي","اختبار الدرج الخلفي","اختبار طومسون","اختبار إجهاد الأفحج"],"answer":0,"exp":"مسار يشير إلى خلع أو خلع جزئي للرضفة. تتحقق من عدم الثبات باختبار التوجس الرضفي."},{"level":"سريري","q":"رجل عمره 40 عامًا. يعاني منذ مدة من انحشار داخل ركبته، ومنذ صباح اليوم لا يستطيع بسطها تمامًا. ما التصرف الصحيح؟","options":["إرجاعها ببسط سلبي قوي","إحالته للطبيب وطلب الفحص","تكرار اختبار ثيسالي","البدء فورًا بتمارين التقوية"],"answer":1,"exp":"قد يشير الانحشار المانع للبسط إلى غضروف هلالي محشور، ويلزم فحص طبي. تجنّب البسط القسري وتكرار الاختبارات."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"الورك والركبة","icono":"🦵","mapa":"img/mapas/t20.jpg","fichas":[{"nombre":"اختبار ماكموري","img":"img/fichas/mcmurray.jpg"}],"secuencias":[]},"21":{"id":21,"title":"الكاحل والقدم","lead":"تُميّز اختبارات الكاحل والقدم بين إصابة الأربطة الناتجة عن الالتواء وتمزق وتر أكيلس. يجب التفكير دائمًا في احتمال الكسر.","sheet":{"kind":"tests","tests":[{"name":"اختبار طومسون","alias":"اختبار سيموندز","steps":"استلقاء على البطن والقدم متدلية من حافة السرير. اضغط بطن العضلة ثلاثية الرؤوس الربلية.","positive":"لا يحدث عطف أخمصي في الكاحل، أو يكون أقل بوضوح من الجانب السليم.","tissue":"وتر أكيلس","point":"قد يوجد عطف أخمصي نشط رغم التمزق (مثلًا بعضلات ثني الأصابع)، لذا هذا الاختبار مفيد."},{"name":"اختبار الدرج الأمامي (الكاحل)","alias":"","steps":"جلوس أو استلقاء على الظهر، الكاحل في عطف أخمصي خفيف. ثبّت الجزء البعيد من الظنبوب، وامسك الكعب واسحب الكاحل (talus) إلى الأمام.","positive":"انزياح أمامي أكبر من الجانب السليم، وشعور نهائي غير واضح.","tissue":"الرباط الكاحلي الشظوي الأمامي","point":"يقيّم الرباط الأكثر إصابة في التواء القلب للداخل. في المرحلة الحادة نفّذه مع مراعاة الألم."},{"name":"اختبار إمالة الكاحل","alias":"اختبار إجهاد الأفحج","steps":"ثبّت الجزء البعيد من الساق، وامسك عظم العقب وأمِل الكاحل باتجاه القلب للداخل.","positive":"ميل للكاحل أكبر من الجانب السليم، مع ألم.","tissue":"الرباط العقبي الشظوي (والكاحلي الشظوي الأمامي)","point":"قيّم شدة إصابة الأربطة الوحشية مع اختبار الدرج الأمامي."},{"name":"اختبار الضغط (Squeeze)","alias":"","steps":"استلقاء على الظهر. في منتصف الساق اضغط الظنبوب والشظية معًا باليدين.","positive":"ألم فوق الكاحل بين الظنبوب والشظية.","tissue":"الأربطة الظنبوبية الشظوية البعيدة (الارتفاق)","point":"استخدمه عند الاشتباه بالتواء الكاحل العالي. استبعاد الكسر مهم أيضًا."}]},"keypoints":["في التواء القلب للداخل يكون الرباط الكاحلي الشظوي الأمامي الأكثر إصابة","قد يوجد عطف أخمصي نشط رغم تمزق وتر أكيلس","عند وجود ألم عظمي بالضغط أو عجز عن التحميل فكّر في الكسر وأحِل للطبيب","قيّم اختبارات الأربطة دائمًا بالمقارنة مع الجانب السليم","الألم بين الظنبوب والشظية قد يشير إلى التواء الكاحل العالي"],"case":{"text":"رجل عمره 45 عامًا. أثناء لعب التنس شعر وكأن أحدًا ركله من الخلف. لا يستطيع الوقوف على أطراف أصابعه. في الاستلقاء على البطن لا يحدث عطف أخمصي عند ضغط العضلة ثلاثية الرؤوس الربلية.","answer":"اختبار طومسون إيجابي: اشتباه تمزق وتر أكيلس. أحِل المريض بشكل عاجل للفحص الطبي. وجود عطف أخمصي نشط لا يستبعد التمزق."},"questions":[{"level":"أساسي","q":"أي بنية يقيّمها اختبار طومسون؟","options":["الرباط الكاحلي الشظوي الأمامي","وتر أكيلس","رباط عقبي شظوي","اللفافة الأخمصية"],"answer":1,"exp":"عند ضغط العضلة ثلاثية الرؤوس الربلية نلاحظ هل يحدث عطف أخمصي: يقيّم الاختبار استمرارية وتر أكيلس."},{"level":"أساسي","q":"أي رباط يُصاب أكثر في التواء القلب للداخل؟","options":["الرباط الكاحلي الشظوي الخلفي","الرباط الدالي","رباط عقبي شظوي","الرباط الكاحلي الشظوي الأمامي"],"answer":3,"exp":"تحدث الإصابة غالبًا في القلب للداخل مع عطف أخمصي، والرباط الكاحلي الشظوي الأمامي هو الأكثر إصابة. وفي الحالات الأشد يُصاب العقبي الشظوي أيضًا."},{"level":"متوسط","q":"أي رباط يقيّمه اختبار إمالة الكاحل أساسًا؟","options":["رباط عقبي شظوي","الرباط الدالي","وتر أكيلس","وتر العضلة الظنبوبية الخلفية"],"answer":0,"exp":"عند إمالة عظم العقب نحو القلب للداخل نلاحظ ميل الكاحل، فنقيّم أساسًا الرباط العقبي الشظوي."},{"level":"متوسط","q":"في اختبار الضغط يظهر ألم فوق الكاحل. بماذا تفكر؟","options":["تمزق وتر أكيلس","التهاب اللفافة الأخمصية","إصابة الأربطة الظنبوبية الشظوية البعيدة","إبهام القدم الأروح"],"answer":2,"exp":"إذا سبب ضغط منتصف الساق ألمًا عند المفصل الظنبوبي الشظوي البعيد فالاشتباه إصابة الارتفاق (التواء الكاحل العالي)."},{"level":"سريري","q":"رجل عمره 22 عامًا، إصابة قلب للداخل. تورم وألم بالضغط أمام الكعب الوحشي، دون ألم عظمي. أي اختبار يقيّم الرباط الكاحلي الشظوي الأمامي؟","options":["اختبار الدرج الأمامي (الكاحل)","اختبار طومسون","اختبار لاكمان","اختبار الضغط (Squeeze)"],"answer":0,"exp":"يكبح الرباط الكاحلي الشظوي الأمامي انزياح الكاحل إلى الأمام. تقيّمه باختبار الدرج الأمامي للكاحل بالمقارنة مع الجانب السليم."},{"level":"سريري","q":"امرأة عمرها 60 عامًا. سقطت والتوى كاحلها. يوجد ألم عظمي بالضغط على الكعب الوحشي، ولا تستطيع المشي مع التحميل. ما التصرف الصحيح؟","options":["تكرار اختبار الدرج الأمامي","إحالتها للطبيب لاشتباه كسر","تمارين توازن فورًا","تدريب المشي مع شريط لاصق"],"answer":1,"exp":"يشير الألم العظمي بالضغط والعجز عن التحميل إلى كسر. يلزم فحص طبي قبل اختبارات الإجهاد والتمارين."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"الكاحل والقدم","icono":"🦶","mapa":"img/mapas/t21.jpg","fichas":[{"nombre":"اختبار طومسون","img":"img/fichas/thompson.jpg"}],"secuencias":[{"nombre":"اختبار طومسون","rotulo":"يقيّم","texto":"وتر أكيلس","frames":["img/mov/teste-thompson-1.jpg","img/mov/teste-thompson-2.jpg","img/mov/teste-thompson-3.jpg"]}]},"22":{"id":22,"title":"الاختبارات العصبية والديناميكا العصبية","lead":"في اختبارات الديناميكا العصبية نشدّ الجهاز العصبي خطوة بخطوة ونراقب تكرار ظهور الأعراض. تساعد على التمييز بين الألم الجذري والألم الناشئ من عصب طرفي.","sheet":{"kind":"tests","tests":[{"name":"علامة لاسيغ (اختبار SLR)","alias":"اختبار رفع الساق المستقيمة","steps":"في الاستلقاء على الظهر ترفع الطرف السفلي والركبة مبسوطة بشكل سلبي. سجّل زاوية ظهور العرض، وتحقق من الزيادة بالعطف الظهري.","positive":"تتكرر الأعراض، مثل ألم ينتشر من الألية إلى السطح الخلفي للطرف السفلي.","tissue":"العصب الوركي، والجذران العصبيان L5 وS1 وغيرهما","point":"لتمييزه عن شد أوتار المأبض تفيد إضافة العطف الظهري للكاحل أو ثني الرقبة."},{"name":"اختبار شد العصب الفخذي","alias":"FNST (لاسيغ المعكوس)","steps":"في الاستلقاء على البطن تثني الركبة بشكل سلبي. عند الحاجة تضيف بسط الورك.","positive":"ألم ينتشر إلى السطح الأمامي للفخذ.","tissue":"العصب الفخذي، والجذور العصبية L2–L4","point":"ميّزه عن شد العضلة رباعية الرؤوس. يُستخدم لتقييم إصابة الجذور العصبية القطنية العلوية."},{"name":"اختبار الانهيار (Slump)","alias":"","steps":"في الجلوس بالترتيب: ثني الجذع ← ثني الرقبة ← بسط الركبة ← عطف ظهري للكاحل، ثم فك ثني الرقبة ومراقبة التغير.","positive":"تتكرر الأعراض، وتخف عند فك ثني الرقبة.","tissue":"الجهاز العصبي من القناة الشوكية إلى الطرف السفلي","point":"تقدّم خطوة بخطوة وتوقف عند ظهور العرض. قارن بين الجانبين."},{"name":"اختبار شد أعصاب الطرف العلوي","alias":"ULNT1 (العصب المتوسط)","steps":"استلقاء على الظهر: خفض حزام الكتف، تبعيد الكتف، استلقاء الساعد، بسط الرسغ والأصابع، دوران خارجي، بسط المرفق؛ وأخيرًا ميل الرقبة جانبيًا.","positive":"تتكرر أعراض الطرف العلوي وتتغير مع الميل الجانبي للرقبة.","tissue":"العصب المتوسط، والجذور العصبية العنقية","point":"قارن مع الجانب السليم. إذا غيّر تحريك جزء بعيد من الجسم العرض فالمنشأ العصبي أرجح."}]},"keypoints":["قيّم الاختبارات العصبية بناءً على تكرار الأعراض والفرق بين الجانبين","إذا غيّر تحريك جزء بعيد من الجسم العرض ففكّر في منشأ عصبي","وثّق شد العضلات والأعراض العصبية المنشأ بشكل منفصل","توقف عند ظهور العرض ولا تُحدث ألمًا شديدًا","عند شلل متفاقم أو اضطراب المثانة والمستقيم: إحالة فورية للفحص الطبي"],"case":{"text":"رجل عمره 42 عامًا. بعد رفع حمل ثقيل ظهر ألم أسفل الظهر وألم في السطح الخلفي للطرف السفلي الأيمن. يكرر اختبار SLR الألم المنتشر في السطح الخلفي للطرف السفلي الأيمن، ويزداد مع العطف الظهري.","answer":"نتيجة تشير إلى أعراض جذرية قطنية. حدّد القطعة المصابة من القوة العضلية والإحساس والمنعكسات. عند اضطراب المثانة والمستقيم أو شلل متفاقم أحِله فورًا للطبيب."},"questions":[{"level":"أساسي","q":"أي عصب يشدّه اختبار SLR أساسًا؟","options":["العصب المتوسط","العصب الفخذي","العصب الوركي","العصب الزندي"],"answer":2,"exp":"عند رفع الطرف السفلي والركبة مبسوطة يُشد العصب الوركي الممتد على السطح الخلفي والجذور العصبية القطنية السفلية."},{"level":"أساسي","q":"في أي وضعية يُجرى اختبار شد العصب الفخذي؟","options":["الاستلقاء على البطن","الاستلقاء على الظهر","الجلوس مع بسط الساقين","الوقوف"],"answer":0,"exp":"في الاستلقاء على البطن نثني الركبة فنشد العصب الفخذي الممتد على السطح الأمامي للفخذ."},{"level":"متوسط","q":"في اختبار SLR زاد العطف الظهري للكاحل الأعراض. إلامَ يشير ذلك؟","options":["قصر أوتار المأبض","عرض عصبي المنشأ","تقفع الورك","التواء الكاحل"],"answer":1,"exp":"يزيد العطف الظهري شد العصب دون تغيير طول العضلة. إذا زاد العرض فهو يشير إلى منشأ عصبي."},{"level":"متوسط","q":"في اختبار الانهيار خفّت أعراض الطرف السفلي عند فك ثني الرقبة. بماذا تفكر؟","options":["ألم شد عضلي","عدم ثبات مفصلي","ألم نفسي المنشأ","زيادة حساسية الجهاز العصبي"],"answer":3,"exp":"تحريك الرقبة لا يؤثر في عضلات الطرف السفلي، لذا يشير تغير العرض إلى إصابة الجهاز العصبي."},{"level":"سريري","q":"امرأة عمرها 50 عامًا. تنميل من مقدمة الفخذ حتى الجانب الإنسي للركبة. في الاستلقاء على البطن يكرر ثني الركبة ألم مقدمة الفخذ. أي قطعة مشتبه بها؟","options":["L2–L4","L5","S1","C6"],"answer":0,"exp":"اختبار شد العصب الفخذي إيجابي مع أعراض في مقدمة الفخذ: اشتباه إصابة الجذور العصبية القطنية العلوية (L2–L4)."},{"level":"سريري","q":"رجل عمره 38 عامًا. يكرر اختبار SLR ألم الطرف السفلي. مؤخرًا يجد صعوبة في التبول، والإحساس منخفض في منطقة العجان. ما التصرف الصحيح؟","options":["إعادة التحقق باختبار SLR","تقوية عضلات أسفل الظهر","إحالته فورًا للطبيب","متابعة تمارين انزلاق العصب"],"answer":2,"exp":"اضطراب التبول ونقص الإحساس في العجان من العلامات الحمراء لمتلازمة ذيل الفرس. يلزم فحص طبي فوري."}],"seccion":"الاختبارات الخاصة حسب المنطقة","grupo":"الاختبارات العصبية","icono":"🧠","mapa":"img/mapas/t22.jpg","fichas":[{"nombre":"علامة لاسيغ (اختبار SLR)","img":"img/fichas/lasegue.jpg"}],"secuencias":[{"nombre":"علامة لاسيغ","rotulo":"يقيّم","texto":"العصب الوركي (L4–S1)","frames":["img/mov/teste-lasegue-1.jpg","img/mov/teste-lasegue-2.jpg","img/mov/teste-lasegue-3.jpg"]}]},"23":{"id":23,"title":"الانحشار تحت الأخرم وتمزق الكفة المدورة","lead":"في الانحشار تحت الأخرم تتهيج الكفة المدورة والجراب تحت الأخرم عند رفع الذراع وتسبب ألمًا. من المهم تمييزه عن تمزق الكفة المدورة، وإعطاء تمارين علاجية متدرجة.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"عند الرفع تتهيج الكفة المدورة (خاصة وتر العضلة فوق الشوكة) والجراب تحت الأخرم وتؤلم. قد يحدث تمزق الكفة المدورة على خلفية العمر أو الإجهاد الزائد أو الرضح."},{"h":"الأعراض الرئيسية","t":"ألم عند الرفع (القوس المؤلم)، ألم ليلي، صعوبة النوم على الجانب المصاب. في التمزق تقل قوة الرفع والدوران الخارجي."},{"h":"نقاط التقييم","t":"تقيّم الانحشار باختبار نير واختبار هوكينز-كينيدي، ووظيفة الكفة المدورة باختبار جوب وقوة الدوران الخارجي. قيّم أيضًا حركة لوح الكتف والقوام."},{"h":"مسار العلاج","t":"تسكين الألم وتنظيم النشاط ← تحسين مدى الحركة ← تقوية تدريجية للكفة المدورة وعضلات لوح الكتف ← تدريب الحركة والعودة إلى العمل والرياضة."},{"h":"الحذر وموانع الاستعمال","t":"تجنّب الرفع المتكرر الذي يزيد الألم. لاءم الحمل مع حجم التمزق والخطة الطبية، ولا تفرض الإطالة."},{"h":"علامات الإحالة للطبيب","t":"عجز مفاجئ عن الرفع بعد رضح، ضعف متفاقم، تدهور ألم الراحة، حمى أو تورم، تنميل وأعراض عصبية أخرى."}]},"keypoints":["القوس المؤلم والألم الليلي من الشكاوى الشائعة","ضعف الرفع والدوران الخارجي قد يشير إلى تمزق الكفة المدورة","قيّم حركة لوح الكتف والقوام أيضًا","ارفع حمل التمارين تدريجيًا ضمن حدود الألم","عند العجز المفاجئ عن الرفع بعد رضح أحِل المريض للطبيب"],"case":{"text":"رجل عمره 62 عامًا. يؤلمه كتفه منذ أشهر عند التبعيد، ولديه ألم ليلي أيضًا. الألم شديد في المدى الأوسط من الرفع، واختبار جوب مؤلم مع ضعف واضح.","answer":"اشتباه تضرر وتر العضلة فوق الشوكة أو تمزق الكفة المدورة. اطلب نتيجة الفحص التصويري الطبي والخطة، وتقدّم ضمن حدود الألم بتمارين مدى الحركة والكفة المدورة وعضلات لوح الكتف. تجنّب الرفع المتكرر الذي يزيد الألم."},"questions":[{"level":"أساسي","q":"أي وتر يمر تحت الأخرم ويتهيج بسهولة عند الرفع؟","options":["وتر العضلة فوق الشوكة","وتر العضلة المدورة الصغيرة","وتر العضلة الصدرية الكبيرة","وتر العضلة ثلاثية الرؤوس العضدية"],"answer":0,"exp":"يمر وتر العضلة فوق الشوكة تحت الأخرم، لذا يتهيج بسهولة عند الرفع مع الجراب تحت الأخرم."},{"level":"أساسي","q":"ماذا نسمي ظهور الألم في المدى الأوسط فقط من رفع الكتف؟","options":["متلازمة الكتف واليد","الألم الليلي","القوس المؤلم","علامة سقوط الذراع"],"answer":2,"exp":"إذا ظهر الألم أثناء الرفع وخفّ مع متابعة الرفع نتحدث عن القوس المؤلم. نراه في اضطرابات الحيز تحت الأخرم."},{"level":"متوسط","q":"ماذا يقيّم اختبار هوكينز-كينيدي أساسًا؟","options":["عدم ثبات الكتف الأمامي","الانحشار تحت الأخرم","خلع المفصل الأخرمي الترقوي","متلازمة مخرج الصدر"],"answer":1,"exp":"بإعطاء دوران داخلي والكتف في ثني 90° نلاحظ هل تنحشر البنى تحت الأخرم وتؤلم: اختبار انحشار."},{"level":"متوسط","q":"أي نتيجة تشير أكثر إلى تمزق الكفة المدورة؟","options":["محدودية ثني المرفق","زيادة قوة القبضة","تنميل الأصابع فقط","ضعف الرفع والدوران الخارجي"],"answer":3,"exp":"تشارك الكفة المدورة في الرفع والدوران الخارجي. قد يشير الضعف إلى تمزق، ويؤكده التصوير الطبي."},{"level":"سريري","q":"امرأة عمرها 58 عامًا. منذ سقوطها لا تستطيع رفع ذراعها. يمكن رفعها سلبيًا لا نشطًا. ما الأرجح؟","options":["الكتف المتجمد","تمزق الكفة المدورة","داء الفقار العنقي","خلع الكتف"],"answer":1,"exp":"الحركة السلبية الممكنة مع عجز الرفع النشط تشير إلى خلل وظيفي عضلي وتري؛ وبعد رضح يُشتبه بتمزق الكفة المدورة. في الكتف المتجمد تكون الحركة السلبية محدودة أيضًا."},{"level":"سريري","q":"رجل عمره 45 عامًا، انحشار تحت الأخرم مع ألم مستمر عند الرفع. ما التمرين العلاجي الأولي المناسب؟","options":["رفع متكرر مع تحمّل الألم","الرفع بدمبل ثقيل","تمارين الكفة المدورة ضمن حدود الألم","الراحة التامة"],"answer":2,"exp":"ابدأ بتمارين الكفة المدورة وعضلات لوح الكتف التي لا تزيد الألم، وارفع الحمل تدريجيًا."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الكتف","icono":"💪","mapa":"img/mapas/t23.jpg","fichas":[],"secuencias":[]},"24":{"id":24,"title":"الكتف المتجمد","lead":"في الكتف المتجمد يتطور الألم وتقييد الحركة تدريجيًا؛ وهو شائع في منتصف العمر وعند كبار السن. يجب ملاءمة العلاج مع مرحلة المرض.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"يسبب التهاب المحفظة المفصلية للكتف وتليفها ألمًا وتقييدًا للحركة. السبب غالبًا غير واضح؛ وقد وُصف ارتباط بداء السكري."},{"h":"الأعراض الرئيسية","t":"ألم ليلي، صعوبة في تمشيط الشعر وفي إيصال اليد خلف الظهر. يقل مدى الحركة النشط والسلبي، خاصة الدوران الخارجي."},{"h":"نقاط التقييم","t":"قارن مدى الحركة النشط والسلبي، وقيّم شدة الألم والألم الليلي وصعوبات ADL. من المهم التمييز عن حالات أخرى، مثل تمزق الكفة المدورة."},{"h":"إعادة التأهيل حسب المرحلة","t":"المرحلة الالتهابية: تسكين الألم وتحريك لطيف. مرحلة التيبس: إطالة وتمارين مدى الحركة ضمن حدود الألم. مرحلة الانفراج: استعادة مدى الحركة والقوة العضلية."},{"h":"الحذر وموانع الاستعمال","t":"في المرحلة الالتهابية قد تزيد الإطالة القوية الألم. تجنّب التحريك السلبي القسري الذي يتطلب تحمّل الألم."},{"h":"علامات الإحالة للطبيب","t":"بداية بعد رضح، ضعف مفاجئ، حمى أو تورم، أعراض عامة (مثل نقص الوزن)، تدهور مفاجئ لألم الراحة."}]},"keypoints":["من المميز أن يقل مدى الحركة النشط والسلبي معًا","تقييد الدوران الخارجي لافت بشكل خاص","في المرحلة الالتهابية تجنّب الإطالة التي تزيد الألم","غيّر هدف العلاج حسب المرحلة","ميّزه عن حالات أخرى، مثل تمزق الكفة المدورة"],"case":{"text":"امرأة عمرها 55 عامًا. بدأ كتفها يؤلمها دون سبب واضح، ولا تستطيع النوم ليلًا من الألم. خلال بضعة أشهر أصبح تمشيط الشعر وإيصال اليد خلف الظهر صعبًا؛ والدوران الخارجي محدود بشدة نشطًا وسلبيًا.","answer":"اشتباه كتف متجمد. استبعد الحالات الأخرى بالتشخيص الطبي، وحدّد المرحلة الحالية. أثناء الألم الشديد تجنّب الإطالة القوية؛ وابدأ بتسكين الألم والتحريك اللطيف."},"questions":[{"level":"أساسي","q":"أي حركة تكون محدودة بشكل خاص في الكتف المتجمد؟","options":["ثني المرفق","العطف الظهري للرسغ","رفع لوح الكتف","الدوران الخارجي للكتف"],"answer":3,"exp":"في الكتف المتجمد تنكمش المحفظة فيتقيد الكتف في عدة اتجاهات، خاصة الدوران الخارجي."},{"level":"أساسي","q":"في الكتف المتجمد، أي مرحلة يخف فيها الألم ويبرز تقييد الحركة؟","options":["المرحلة الالتهابية","مرحلة التيبس","مرحلة الانفراج","المرحلة الحادة"],"answer":1,"exp":"عندما يهدأ الألم الشديد للمرحلة الالتهابية تأتي مرحلة التيبس التي يميزها تقييد الحركة، ثم مرحلة الانفراج."},{"level":"متوسط","q":"أي نتيجة تساعد على تمييز الكتف المتجمد عن تمزق الكفة المدورة؟","options":["وجود الألم الليلي","تقييد مدى الحركة السلبي","العمر","موضع الألم"],"answer":1,"exp":"في الكتف المتجمد يكون مدى الحركة السلبي محدودًا أيضًا. في تمزق الكفة المدورة تكون الحركة السلبية جيدة نسبيًا، لكن الرفع النشط صعب غالبًا."},{"level":"متوسط","q":"ما العلاج الأنسب في المرحلة الالتهابية للكتف المتجمد؟","options":["تسكين الألم وتحريك لطيف","إطالة سلبية قوية","تقوية بحمل عالٍ","تدريب العودة إلى الرياضة"],"answer":0,"exp":"في المرحلة الالتهابية يكون الألم شديدًا وقد تزيده الإطالة القوية سوءًا. العنصر الأساسي هو تسكين الألم وتحريك لا يزيد الألم."},{"level":"سريري","q":"امرأة عمرها 52 عامًا، كتف متجمد في مرحلة التيبس. الألم خفيف، والدوران الخارجي وإيصال اليد خلف الظهر محدودان. ما العلاج المناسب؟","options":["الراحة التامة","التثبيت بحمالة مثلثة","تمارين مدى الحركة ضمن حدود الألم","إطالة قوية مع تحمّل الألم"],"answer":2,"exp":"في مرحلة التيبس يكون الألم قد خفّ، لذا تقدّم بالإطالة وتمارين مدى الحركة ضمن حدود الألم."},{"level":"سريري","q":"رجل عمره 60 عامًا. إلى جانب ألم الكتف وتقييد الحركة نقص وزنه مؤخرًا، ولديه ألم راحة شديد. ما التصرف الصحيح؟","options":["إحالته للطبيب","زيادة تمارين مدى الحركة","علاج حراري ومراقبة فقط","البدء بتقوية العضلات"],"answer":0,"exp":"نقص الوزن وألم الراحة الشديد من العلامات الحمراء لمرض خطير. أحِله أولًا للفحص الطبي."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الكتف","icono":"💪","mapa":"img/mapas/t24.jpg","fichas":[],"secuencias":[]},"25":{"id":25,"title":"بعد إصلاح الكفة المدورة","lead":"تعيد إعادة التأهيل بعد إصلاح الكفة المدورة مدى الحركة والقوة العضلية تدريجيًا مع حماية الوتر المُخاط. الشرط الأساسي الالتزام بالتوقيتات والقيود التي يحددها الطبيب.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"يُعاد تثبيت الكفة المدورة الممزقة بالعظم جراحيًا. يحتاج التئام الوتر المُخاط بالعظم وقتًا، وقد يسبب التحميل المبكر جدًا إعادة التمزق."},{"h":"الأعراض الرئيسية","t":"ألم ما بعد الجراحة وألم ليلي، تقييد الحركة، ضعف. بسبب الجبيرة قد يتصلب حزام الكتف والرقبة، وقد تقل حركة المرفق واليد."},{"h":"نقاط التقييم","t":"قيّم الألم ومدى الحركة السلبي والنشط وحركة لوح الكتف والقوة العضلية وADL. راجع تقرير العملية وتعليمات الطبيب (الأوضاع الممنوعة، التوقيتات)."},{"h":"إعادة التأهيل حسب المرحلة","t":"مرحلة الحماية (جبيرة، تحريك سلبي) ← تحريك نشط مُساعد ونشط ← تقوية عضلية تدريجية ← العودة إلى الأنشطة اليومية والعمل والرياضة."},{"h":"الحذر وموانع الاستعمال","t":"تجنّب الرفع النشط وتمارين المقاومة قبل الموعد المحدد، والأوضاع التي تشد الوتر المُخاط بقوة. حرّك المرفق والأصابع حتى أثناء التثبيت."},{"h":"علامات الإحالة للطبيب","t":"زيادة مفاجئة في الألم أو نقص قوة الرفع (اشتباه إعادة التمزق)، احمرار حول الجرح، تورم، سخونة، حمى، ظهور تنميل."}]},"keypoints":["تحقق من التوقيتات والأوضاع الممنوعة في تعليمات الطبيب وتقرير العملية","في مرحلة الحماية احمِ الوتر المُخاط، والتحريك السلبي هو المحور","درّب المرفق والأصابع ولوح الكتف حتى أثناء التثبيت","أعطِ تمارين المقاومة تدريجيًا بدءًا من الموعد المحدد","عند النقص المفاجئ لقوة الرفع فكّر في إعادة التمزق وأحِل للطبيب"],"case":{"text":"رجل عمره 60 عامًا، في المرحلة المبكرة بعد إصلاح الكفة المدورة، يرتدي جبيرة. لأنه يريد العودة سريعًا إلى العمل، تدرّب وحده على رفع الذراع.","answer":"في مرحلة الحماية يُجهد الرفع النشط غير الموصوف الوتر المُخاط. راجع تعليمات الطبيب، وركّز على التحريك السلبي المسموح وتمارين المرفق والأصابع، واشرح أهمية الالتزام بالتوقيتات."},"questions":[{"level":"أساسي","q":"ما الهدف الأساسي للجبيرة في المرحلة المبكرة بعد إصلاح الكفة المدورة؟","options":["زيادة القوة العضلية","زيادة مدى الحركة","حماية الوتر المُخاط","الوقاية من الوذمة"],"answer":2,"exp":"في مرحلة الحماية تثبّت الجبيرة الكتف وتحمي الوتر المُخاط حتى يلتئم بالعظم."},{"level":"أساسي","q":"في إعادة التأهيل بعد إصلاح الكفة المدورة، ما الذي يُدخل في النهاية؟","options":["التثبيت بالجبيرة","التحريك السلبي","التحريك النشط المُساعد","تمارين المقاومة"],"answer":3,"exp":"بعد التثبيت والتحريك السلبي في مرحلة الحماية يأتي التحريك النشط المُساعد والنشط، وأخيرًا التقوية بالمقاومة."},{"level":"متوسط","q":"أي حركة يجب تجنبها في مرحلة الحماية بعد الإصلاح؟","options":["الرفع النشط للكتف قبل الموعد المحدد","الثني والبسط النشط للمرفق","تمارين الأصابع","التحريك السلبي الموصوف"],"answer":0,"exp":"في مرحلة الحماية يُجهد الرفع النشط غير الموصوف الوتر المُخاط. يستمر تحريك المرفق والأصابع حتى أثناء التثبيت."},{"level":"متوسط","q":"ما الذي يجب التحقق منه أولًا عند تخطيط مسار تمارين ما بعد الجراحة؟","options":["رغبة المريض فقط","تعليمات الطبيب وتقرير العملية","القوة العضلية للجانب السليم","العمر فقط"],"answer":1,"exp":"تختلف التوقيتات والأوضاع الممنوعة حسب حجم التمزق وتقنية الخياطة، لذا راجع التعليمات والتقرير."},{"level":"سريري","q":"امرأة عمرها 65 عامًا، تقدمت جيدًا بعد إصلاح الكفة المدورة، لكنها شعرت بألم عند رفع شيء ولا تستطيع فجأة رفع ذراعها. ما التصرف؟","options":["زيادة تمارين المقاومة","متابعة التمارين نفسها","إطالة قوية","إبلاغ الطبيب وطلب الفحص"],"answer":3,"exp":"قد يشير الألم المفاجئ ونقص قوة الرفع إلى إعادة التمزق. أوقف التمارين واطلب فحصًا طبيًا."},{"level":"سريري","q":"رجل عمره 58 عامًا، بعد إصلاح الكفة المدورة ويرتدي جبيرة. يشكو من تيبس المرفق والأصابع. ما التصرف الصحيح؟","options":["تعليم تمارين المرفق والأصابع","البدء بالرفع النشط للكتف","لا شيء، متابعة التثبيت","تمارين مقاومة للكتف"],"answer":0,"exp":"حرّك المرفق والأصابع حتى أثناء التثبيت للوقاية من التيبس. ينتظر الرفع النشط للكتف والمقاومة حتى الموعد المحدد."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الكتف","icono":"💪","mapa":"img/mapas/t25.jpg","fichas":[],"secuencias":[]},"26":{"id":26,"title":"اعتلالات الأوتار","lead":"في اعتلال الوتر لا يستطيع الوتر التكيف مع الحمل المتكرر، فيظهر الألم ونقص الوظيفة. مفتاح التعافي ليس الراحة، بل تنظيم الحمل ورفعه تدريجيًا.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"يتجاوز الحمل المتكرر على الوتر قدرته على التجدد، فتتغير بنية الوتر ووظيفته ويظهر الألم. من الأسباب الشائعة الزيادة المفاجئة في حجم التدريب."},{"h":"الأعراض الرئيسية","t":"ألم وتيبس في بداية الحركة وصباح اليوم التالي، ألم موضعي بالضغط على الوتر. قد يخف أثناء الحركة ويسوء بعد التحميل."},{"h":"نقاط التقييم","t":"افحص ألم الوتر بالضغط والألم مع التحميل (رفع الكعب على ساق واحدة، القرفصاء على ساق واحدة)، واسأل عن تغير حجم التدريب والحذاء والأرضية."},{"h":"مسار العلاج","t":"تنظيم الحمل ← تمارين متساوية القياس ← تقوية متساوية التوتر (تشمل اللامركزية) ← حركات سريعة مثل القفز ← العودة إلى الرياضة."},{"h":"الحذر وموانع الاستعمال","t":"قد تقلل الراحة التامة قدرة الوتر على تحمّل الحمل. تجنّب الحمل الذي يزيد الألم بشكل واضح والألم الشديد الذي يستمر حتى اليوم التالي."},{"h":"علامات الإحالة للطبيب","t":"إحساس مفاجئ بالتمزق أو صوت فرقعة، ضعف واضح، تورم وسخونة شديدان، ألم ليلي أو ألم راحة لا يتحسن."}]},"keypoints":["الزيادة المفاجئة في حجم التدريب تثير اعتلال الوتر كثيرًا","بدل الراحة التامة نظّم الحمل بما يلائم الألم","اضبط كمية الحمل حسب الألم بعد التحميل وفي اليوم التالي","تقدّم تدريجيًا من التمارين المتساوية القياس نحو حمل أكبر","عند الإحساس بالتمزق أو الضعف المفاجئ أحِل المريض للطبيب"],"case":{"text":"رجل عداء عمره 28 عامًا. منذ أن زاد مسافة الجري فجأة يصبح وتر أكيلس متيبسًا ومؤلمًا صباحًا لفترة طويلة. يؤلمه في بداية الجري ويخف أثناءه. يوجد ألم بالضغط على الجزء الأوسط من الوتر.","answer":"اشتباه اعتلال وتر أكيلس. لا تنصح بالراحة التامة، بل نظّم كمية الجري وتقدّم بتحميل متدرج يلائم الألم، مثل رفع الكعب. عند الإحساس بالتمزق أو الضعف أحِله للطبيب."},"questions":[{"level":"أساسي","q":"ما السبب النموذجي لاعتلال الوتر؟","options":["الراحة الطويلة","الزيادة المفاجئة في حجم التدريب","النوم الكافي","تحسن المرونة"],"answer":1,"exp":"الحمل الذي يتجاوز قدرة الوتر على التجدد، خاصة الزيادة المفاجئة في حجم التدريب، هو السبب النموذجي لاعتلال الوتر."},{"level":"أساسي","q":"ما خاصية الألم الشائعة في اعتلال الوتر؟","options":["ألم ليلي شديد فقط","يسوء باستمرار في الراحة","بالشدة نفسها دائمًا","ألم بداية الحركة، تيبس صباحي"],"answer":3,"exp":"يظهر الألم والتيبس في بداية الحركة وصباح اليوم التالي، وغالبًا يخف أثناء الحركة."},{"level":"متوسط","q":"في التحميل المتدرج لاعتلال الوتر، ما الذي يُدخل متأخرًا نسبيًا؟","options":["التمارين المتساوية القياس","التقوية البطيئة","الحركات السريعة مثل القفز","تنظيم الحمل"],"answer":2,"exp":"مع التحكم في الألم تزيد قدرة التحمل بالتمارين المتساوية القياس والمتساوية التوتر، ثم تنتقل إلى الحركات السريعة مثل القفز."},{"level":"متوسط","q":"ما المرجع المناسب لإعادة النظر في حمل اعتلال الوتر؟","options":["تغير الألم في اليوم التالي","تغير وزن الجسم","درجة الحرارة","وقت التدريب من اليوم"],"answer":0,"exp":"لا تراقب الألم أثناء الحركة فقط، بل أيضًا تغير الألم والتيبس في اليوم التالي، واضبط الحمل وفقه."},{"level":"سريري","q":"لاعبة كرة طائرة عمرها 22 عامًا. بعد القفز يؤلمها القطب السفلي للرضفة، والرباط الرضفي مؤلم بالضغط. ما الأرجح؟","options":["إصابة الرباط الصليبي الأمامي","اعتلال الوتر الرضفي","إصابة الغضروف الهلالي","خلع الرضفة"],"answer":1,"exp":"القفز المتكرر مع ألم بالضغط على القطب السفلي للرضفة والرباط الرضفي نمط مميز لاعتلال الوتر الرضفي."},{"level":"سريري","q":"رجل عمره 40 عامًا تعالجه من اعتلال وتر أكيلس. أثناء التنس شعر وكأنه رُكل من الخلف؛ لا يستطيع الوقوف على أطراف أصابعه. ما التصرف؟","options":["متابعة التمرين اللامركزي","زيادة الحمل أكثر","زيادة الإطالة","إحالته للطبيب لاشتباه تمزق"],"answer":3,"exp":"الإحساس المفاجئ بضربة والعجز عن الوقوف على أطراف الأصابع يشيران إلى تمزق وتر أكيلس. أوقف التمارين وأحِله للفحص الطبي."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الرياضة والأوتار والعضلات","icono":"🏃","mapa":"img/mapas/t26.jpg","fichas":[],"secuencias":[]},"27":{"id":27,"title":"التواء الكاحل","lead":"التواء الكاحل من أكثر الإصابات الرياضية شيوعًا؛ ويحدث غالبًا في القلب للداخل مع العطف الأخمصي. التدريب على الحس العميق أساسي في الوقاية من تكرار الالتواء.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"في القلب للداخل مع العطف الأخمصي تُصاب الأربطة الوحشية. الأكثر إصابة هو الرباط الكاحلي الشظوي الأمامي، وفي الحالات الأشد الرباط العقبي الشظوي أيضًا."},{"h":"الأعراض الرئيسية","t":"ألم وتورم وكدمة حول الكعب الوحشي، وألم عند التحميل. قد يذكر المريض إحساسًا بعدم الثبات أو التواءات متكررة."},{"h":"نقاط التقييم","t":"آلية الإصابة، موضع الألم بالضغط، القدرة على التحميل، اختبار الدرج الأمامي واختبار إمالة الكاحل. لا تغفل عن الكسر وإصابة الأربطة الأخرى."},{"h":"إعادة التأهيل حسب المرحلة","t":"1 حماية، تبريد، ضغط، رفع ← 2 الحركية والتحميل المتدرج ← 3 تقوية العضلات والحس العميق ← 4 الجري والقفز والعودة إلى الرياضة."},{"h":"الحذر وموانع الاستعمال","t":"في المرحلة الحادة تجنّب التمارين التي تزيد الألم. إذا أُهمل تدريب الحس العميق والتوازن يتكرر الالتواء بسهولة ويبقى الإحساس بعدم الثبات."},{"h":"علامات الإحالة للطبيب","t":"ألم عظمي بالضغط أو عجز عن التحميل (اشتباه كسر)، تورم واضح أو تشوه، تنميل، ألم لا يتحسن أو عدم ثبات متكرر."}]},"keypoints":["آلية الإصابة غالبًا القلب للداخل مع العطف الأخمصي","الأكثر إصابة هو الرباط الكاحلي الشظوي الأمامي","عند وجود ألم عظمي بالضغط أو عجز عن التحميل فكّر في الكسر","التدريب على الحس العميق يقلل خطر تكرار الإصابة","العودة إلى الرياضة تدريجية، بعد التحقق من الحركات على ساق واحدة"],"case":{"text":"رجل عمره 19 عامًا. التوت قدمه للداخل أثناء كرة القدم. في اليوم التالي يوجد تورم وألم بالضغط أمام الكعب الوحشي، دون ألم عظمي، ويستطيع التحميل. في اختبار الدرج الأمامي الانزياح أكبر من الجانب السليم.","answer":"اشتباه التواء بالقلب للداخل مع إصابة الرباط الكاحلي الشظوي الأمامي. ابدأ بالحماية والتبريد والضغط والرفع وتحميل يلائم الألم، ثم بعد التقوية وتدريب الحس العميق يعود تدريجيًا إلى الرياضة."},"questions":[{"level":"أساسي","q":"في الشكل، ما آلية الإصابة النموذجية لالتواء الكاحل؟","options":["قلب للخارج مع عطف ظهري","قلب للداخل مع عطف أخمصي","قلب للداخل مع عطف ظهري","قلب للخارج مع عطف أخمصي"],"answer":1,"exp":"يحدث التواء الكاحل غالبًا في القلب للداخل مع العطف الأخمصي، والرباط الكاحلي الشظوي الأمامي الوحشي هو الأكثر إصابة."},{"level":"أساسي","q":"في الشكل، ما محتوى المرحلة 3؟","options":["حماية، تبريد، ضغط، رفع","الحركية والتحميل المتدرج","تقوية العضلات والحس العميق","الجري والعودة إلى الرياضة"],"answer":2,"exp":"المرحلة 1: حماية وتبريد وضغط ورفع؛ 2: الحركية والتحميل؛ 3: تقوية العضلات والحس العميق؛ 4: العودة إلى الرياضة."},{"level":"متوسط","q":"في أي مرحلة يبدأ التحميل المتدرج؟","options":["المرحلة 1","المرحلة 2","المرحلة 3","المرحلة 4"],"answer":1,"exp":"بعد حماية المرحلة 1، في المرحلة 2 تزيد الحمل تدريجيًا بما يلائم الألم مع تحسين الحركية."},{"level":"متوسط","q":"أي تدريب مهم بشكل خاص للوقاية من تكرار التواء الكاحل؟","options":["التثبيت الطويل","الراحة التامة","تقوية عضلات الطرف العلوي","التدريب على الحس العميق"],"answer":3,"exp":"يقلل التدريب على الحس العميق بلوح التوازن أو الوقوف على ساق واحدة خطر تكرار الإصابة."},{"level":"سريري","q":"امرأة عمرها 24 عامًا. بعد 3 أسابيع من الالتواء لا يكاد يوجد ألم، لكن كاحلها يتمايل في الوقوف على ساق واحدة. أي علاج له الأولوية؟","options":["تمارين التوازن والحس العميق","التبريد والرفع","الراحة التامة","ركض سريع بأقصى سرعة فورًا"],"answer":0,"exp":"هدأ الألم لكن بقي عدم الثبات. الأولوية لتمارين الحس العميق والتقوية في الوقوف على ساق واحدة، ثم العودة التدريجية."},{"level":"سريري","q":"رجل عمره 20 عامًا. التوى كاحله مرات عديدة، ويشعر بتمايله في الحياة اليومية أيضًا. بماذا تفكر؟","options":["تمزق وتر أكيلس","التهاب اللفافة الأخمصية","عدم ثبات الكاحل المزمن","إبهام القدم الأروح"],"answer":2,"exp":"الالتواء المتكرر والإحساس بعدم الثبات يشيران إلى عدم ثبات الكاحل المزمن. تدريب الحس العميق والتقوية مهم، مع استشارة طبية عند الحاجة."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الرياضة والأوتار والعضلات","icono":"🏃","mapa":"img/mapas/t27.jpg","fichas":[],"secuencias":[]},"28":{"id":28,"title":"الإصابات العضلية","lead":"الإصابة العضلية إصابة رياضية، شكلاها الرئيسيان الشد العضلي (تمزق جزئي) والكدمة العضلية. تتكرر كثيرًا، لذا من المهم التحميل المتدرج وتحديد معايير العودة.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"يحدث الشد غالبًا في الانقباض اللامركزي (العضلة المشدودة تستطيل)، وأكثر ما يكون في الاتصال العضلي الوتري. الكدمة إصابة بقوة خارجية مباشرة، غالبًا في العضلة رباعية الرؤوس الفخذية."},{"h":"الأعراض الرئيسية","t":"ألم أو إحساس بالتمزق لحظة الإصابة، ألم بالضغط، تورم، كدمة، ألم مع الإطالة والمقاومة، نقص القوة. في الحالات الشديدة يُجس انخفاض."},{"h":"نقاط التقييم","t":"آلية الإصابة، نقطة الألم بالضغط، ألم الإطالة (مثل فرق زاوية SLR بين الجانبين)، الألم مع المقاومة، نمط المشي. يقيّم الطبيب الشدة مع نتائج التصوير."},{"h":"إعادة التأهيل حسب المرحلة","t":"في المرحلة الحادة حماية وتحكم في التورم. حسب الألم: متساوي القياس ← مركزي ← لامركزي، والجري تدريجيًا أيضًا. قبل العودة تحقق من الحركات الرياضية."},{"h":"الحذر وموانع الاستعمال","t":"في المرحلة الحادة تجنّب الإطالة القوية والتدليك القوي. بعد كدمة الفخذ قد يُحدث المنبه القوي التهاب العضل المتعظم. لا تُشغّل العضلة مع الألم."},{"h":"علامات الإحالة للطبيب","t":"انخفاض واضح أو إحساس بالتمزق، تورم يتزايد بسرعة، ألم شديد مستمر، تنميل أو تغير لون الجلد (اشتباه متلازمة الحيز)."}]},"keypoints":["الشد أكثر شيوعًا في الانقباض اللامركزي وفي الاتصال العضلي الوتري","في المرحلة الحادة حماية وتحكم في التورم، دون إطالة قوية","ترتيب الحمل: متساوي القياس ← مركزي ← لامركزي","في أوتار المأبض أدرج التدريب اللامركزي","قرّر العودة بناءً على الألم والمرونة والقوة العضلية والحركة الرياضية"],"case":{"text":"رجل عداء مسافات قصيرة عمره 20 عامًا. أثناء العدو بأقصى سرعة شعر بألم في خلف الفخذ وأوقف السباق. في اليوم التالي يوجد ألم بالضغط وكدمة فوق العضلة ذات الرأسين الفخذية، وفي SLR فرق بين الجانبين وألم إطالة.","answer":"نفكر في شد أوتار المأبض. في المرحلة الحادة الأولوية للحماية والتحكم في التورم، وتجنّب الإطالة القوية والتدليك. حسب الألم ابدأ بالعمل المتساوي القياس وارفع الحمل تدريجيًا. عند الانخفاض أو علامة خطيرة أخرى أحِله للطبيب."},"questions":[{"level":"أساسي","q":"أين يحدث الشد العضلي غالبًا؟","options":["في منتصف بطن العضلة","في الاتصال العضلي الوتري","في السمحاق","عند ارتكاز الوتر على العظم"],"answer":1,"exp":"يحدث الشد غالبًا عند الاتصال بين العضلة والوتر. في أوتار المأبض يصيب أساسًا الرأس الطويل للعضلة ذات الرأسين الفخذية."},{"level":"أساسي","q":"مع أي نوع من الانقباض يحدث الشد غالبًا؟","options":["متساوي القياس","مركزي","لامركزي","متساوي الحركة"],"answer":2,"exp":"في الانقباض اللامركزي، عندما تستطيل العضلة المشدودة؛ والوضع النموذجي نهاية مرحلة التأرجح في العدو السريع."},{"level":"متوسط","q":"ما الترتيب المعتاد للتقوية بعد الشد؟","options":["لامركزي ← مركزي ← متساوي القياس","متساوي القياس ← مركزي ← لامركزي","مركزي ← متساوي القياس ← لامركزي","عمل لامركزي أقصى فورًا"],"answer":1,"exp":"حسب الألم نبدأ بعمل متساوي القياس منخفض الحمل، ثم الانقباض المركزي، وأخيرًا اللامركزي."},{"level":"متوسط","q":"لماذا نتجنب التدليك والإطالة القويين بعد كدمة الفخذ؟","options":["قد يُحدثان التهاب العضل المتعظم","يزول ضمور العضلة","يقصر الوتر","يتوقف تجدد العصب"],"answer":0,"exp":"قد يزيد المنبه القوي المبكر بعد الكدمة النزف داخل العضلة، ويؤدي إلى التهاب العضل المتعظم."},{"level":"سريري","q":"لاعب كرة قدم: عند الركل ظهر ألم في مقدمة الفخذ، وفي اليوم التالي ما زال مؤلمًا بالضغط ومع الإطالة. ما التصرف الصحيح في المرحلة الحادة؟","options":["إطالة قوية","حماية وتحكم في التورم","التحقق بعدو سريع كامل","تدليك قوي"],"answer":1,"exp":"في المرحلة الحادة الأولوية للحماية والتحكم في التورم. قد تزيد الإطالة القوية والتدليك واختبار الحركة الأقصى الإصابة سوءًا."},{"level":"سريري","q":"طالب ثانوي تلقى فخذه ضربة قوية. التورم يزداد بسرعة، ويشكو من ألم شديد وتنميل في الساق. ما التصرف الأول؟","options":["علاج حراري","تعليم الإطالة","إحالة فورية للفحص الطبي","البدء بالتقوية"],"answer":2,"exp":"التورم المتزايد بسرعة والألم الشديد والتنميل تشير إلى متلازمة الحيز، ويلزم فحص طبي عاجل."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الرياضة والأوتار والعضلات","icono":"🏃","mapa":"img/mapas/t28.jpg","fichas":[],"secuencias":[]},"29":{"id":29,"title":"إصابة الرباط الصليبي الأمامي والغضروف الهلالي","lead":"إصابة ACL شائعة في الرياضة عند الهبوط أو تغيير الاتجاه، وكثيرًا ما تترافق مع إصابة الغضروف الهلالي. يحدد الإنذارَ الفحصُ المبكر وإعادة تعليم أنماط الحركة.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"تحدث إصابة ACL غالبًا دون احتكاك، عند الهبوط أو تغيير الاتجاه، ولأروح الركبة ودوران الساق دور فيها. يُصاب الغضروف الهلالي في الدوران تحت الحمل، وغالبًا مع ACL."},{"h":"الأعراض الرئيسية","t":"ACL: صوت فرقعة عند الإصابة، تورم بسبب تدمّي المفصل، انفلات الركبة (giving way). الغضروف الهلالي: ألم في الشق المفصلي، إحساس بالانحشار، انغلاق (locking)، تقييد الحركة."},{"h":"نقاط التقييم","t":"ACL: اختبار لاكمان، اختبار الدرج الأمامي، اختبار التحول المحوري. الغضروف الهلالي: ألم الشق المفصلي بالضغط، اختبار ماكموري. التشخيص النهائي يضعه الطبيب."},{"h":"مسار العلاج","t":"في المرحلة الحادة تحكم في التورم، وتأمين مدى البسط وانقباض العضلة رباعية الرؤوس. يقرر الطبيب العلاج التحفظي أو إعادة بناء الرباط. ابنِ القوة ومدى الحركة قبل الجراحة أيضًا."},{"h":"الحذر وموانع الاستعمال","t":"قد يزيد انفلات الركبة المتكرر تضرر الغضروف الهلالي والغضروف المفصلي. في الركبة المنغلقة لا تفرض تمارين مدى الحركة. انتبه لانهيار الركبة للداخل أثناء الحركة."},{"h":"علامات الإحالة للطبيب","t":"ركبة لا تُبسط بسبب الانغلاق، تورم مفصلي سريع بعد الإصابة مباشرة، انفلات متكرر للركبة، ألم شديد مستمر، علامات تشير إلى كسر."}]},"keypoints":["إصابة ACL غالبًا دون احتكاك، والوضع الخطر هو انهيار الركبة للداخل","أساس تقييم ACL هو اختبار لاكمان","إصابة الغضروف الهلالي: ألم الشق المفصلي بالضغط وإحساس بالانحشار","إذا لم تُبسط الركبة بسبب الانغلاق أحِل للطبيب","للوقاية علّم تقنية الهبوط وتغيير الاتجاه"],"case":{"text":"لاعبة كرة سلة عمرها 17 عامًا. عند الهبوط من قفزة انهارت ركبتها للداخل، وسمعت صوت فرقعة وسقطت. خلال بضع ساعات تورمت الركبة؛ ويُظهر اختبار لاكمان انزياحًا أماميًا زائدًا وغياب الشعور النهائي.","answer":"اشتباه إصابة ACL. في المرحلة الحادة الأولوية للتحكم في التورم وتأمين مدى البسط وانقباض العضلة رباعية الرؤوس. لاحتمال إصابة هلالية مرافقة اسأل عن الانغلاق. يقرر الطبيب العلاج التحفظي أو إعادة البناء؛ ولا تعود إلى الرياضة بقرار ذاتي."},"questions":[{"level":"أساسي","q":"ما الوضع النموذجي لإصابة ACL دون احتكاك؟","options":["أفحج الركبة (الركبة للخارج)","أروح الركبة (الركبة تنهار للداخل)","فرط ثني الركبة","ضربة مباشرة على الرضفة"],"answer":1,"exp":"تحدث إصابة ACL دون احتكاك نموذجيًا عند الهبوط أو تغيير الاتجاه، حين تنهار الركبة للداخل (أروح)."},{"level":"أساسي","q":"أي عرض يميز إصابة الغضروف الهلالي؟","options":["الانغلاق (locking)","تدلي القدم","غياب المنعكس الرضفي","نقص الإحساس في مقدمة الفخذ"],"answer":0,"exp":"إذا انحشر الجزء المصاب من الغضروف الهلالي داخل المفصل تتوقف الركبة عند زاوية معينة: هذا هو الانغلاق."},{"level":"متوسط","q":"أي اختبار يدوي هو الأكثر حساسية لإصابة ACL؟","options":["اختبار ماكموري","اختبار الدرج الخلفي","اختبار لاكمان","اختبار إجهاد الأروح"],"answer":2,"exp":"يسحب اختبار لاكمان الظنبوب إلى الأمام والركبة مثنية قليلًا، ويقيّم الانزياح والشعور النهائي. هو أساس تقييم ACL."},{"level":"متوسط","q":"ما نتيجة اختبار ماكموري الإيجابي؟","options":["انزياح أمامي زائد للظنبوب","طقطقة وألم عند البسط مع الدوران","إحساس بعدم ثبات الرضفة","انفتاح الشق المفصلي الإنسي"],"answer":1,"exp":"من الركبة المثنية نبسط مع تدوير الساق؛ إذا ظهرت طقطقة أو ألم في الشق المفصلي نشتبه بإصابة الغضروف الهلالي."},{"level":"سريري","q":"لاعب كرة قدم: التوت ركبته عند تغيير الاتجاه، ومنذ ذلك تنحشر ولا يستطيع بسطها تمامًا. ما الأرجح؟","options":["اعتلال الوتر الرضفي","متلازمة الشريط الحرقفي الظنبوبي","انغلاق بسبب إصابة الغضروف الهلالي","داء أوسغود-شلاتر"],"answer":2,"exp":"العجز عن البسط بعد إصابة دورانية يشير إلى الانغلاق. لا تفرض تمارين مدى الحركة، وأحِله للفحص الطبي."},{"level":"سريري","q":"اليوم الثاني بعد إصابة ACL، والركبة متورمة. ما الأولوية في بداية العلاج التحفظي؟","options":["تدريب القفز","التحكم في التورم وتأمين البسط","تدريب تغيير الاتجاه الأقصى","قرفصاء عميقة مع حمل"],"answer":1,"exp":"في البداية نعالج التورم ونؤمّن مدى البسط وانقباض العضلة رباعية الرؤوس. قد يسبب الحمل العالي انفلات الركبة وإصابة ثانوية."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الرياضة والأوتار والعضلات","icono":"🏃","mapa":"img/mapas/t29.jpg","fichas":[],"secuencias":[]},"30":{"id":30,"title":"بعد إعادة بناء الرباط الصليبي الأمامي","lead":"تعيد إعادة التأهيل بعد إعادة بناء ACL مدى الحركة والقوة العضلية وأنماط الحركة تدريجيًا مع حماية الطُّعم. الهدف الأول: ألا يبقى تقييد في البسط.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية والجراحة","t":"يُعاد بناء الرباط من وتر ذاتي (مثل وتر المأبض أو طُعم عظم-وتر رضفي-عظم). يُعاد تشكّل الطُّعم بعد الجراحة، ولا يكتسب متانته إلا مع الوقت."},{"h":"مهام ما بعد الجراحة","t":"في البداية يشيع التورم والألم وتقييد البسط وضعف تفعيل العضلة رباعية الرؤوس. انتبه أيضًا لألم وضعف موضع أخذ الطُّعم."},{"h":"نقاط التقييم","t":"التورم، فرق بسط وثني الركبة بين الجانبين، الانقباض الإرادي للعضلة رباعية الرؤوس (extension lag)، نمط المشي، القوة العضلية، الاختبارات الوظيفية (مثل اختبارات القفز)."},{"h":"إعادة التأهيل حسب المرحلة","t":"الأسبوع 0–2: بسط كامل، رباعية الرؤوس. 2–6: مشي طبيعي، زيادة الثني. 6–12: القوة، الحس العميق. الشهر 3–6: جري وقفز تدريجي. من الشهر 6: اختبارات العودة."},{"h":"الحذر وموانع الاستعمال","t":"لا تترك تقييدًا في البسط. يحدد بدء التمارين التي تُجهد الطُّعم تقنيةُ الجراحة وتعليمات الجراح. إذا زاد التورم فقلّل الحمل؛ ولا تتقدم بناءً على الوقت وحده."},{"h":"علامات الإحالة للطبيب","t":"حمى، احمرار الجرح أو سخونته أو إفراز صديدي، تورم يزداد فجأة، ألم وتورم الربلة (اشتباه خثار وريدي عميق)، انفلات الركبة."}]},"keypoints":["الهدف الأول هو الوصول إلى البسط الكامل","فعّل العضلة رباعية الرؤوس إراديًا منذ وقت مبكر","لا تتقدم بناءً على الوقت فقط، بل على التورم ومدى الحركة والقوة العضلية","تقرر الاختبارات الوظيفية والطبيب العودة إلى الرياضة","للوقاية من الإصابة مجددًا علّم الهبوط وتغيير الاتجاه"],"case":{"text":"رجل عمره 22 عامًا، بعد أسبوعين من إعادة بناء ACL. الركبة متورمة قليلًا، والبسط −10°. انقباض العضلة رباعية الرؤوس ضعيف، ويُلاحظ extension lag. يقول إنه يريد الجري في أقرب وقت.","answer":"في هذه المرحلة الأولوية للوصول إلى البسط الكامل والتحكم في العضلة رباعية الرؤوس، والجري ما زال مبكرًا. يؤدي تقييد البسط المتبقي إلى مشي مرضي وألم أمام الركبة. عالج التورم، ولا تتقدم إلا بعد تحقق المعايير."},"questions":[{"level":"أساسي","q":"ما الهدف الأساسي لإعادة التأهيل بعد إعادة بناء ACL؟","options":["تدريب قفز مبكر","الوصول إلى الثني العميق أولًا","استعادة البسط الكامل","الجري مباشرة بعد الجراحة"],"answer":2,"exp":"يؤدي تقييد البسط المتبقي إلى مشي مرضي وألم أمام الركبة، لذا فاستعادة البسط الكامل هي الأولوية."},{"level":"أساسي","q":"في أي مرحلة تُجرى اختبارات العودة إلى الرياضة؟","options":["المرحلة 2 (الأسبوع 2–6)","المرحلة 3 (الأسبوع 6–12)","المرحلة 4 (الشهر 3–6)","المرحلة 5 (من الشهر 6)"],"answer":3,"exp":"تُجرى اختبارات العودة في المرحلة الأخيرة، المرحلة 5 (من الشهر 6)، بناءً على نتائج اختبارات القوة والوظيفة."},{"level":"متوسط","q":"ماذا يعني extension lag الذي يُقيّم في المرحلة المبكرة بعد الجراحة؟","options":["عدم ثبات الركبة الأمامي","البسط النشط أقل من السلبي","تقييد الثني السلبي","وضع الرضفة الوحشي"],"answer":1,"exp":"تُبسط الركبة سلبيًا بالكامل لكن لا تُبسط نشطًا: وهذا يدل على نقص تفعيل العضلة رباعية الرؤوس."},{"level":"متوسط","q":"على أي أساس يصح الانتقال إلى المرحلة التالية من إعادة التأهيل؟","options":["على معايير التورم ومدى الحركة والقوة أيضًا","على عدد الأسابيع منذ الجراحة فقط","حسب الخطة رغم ازدياد الألم","حسب رغبة المريض أساسًا"],"answer":0,"exp":"الوقت للاسترشاد فقط. ننتقل عندما تتحقق معايير التورم ومدى الحركة والقوة العضلية وجودة الحركة."},{"level":"سريري","q":"بعد أسبوع من إعادة البناء يظهر فجأة ألم في الربلة وتورم وسخونة. ما التصرف الصحيح؟","options":["تفريق التورم بالتدليك","زيادة الحمل","إبلاغ الطبيب فورًا","علاج حراري"],"answer":2,"exp":"علامة تشير إلى خثار وريدي عميق. يجب تجنّب التدليك وإبلاغ الطبيب فورًا."},{"level":"سريري","q":"بعد 4 أشهر من الجراحة الفرق في القوة بين الجانبين كبير، والركبة تنهار للداخل عند الهبوط. ما التصرف الصحيح الآن؟","options":["العودة فورًا إلى المباريات","متابعة التقوية وتحسين الهبوط","إنهاء إعادة التأهيل","العودة بالجبيرة فقط"],"answer":1,"exp":"فرق القوة وانهيار الركبة للداخل من عوامل خطر الإصابة مجددًا. تابع التقوية وتحسين الحركة؛ ولا تُطرح العودة إلا بعد تحقق المعايير."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الرياضة والأوتار والعضلات","icono":"🏃","mapa":"img/mapas/t30.jpg","fichas":[],"secuencias":[]},"31":{"id":31,"title":"الفُصال العظمي","lead":"الفُصال العظمي مرض يترافق مع تنكس الغضروف المفصلي، ويتقدم فيه الألم وتراجع الوظيفة تدريجيًا. يصيب أساسًا الركبة والورك؛ وأساس العلاج التحفظي العلاج بالحركة وتثقيف المريض.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"جوهره تنكس الغضروف المفصلي وتآكله، مع تكوّن النوابت العظمية وتصلب ما تحت الغضروف والتهاب الغشاء الزليلي. فُصال الركبة إنسي غالبًا، وفُصال الورك كثيرًا ما ينشأ على خلفية خلل التنسج."},{"h":"الأعراض الرئيسية","t":"ألم البدء، ألم عند النهوض وصعود الدرج، تيبس، انصباب مفصلي، تقييد الحركة. مع التقدم يبرز التشوه (مثل تقوس الساقين) واضطراب المشي."},{"h":"نقاط التقييم","t":"موضع الألم ومثيره، مدى الحركة (مثل تقييد بسط الركبة والدوران الداخلي للورك)، القوة العضلية، المشي (الدفع الوحشي، علامة ترندلنبرغ)، ADL."},{"h":"مسار العلاج","t":"تثقيف المريض، العلاج بالحركة (تقوية رباعية الرؤوس ومبعدات الورك، الحفاظ على مدى الحركة)، نشاط هوائي، ضبط الوزن، عصا، نعل طبي. إذا لم يكفِ العلاج التحفظي تُطرح الجراحة."},{"h":"الحذر وموانع الاستعمال","t":"أثناء الالتهاب الشديد أو الانصباب قلّل الحمل. الحمل الذي يسبب ألمًا حتى اليوم التالي زائد. تُمسك العصا عادة باليد المقابلة للجانب المصاب."},{"h":"علامات الإحالة للطبيب","t":"تورم وسخونة شديدان مفاجئان (اشتباه عدوى أو نقرس كاذب)، حمى، ألم ليلي متزايد، عجز مفاجئ عن المشي، ألم شديد بعد السقوط."}]},"keypoints":["فُصال الركبة إنسي غالبًا، وكثيرًا ما يترافق مع تقوس الساقين","كثيرًا ما يكمن خلل تنسج الحُق وراء فُصال الورك","أساس العلاج التحفظي العلاج بالحركة وتثقيف المريض","تُمسك العصا باليد المقابلة للجانب المصاب","راجع الحمل الذي يبقى بعده الألم حتى اليوم التالي"],"case":{"text":"امرأة عمرها 70 عامًا. تؤلمها ركبتها اليمنى منذ سنوات، خاصة عند النهوض وفي بداية الحركة وعلى الدرج. يُلاحظ تقوس الساقين وتقييد البسط وميل الركبة للخارج أثناء المشي (الدفع الوحشي).","answer":"نفكر في فُصال الركبة الإنسي. تثقيف المريضة، تقوية العضلة رباعية الرؤوس وعضلات الورك، الحفاظ على مدى الحركة، ضبط الوزن؛ وعند الحاجة عصا في اليد اليسرى. عند السخونة أو التورم المفاجئ أحِلها للطبيب."},"questions":[{"level":"أساسي","q":"ما النوع الأكثر شيوعًا لفُصال الركبة؟","options":["وحشي (ركبتان متلاصقتان)","إنسي (تقوس الساقين)","رضفي فخذي فقط","ظنبوبي شظوي"],"answer":1,"exp":"يصيب فُصال الركبة غالبًا الحجيرة الإنسية للمفصل، ويترافق كثيرًا مع تشوه تقوس الساقين (أفحج)."},{"level":"أساسي","q":"ما النتيجة التصويرية النموذجية للفُصال العظمي؟","options":["اتساع الشق المفصلي","اتساع غضروف النمو","تفاعل سمحاقي","تكوّن النوابت العظمية"],"answer":3,"exp":"العلامات النموذجية للفُصال العظمي هي تضيق الشق المفصلي والنوابت العظمية وتصلب ما تحت الغضروف."},{"level":"متوسط","q":"تعلّم مريضًا مصابًا بفُصال الركبة اليمنى استخدام العصا. بأي يد يمسكها؟","options":["باليد اليمنى","باليد اليسرى","باليدين معًا","لا فرق"],"answer":1,"exp":"تُمسك العصا عادة باليد المقابلة للجانب المصاب، وتتقدم مع الساق المصابة؛ فيقل الحمل على الجانب المصاب."},{"level":"متوسط","q":"في فُصال الورك مع ضعف العضلة الألوية الوسطى، أي علامة مميزة؟","options":["علامة سقوط الذراع","علامة لاسيغ","علامة ترندلنبرغ","علامة هومانز"],"answer":2,"exp":"عند ضعف العضلة الألوية الوسطى، في الوقوف على ساق الجانب المصاب يهبط الحوض في الجانب المقابل: هذه علامة ترندلنبرغ."},{"level":"سريري","q":"رجل عمره 65 عامًا، فُصال الركبة. بعد العلاج بالحركة بقي ألم وتورم شديدان حتى اليوم التالي. ما التصرف الصحيح؟","options":["زيادة الحمل أكثر","إيقاف كل حركة","تقليل الحمل وإعادة جرعته","التوصية بالراحة فقط"],"answer":2,"exp":"يشير الألم والتورم المستمران حتى اليوم التالي إلى حمل زائد. لا تتوقف، بل تابع مع تعديل الكمية والشدة."},{"level":"سريري","q":"مريض بفُصال الركبة تورمت ركبته فجأة بشدة، وهي ساخنة، ولديه حمى. ما التصرف الأول؟","options":["إبلاغ الطبيب","زيادة العلاج بالحركة","علاج حراري","تعليم الإطالة"],"answer":0,"exp":"قد يشير التورم المفاجئ والسخونة والحمى إلى عدوى أو نقرس كاذب. تجنّب العلاج الحراري والحركة، وأبلغ الطبيب."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"جراحة العظام والإصابات","icono":"🦴","mapa":"img/mapas/t31.jpg","fichas":[],"secuencias":[]},"32":{"id":32,"title":"استبدال مفصلي الورك والركبة","lead":"يستبدل المفصل الاصطناعي الأسطح المفصلية المتضررة بمادة صناعية لتقليل الألم وتحسين الوظيفة. مفتاح التعافي تعليم الحركة الملائم للمدخل الجراحي والتحريك المبكر.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية والجراحة","t":"استبدال الأسطح المفصلية المتضررة بسبب الفُصال العظمي أو غيره بمفصل اصطناعي لتقليل الألم وتحسين الوظيفة. في استبدال الورك (THA) يعتمد الوضع المعرّض للخلع على نوع المدخل الجراحي."},{"h":"مهام ما بعد الجراحة","t":"ألم، تورم، تقييد الحركة، ضعف عضلي، تراجع المشي. بعد THA المهمة الرئيسية الوقاية من الخلع، وبعد استبدال الركبة (TKA) الوصول إلى مدى الثني والبسط."},{"h":"نقاط التقييم","t":"الجرح والتورم، مدى الحركة، القوة العضلية (رباعية الرؤوس، الألوية الوسطى)، الإحساس بفرق طول الساقين، نمط المشي، التوازن، ADL. نسّق مع الطبيب حدود التحميل والأوضاع الممنوعة."},{"h":"مسار العلاج","t":"مبكرًا تمارين الكاحل والتمارين المتساوية القياس والتحريك وتدريب المشي. تمارين مدى الحركة والتقوية، تغيير أداة المشي تدريجيًا، تعليم ADL والحياة في المنزل."},{"h":"الحذر وموانع الاستعمال","t":"بعد THA بمدخل خلفي يُتجنّب الجمع بين الثني والتقريب والدوران الداخلي، وبعد المدخل الأمامي بين البسط والتقريب والدوران الخارجي. بعد TKA انتبه لعلامات شلل العصب الشظوي."},{"h":"علامات الإحالة للطبيب","t":"ألم مفاجئ يشير إلى الخلع، قِصر الساق ودورانها، تورم الربلة وألمها، ضيق نفس مفاجئ أو ألم صدري، احمرار الجرح أو تقيّحه، حمى."}]},"keypoints":["يعتمد الوضع المعرّض للخلع في THA على نوع المدخل الجراحي","في المدخل الخلفي تجنّب الجمع بين الثني والتقريب والدوران الداخلي","يساعد العطف الظهري والأخمصي للكاحل في الوقاية من الخثار","بعد TKA من المهم الوصول المبكر إلى مدى الثني والبسط","نسّق دائمًا مع الطبيب التحميل والأوضاع الممنوعة"],"case":{"text":"امرأة عمرها 75 عامًا، أُجري لها THA بمدخل خلفي بسبب فُصال الورك، اليوم الثالث بعد الجراحة. تتدرب بالمشاية، وتريد التقاط شيء من الأرض: ستنحني بعمق مع تدوير جذعها.","answer":"الجمع بين الثني العميق والتقريب والدوران الداخلي معرّض للخلع بعد THA بمدخل خلفي، فأوقفها فورًا. علّمها الحركات الآمنة بأداة مساعدة (مثل ملقط التقاط الأشياء). عند ألم مفاجئ أو قِصر الساق أو دورانها أحِلها للطبيب."},"questions":[{"level":"أساسي","q":"بعد THA بمدخل خلفي، أي وضع معرّض للخلع؟","options":["بسط، تقريب، دوران خارجي","ثني، تقريب، دوران داخلي","ثني، تبعيد، دوران خارجي","بسط، تبعيد، دوران داخلي"],"answer":1,"exp":"بعد THA بمدخل خلفي يزداد خطر الخلع عند الجمع بين ثني الورك وتقريبه ودورانه الداخلي."},{"level":"أساسي","q":"ما الهدف الرئيسي لاستبدال مفصل الركبة (TKA)؟","options":["تحفيز نمو العظم","استبدال الرباط","إصلاح العصب","تقليل الألم وتحسين الوظيفة"],"answer":3,"exp":"يستبدل TKA الأسطح المفصلية المتضررة بمفصل اصطناعي؛ وهدفه تقليل الألم وتحسين المشي والوظائف الأخرى."},{"level":"متوسط","q":"أي تمرين تعلّمه مبكرًا للوقاية من الخثار الوريدي العميق؟","options":["تدوير الرقبة","ثني الأصابع وبسطها","العطف الظهري والأخمصي للكاحل","القرفصاء العميقة"],"answer":2,"exp":"يساعد العطف الظهري والأخمصي للكاحل عبر مضخة عضلة الربلة على العودة الوريدية والوقاية من الخثار."},{"level":"متوسط","q":"أي شلل عصبي يجب الانتباه إليه بعد TKA؟","options":["شلل العصب الشظوي","شلل العصب المتوسط","شلل العصب الوجهي","شلل العصب الكعبري"],"answer":0,"exp":"بعد TKA قد يحدث شلل العصب الشظوي بسبب الضغط حول رأس الشظية؛ انتبه لتدلي القدم والتنميل."},{"level":"سريري","q":"اليوم الخامس بعد THA بمدخل خلفي: يجلس المريض على كرسي منخفض ويريد وضع ساق فوق الأخرى. ما التصرف الصحيح؟","options":["المراقبة فقط","كرسي أعلى وتجنّب تصالب الساقين","التدرب على تصالب الساقين","التدرب على الانحناء العميق"],"answer":1,"exp":"على الكرسي المنخفض يكون الثني العميق وتصالب الساقين (تقريب، دوران داخلي) معرّضين للخلع. ليستخدم مقعدًا مرتفعًا ولا يضع ساقًا فوق الأخرى."},{"level":"سريري","q":"اليوم الثاني بعد TKA: أثناء تدريب المشي يظهر فجأة ضيق نفس وألم صدري. ما التصرف الأول؟","options":["متابعة تدريب المشي","تعليم تمارين التنفس","إيقاف فوري وإبلاغ الطبيب","الراحة والمراقبة"],"answer":2,"exp":"علامة تشير إلى انصمام رئوي. يجب إيقاف الحركة فورًا وإبلاغ الطبيب."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"جراحة العظام والإصابات","icono":"🦴","mapa":"img/mapas/t32.jpg","fichas":[],"secuencias":[]},"33":{"id":33,"title":"الكسور الشائعة","lead":"عند كبار السن تشيع الكسور الناتجة عن السقوط على خلفية هشاشة العظام. باتباع مرحلة التئام العظم والإطار الذي يسمح به الطبيب، امنع الخمول واستعد الوظيفة.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"عند كبار السن، على خلفية هشاشة العظام وبعد السقوط، تشيع كسور الفخذ القريب والكعبرة البعيدة والعضد القريب وجسم الفقرة. أما عند الشباب فيغلب الرضح عالي الطاقة."},{"h":"الأعراض الرئيسية","t":"ألم، تورم، تشوه، كدمة، فقدان الوظيفة. في كسر الفخذ القريب لا يستطيع المريض الوقوف، والساق قصيرة ومدوّرة للخارج؛ وفي الكسر الانضغاطي ألم ظهر مع الحركة."},{"h":"نقاط التقييم","t":"نسّق مع الطبيب نوع الكسر والتثبيت وإطار التحميل ومدى الحركة. الألم، التورم، مدى حركة المفاصل المجاورة، القوة، الحالة العصبية والدورانية، ADL قبل الإصابة والإدراك."},{"h":"مسار العلاج","t":"أثناء التثبيت حرّك المفاصل الحرة ضد التورم والتقفع. حسب التئام العظم والإذن: تمارين مدى الحركة والتحميل والتقوية. عند كبار السن تحريك مبكر ووقاية من السقوط."},{"h":"الحذر وموانع الاستعمال","t":"لا تتجاوز التحميل ومدى الحركة المسموح بهما. في الراحة الطويلة بالسرير انتبه للخمول وذات الرئة وقرحة الفراش والهذيان. بعد كسر الكعبرة البعيدة انتبه لتيبس الأصابع."},{"h":"علامات الإحالة للطبيب","t":"ألم شديد أثناء التثبيت، تنميل، تغير لون الأصابع (اشتباه اضطراب دوراني أو متلازمة الحيز)، ألم أو تشوه يزداد فجأة، تورم الربلة، حمى."}]},"keypoints":["عند كبار السن يشيع الكسر بعد السقوط على خلفية هشاشة العظام","نسّق دائمًا مع الطبيب الإطار المسموح للتحميل ومدى الحركة","حرّك المفاصل غير المثبتة بنشاط حتى أثناء التثبيت","بعد كسر الفخذ القريب امنع الخمول بالتحريك المبكر","ضد كسر جديد: الوقاية من السقوط وعلاج هشاشة العظام"],"case":{"text":"امرأة عمرها 82 عامًا سقطت في المنزل، يؤلمها وركها الأيمن ولا تستطيع الوقوف. الطرف السفلي الأيمن قصير ومدوّر للخارج. أُجري لها تثبيت داخلي لكسر الفخذ بين المدورين، وطُلب التأهيل في اليوم التالي للجراحة.","answer":"نسّق مع الطبيب التحميل المسموح، وابدأ التحريك المبكر وتدريب المشي، وامنع الخمول وذات الرئة والهذيان. الهدف ADL ما قبل الإصابة؛ وقبل الخروج من المستشفى علّمها الوقاية من السقوط وعلاج هشاشة العظام."},"questions":[{"level":"أساسي","q":"أي كسر شائع عندما يسقط مسن على يد ممدودة؟","options":["كسر العظم الزورقي","كسر الكعبرة البعيدة","كسر الزج","كسر عظم المشط"],"answer":1,"exp":"عند كبار السن، بعد السقوط على يد ممدودة، يكون كسر الكعبرة البعيدة هو المميز. إذا انزاحت القطعة البعيدة ظهريًا نسميه كسر كوليس."},{"level":"أساسي","q":"ما وضع الطرف السفلي في كسر الفخذ القريب؟","options":["أطول ومدوّر للداخل","لا يوجد اختلاف","قصير ومدوّر للخارج","أطول ومُبعَد"],"answer":2,"exp":"في كسر الفخذ القريب تكون الساق نموذجيًا قصيرة ومدوّرة للخارج، والوقوف والمشي صعبان."},{"level":"متوسط","q":"ما العلاج الطبيعي الصحيح في مرحلة تثبيت الكسر؟","options":["مدى حركة سلبي قوي على الجزء المثبت","تحميل كامل قبل الإذن","تدليك قوي على موضع الكسر","تحريك المفاصل غير المثبتة"],"answer":3,"exp":"أثناء التثبيت نحمي الكسر، ونمنع التورم والتقفع وضعف العضلات بتحريك المفاصل غير المثبتة."},{"level":"متوسط","q":"ما الهدف الرئيسي للتحريك المبكر بعد جراحة كسر الفخذ القريب عند كبار السن؟","options":["تحديد نوع الكسر","الوقاية من متلازمة الخمول","الاستغناء عن الجراحة","الاستغناء عن التئام العظم"],"answer":1,"exp":"عند كبار السن، مع الاستلقاء الطويل، تتطور بسرعة ضعف العضلات وذات الرئة وقرحة الفراش والهذيان، لذا نحرّك المريض مبكرًا."},{"level":"سريري","q":"امرأة عمرها 70 عامًا في جبس بسبب كسر الكعبرة البعيدة. أصابعها متورمة بشدة ومتنملة ومتغيرة اللون. ما التصرف الصحيح؟","options":["زيادة تمارين الأصابع","علاج حراري","إبلاغ الطبيب فورًا","انتظار الجلسة القادمة"],"answer":2,"exp":"يشير التورم الشديد والتنميل وتغير اللون أثناء التثبيت إلى اضطراب دوراني أو متلازمة الحيز. أبلغ الطبيب فورًا."},{"level":"سريري","q":"امرأة عمرها 85 عامًا، كسر انضغاطي في فقرة قطنية، ألم ظهر؛ وسمح الطبيب بالتحريك. ما التصرف الصحيح؟","options":["التحريك ضمن الإطار المسموح","البقاء في السرير والمراقبة","تمارين ثني قوي للجذع","التدرب على رفع أشياء ثقيلة"],"answer":0,"exp":"نحرّك المريضة ضمن الإطار المسموح ضد الخمول. في الكسر الانضغاطي يُجهد ثني الجذع القوي ورفع الأشياء الثقيلة، فيجب تجنبهما."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"جراحة العظام والإصابات","icono":"🦴","mapa":"img/mapas/t33.jpg","fichas":[],"secuencias":[]},"34":{"id":34,"title":"آلام أسفل الظهر والانزلاق الغضروفي","lead":"معظم آلام أسفل الظهر غير نوعية ولا يُعرف سببها، لكن من المهم تمييز الأعراض الجذرية والأمراض الخطيرة. بعد استبعاد العلامات الحمراء ندعم الحفاظ على النشاط.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"معظم آلام أسفل الظهر غير نوعية. في الانزلاق الغضروفي تخترق النواة اللبية الحلقة الليفية وتبرز وتضغط الجذر العصبي. الأكثر شيوعًا في القطعتين L4/5 وL5/S1."},{"h":"الأعراض الرئيسية","t":"ألم أسفل الظهر وألم أحادي الجانب ينتشر إلى الساق (عرق النسا)، تنميل، شكوى تزداد مع الانحناء للأمام والجلوس. نقص الإحساس والقوة والمنعكسات وفق الجذر المصاب."},{"h":"نقاط التقييم","t":"اختبار SLR (وللجذور القطنية العليا اختبار شد العصب الفخذي)، الجلَّادات، القوة العضلية (L5: عطف ظهري لإبهام القدم، S1: عطف أخمصي للكاحل)، المنعكسات (S1: منعكس وتر أكيلس)."},{"h":"مسار العلاج","t":"بتثقيف المريض قلّل الخوف، وحافظ على النشاط ضمن الإطار الممكن. ابحث عن وضعية وتمرين يقللان الأعراض؛ تمارين للجذع والطرف السفلي، ونشاط يزداد تدريجيًا."},{"h":"الحذر وموانع الاستعمال","t":"لا تنصح بالراحة الطويلة في السرير. أوقف التمرين الذي تمتد معه الأعراض نحو أصابع القدم. يؤدي تجنّب الخوف والعوامل النفسية الاجتماعية الأخرى دورًا في التحول إلى الإزمان."},{"h":"علامات الإحالة للطبيب","t":"اضطراب المثانة والمستقيم، فقدان إحساس السرج (متلازمة ذيل الفرس)، ضعف متفاقم، حمى، نقص وزن غير مفسر، ورم في التاريخ المرضي، ألم شديد بعد رضح."}]},"keypoints":["معظم آلام أسفل الظهر غير نوعية","في انزلاق L4/5 يُصاب نموذجيًا الجذر L5","يقيّم اختبار SLR الأعراض الجذرية القطنية السفلية","بدل الراحة الطويلة حافظ على النشاط ضمن الإطار الممكن","اضطراب المثانة والمستقيم وفقدان إحساس السرج: إحالة فورية للفحص الطبي"],"case":{"text":"رجل عمره 35 عامًا، يعمل في مكتب. منذ رفع شيء ثقيل يعاني ألم أسفل الظهر وتنميلًا يمتد من الجانب الوحشي للساق اليسرى إلى ظهر القدم. يثير SLR الأيسر ألمًا ينتشر إلى الساق، والعطف الظهري لإبهام القدم الأيسر ضعيف. لا يوجد اضطراب في التبول.","answer":"نشتبه بإصابة الجذر L5 بسبب انزلاق غضروفي L4/5. التثقيف، الحفاظ على النشاط ضمن الإطار الممكن، تمارين لا تزيد الأعراض؛ وأعد تقييم تطور الضعف العضلي بانتظام. عند شلل متفاقم أو اضطراب المثانة والمستقيم أحِله فورًا للطبيب."},"questions":[{"level":"أساسي","q":"في أي قطعة يكون الانزلاق الغضروفي القطني أكثر شيوعًا؟","options":["L1/2","L2/3","L3/4","L4/5"],"answer":3,"exp":"يحدث الانزلاق الغضروفي القطني غالبًا في القطعة L4/5، تليها L5/S1."},{"level":"أساسي","q":"في الانزلاق الغضروفي، أي نسيج يبرز أساسًا؟","options":["النواة اللبية","الرباط الأصفر","قوس الفقرة","الناتئ الشوكي"],"answer":0,"exp":"يبرز الجزء المركزي من القرص، النواة اللبية، عبر شق في الحلقة الليفية ويضغط الجذر العصبي."},{"level":"متوسط","q":"في إصابة الجذر L5، قوة أي حركة تقل نموذجيًا؟","options":["العطف الأخمصي للكاحل","العطف الظهري لإبهام القدم","بسط الركبة","ثني الورك"],"answer":1,"exp":"يعصّب الجذر L5 العضلة الباسطة الطويلة لإبهام القدم، وفي إصابته يضعف العطف الظهري للإبهام. أما العطف الأخمصي للكاحل فهو S1."},{"level":"متوسط","q":"في إصابة الجذر S1، أي منعكس يقل نموذجيًا؟","options":["المنعكس الرضفي","منعكس ذات الرأسين","منعكس وتر أكيلس","المنعكس العضدي الكعبري"],"answer":2,"exp":"يشارك S1 أساسًا في منعكس وتر أكيلس. أما المنعكس الرضفي فيُستخدم أساسًا لتقييم L4."},{"level":"سريري","q":"امرأة عمرها 40 عامًا، ألم حاد أسفل الظهر، دون علامات حمراء. ما النصيحة الصحيحة؟","options":["راحة صارمة في السرير لأسبوعين","إجازة مرضية حتى يزول الألم","منع كل حركة","الحفاظ على النشاط ضمن الإطار الممكن"],"answer":3,"exp":"في ألم أسفل الظهر الحاد دون علامات حمراء يُنصح بالحفاظ على النشاط اليومي ضمن الإطار الممكن بدل الراحة الطويلة."},{"level":"سريري","q":"مريض بألم أسفل الظهر، تتنمل ساقاه كلتاهما؛ يشكو من صعوبة بدء التبول وخدر حول فتحة الشرج. ما التصرف؟","options":["متابعة العلاج بالحركة","علاج بالشد","إبلاغ الطبيب فورًا","انتظار الجلسة القادمة"],"answer":2,"exp":"اضطراب المثانة والمستقيم وفقدان إحساس السرج علامة عاجلة لمتلازمة ذيل الفرس. أبلغ الطبيب فورًا."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"العمود الفقري","icono":"🧍","mapa":"img/mapas/t34.jpg","fichas":[],"secuencias":[]},"35":{"id":35,"title":"آلام الرقبة","lead":"معظم آلام الرقبة غير نوعية، لكن من المهم تمييز اعتلال الجذر واعتلال النخاع. بعد التحقق من علامات الخطر نطبّق العلاج بالحركة ونصحّح القوام.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"الأكثر شيوعًا ألم الرقبة غير النوعي. إذا ضغط القرص أو النابتة العظمية الجذر العصبي ينشأ اعتلال الجذر، وإذا ضغط الحبل الشوكي ينشأ اعتلال النخاع. بعد الرضح قد تحدث إصابة الرقبة السوطية (whiplash)."},{"h":"الأعراض الرئيسية","t":"ألم الرقبة، تقييد الحركة، ألم حول لوح الكتف. في اعتلال الجذر ألم وتنميل في ذراع واحدة. في اعتلال النخاع تنميل اليدين كلتيهما، تراجع الحركات الدقيقة (الأزرار، أدوات الطعام)، اضطراب المشي."},{"h":"نقاط التقييم","t":"مدى حركة الرقبة، اختبار سبورلينغ، الجلَّادات، القوة العضلية، المنعكسات (C6: العضدي الكعبري، C7: ثلاثية الرؤوس)، منعكس هوفمان، المشي، القوام."},{"h":"مسار العلاج","t":"التثقيف والحفاظ على النشاط، تمارين الرقبة وحزام الكتف (مثل تمارين العضلات العميقة الثانية للرقبة)، تعديل القوام وبيئة العمل. علاج يدوي بحذر بناءً على التقييم."},{"h":"الحذر وموانع الاستعمال","t":"عند الاشتباه باعتلال النخاع تجنّب التقنيات اليدوية القوية على الرقبة. أوقف فورًا أي تقنية أو تمرين يثير الدوار أو ازدواج الرؤية أو اضطراب الكلام."},{"h":"علامات الإحالة للطبيب","t":"تنميل اليدين كلتيهما، تراجع الحركات الدقيقة واضطراب المشي، شلل متفاقم، ألم بعد رضح، حمى، دوار، اضطراب الكلام أو البلع، نقص وزن غير مفسر."}]},"keypoints":["معظم آلام الرقبة غير نوعية","يُستخدم اختبار سبورلينغ لتقييم اعتلال الجذر","تراجع مهارة اليدين كلتيهما واضطراب المشي: اشتباه اعتلال النخاع","اطلب تمارين العضلات العميقة الثانية للرقبة وحزام الكتف","عند الاشتباه باعتلال النخاع تجنّب التقنيات اليدوية القوية على الرقبة"],"case":{"text":"امرأة عمرها 45 عامًا، موظفة مكتب. منذ شهر تعاني ألم الرقبة وتنميل الإبهام الأيمن. عند بسط الرقبة وإمالتها إلى اليمين يظهر ألم ينتشر إلى الذراع اليمنى. المنعكس العضدي الكعبري الأيمن ناقص.","answer":"نفكر في اعتلال الجذر C6 الأيمن. ضمن إطار لا يزيد الأعراض: تثقيف، علاج بالحركة، تعديل القوام وبيئة العمل. عند ضعف متفاقم أو علامات اعتلال النخاع (تنميل اليدين كلتيهما، اضطراب المشي) أحِلها للطبيب."},"questions":[{"level":"أساسي","q":"أي عرض يشير إلى اعتلال النخاع الفقاري العنقي؟","options":["ألم حول لوح الكتف في جانب واحد فقط","تراجع مهارة اليدين كلتيهما","تيبس عضلات الرقبة","صداع فقط"],"answer":1,"exp":"في انضغاط الحبل الشوكي تتنمل اليدان كلتاهما، وتتراجع الحركات الدقيقة (أدوات الطعام، الأزرار)، ويظهر اضطراب المشي."},{"level":"أساسي","q":"ما التمرين النموذجي للعضلات العميقة الثانية للرقبة؟","options":["بسط قوي للرقبة","تدوير سريع للرقبة","سحب الذقن (ثني قحفي عنقي)","رفع الكتفين"],"answer":2,"exp":"الثني القحفي العنقي بسحب الذقن قليلًا تمرين نموذجي يزيد نشاط العضلات العميقة الثانية للرقبة (مثل العضلة الطويلة للعنق)."},{"level":"متوسط","q":"ما نتيجة اختبار سبورلينغ الإيجابي؟","options":["بسط + ميل جانبي: ألم ينتشر للذراع","ثني الرقبة: ألم واخز في الظهر","أعراض تخف مع تبعيد الكتف","تنميل مع ثني الرسغ"],"answer":0,"exp":"نبسط الرقبة ونميلها نحو الجانب المصاب ثم نطبّق ضغطًا محوريًا؛ ويشير الألم أو التنميل المنتشر إلى الذراع إلى اعتلال الجذر."},{"level":"متوسط","q":"في إصابة الجذر C7، أي منعكس يقل نموذجيًا؟","options":["منعكس ذات الرأسين","المنعكس العضدي الكعبري","منعكس ثلاثية الرؤوس","المنعكس الرضفي"],"answer":2,"exp":"يُستخدم منعكس ثلاثية الرؤوس أساسًا لتقييم C7، ومنعكس ذات الرأسين لـ C5، والمنعكس العضدي الكعبري لـ C6."},{"level":"سريري","q":"رجل عمره 60 عامًا: مؤخرًا يجد صعوبة في ربط الأزرار، ومشيته غير ثابتة، ومنعكس هوفمان إيجابي. بماذا تشتبه أكثر؟","options":["ألم رقبة غير نوعي","متلازمة مخرج الصدر","متلازمة النفق الرسغي","اعتلال النخاع الفقاري العنقي"],"answer":3,"exp":"يشير تراجع الحركات الدقيقة واضطراب المشي والمنعكس المرضي إلى اعتلال النخاع. تجنّب التقنيات القوية على الرقبة، وأحِله للفحص الطبي."},{"level":"سريري","q":"مريض بألم الرقبة، أثناء تمرين تدوير الرقبة يظهر دوار وازدواج رؤية. ما التصرف الصحيح؟","options":["المتابعة حتى يعتاد","إيقاف فوري وإحالة للطبيب","زيادة مدى الحركة أكثر","التحول إلى العلاج الحراري"],"answer":1,"exp":"قد يشير الدوار وازدواج الرؤية إلى مشكلة وعائية أو عصبية. أوقف فورًا، وأحِله للفحص الطبي."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"العمود الفقري","icono":"🧍","mapa":"img/mapas/t35.jpg","fichas":[],"secuencias":[]},"36":{"id":36,"title":"الجنف","lead":"الجنف انحناء جانبي للعمود الفقري مع دوران الفقرات: تشوه ثلاثي الأبعاد. يميل إلى التفاقم أثناء النمو، لذا من المهم الاكتشاف المبكر والمتابعة المنتظمة.","sheet":{"kind":"condition","items":[{"h":"الحالة المرضية","t":"ينحني العمود الفقري جانبيًا في المستوى الجبهي: تشوه ثلاثي الأبعاد مع دوران الفقرات. غالبًا مجهول السبب (idiopathic)، وأكثر شيوعًا لدى الفتيات المراهقات. يجب تمييزه عن الجنف الوظيفي."},{"h":"الأعراض الرئيسية","t":"غالبًا قليل الألم؛ يلفت الانتباه إليه عدم تناظر الكتف أو لوح الكتف أو خط الخصر، أو حدبة الأضلاع أو الحدبة القطنية عند الانحناء للأمام. في الحالات الشديدة يضعف وظيفة التنفس أيضًا."},{"h":"نقاط التقييم","t":"في الوقوف تناظر الكتفين والحوض وخط الخصر، اختبار الانحناء للأمام، فرق طول الساقين (للتمييز عن الوظيفي)، المرونة، التنفس. يقيس الطبيب الانحناء بالأشعة بزاوية كوب."},{"h":"مسار العلاج","t":"يقرر الطبيب المتابعة أو الدعامة أو الجراحة بناءً على مرحلة النمو وزاوية كوب. يطلب أخصائي العلاج الطبيعي تمارين للجذع والتنفس، ويدعم ارتداء الدعامة."},{"h":"الحذر وموانع الاستعمال","t":"يميل إلى التفاقم أثناء النمو، لذا المتابعة المنتظمة مهمة. لا تقل إنه يُصحَّح بالتمارين وحدها. يحدد الطبيب مدة ارتداء الدعامة."},{"h":"علامات الإحالة للطبيب","t":"ألم شديد أو ليلي، أعراض عصبية (تنميل، ضعف)، تفاقم سريع، انحناء غير نموذجي (مثل انحناء صدري محدب نحو اليسار)، حمى."}]},"keypoints":["الجنف تشوه ثلاثي الأبعاد مع دوران الفقرات","الأكثر تميزًا هو الجنف مجهول السبب الشائع لدى الفتيات المراهقات","تحقق من حدبة الأضلاع باختبار الانحناء للأمام","يميل إلى التفاقم أثناء النمو، والمتابعة المنتظمة مهمة","في الجنف المصحوب بألم أو أعراض عصبية أحِل للطبيب"],"case":{"text":"فتاة عمرها 13 عامًا، شُخّص لديها جنف في الفحص المدرسي. في الوقوف كتفها الأيمن أعلى، وعند الانحناء للأمام تظهر حدبة أضلاع يمنى. لا يوجد ألم ولا أعراض عصبية. وصف طبيب العظام دعامة.","answer":"نفكر في الجنف مجهول السبب لدى المراهقين. يدعم أخصائي العلاج الطبيعي الارتداء المستمر للدعامة، ويطلب تمارين للجذع والتنفس. لا تقل إنه يُصحَّح بالتمارين وحدها. عند ألم أو عرض عصبي أو تفاقم سريع أحِلها للطبيب."},"questions":[{"level":"أساسي","q":"في فحص الجنف، ماذا تلاحظ في اختبار الانحناء للأمام؟","options":["فرط بسط الركبة","حدبة الأضلاع","هبوط قوس القدم","زيادة القعس العنقي"],"answer":1,"exp":"عند الانحناء للأمام ننظر إلى الظهر من الخلف، ونبحث عن حدبة الأضلاع أو الحدبة القطنية الناتجة عن دوران الفقرات."},{"level":"أساسي","q":"أي مؤشر يدل على مقدار انحناء الجنف؟","options":["زاوية Q","زاوية العنق والجسم","زاوية كوب","الزاوية الفخذية الظنبوبية"],"answer":2,"exp":"يُقاس مقدار الانحناء بالأشعة بزاوية كوب، بناءً على الفقرتين الطرفيتين العليا والسفلى للانحناء."},{"level":"متوسط","q":"ما الصحيح بشأن الجنف مجهول السبب؟","options":["شائع لدى الرجال المسنين","شائع لدى الفتيات المراهقات","يترافق دائمًا مع ألم شديد","تشوه في المستوى الجبهي فقط"],"answer":1,"exp":"الجنف مجهول السبب أكثر شيوعًا لدى الفتيات المراهقات، وغالبًا قليل الألم، وهو تشوه ثلاثي الأبعاد مع دوران الفقرات."},{"level":"متوسط","q":"ما الذي قد يسبب الجنف الوظيفي؟","options":["تشوه خلقي في الفقرات","مرض عصبي عضلي","تشوه دوراني في الفقرات","فرق طول الساقين"],"answer":3,"exp":"يتحسن الجنف الوظيفي الناتج عن فرق طول الساقين أو وضعية تجنّب الألم بإزالة السبب؛ ويجب تمييزه عن البنيوي."},{"level":"سريري","q":"فتاة عمرها 14 عامًا بدعامة؛ لأنها تضغط عليها تقلل مدة ارتدائها بقرار ذاتي. ما دور أخصائي العلاج الطبيعي؟","options":["ترك الدعامة والتمارين فقط","دعم الارتداء والتنسيق مع الطبيب","تقليل مدة الارتداء أكثر","طمأنتها بأنه لا مشكلة"],"answer":1,"exp":"في مدة الارتداء تعليمات الطبيب هي المرجع. استمع إلى مشكلاتها، وادعم الارتداء، ونسّق بشأن الملاءمة مع الطبيب أو فني الأجهزة التقويمية."},{"level":"سريري","q":"صبي عمره 12 عامًا مصاب بالجنف، يستيقظ ليلًا من ألم ظهر شديد. ما التصرف الصحيح؟","options":["تعليم الإطالة","المراقبة","زيادة الحمل","الإحالة للفحص الطبي"],"answer":3,"exp":"قد يكمن وراء الجنف المصحوب بألم شديد أو ليلي سبب آخر، مثل الورم، لذا يجب الإحالة للفحص الطبي."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"العمود الفقري","icono":"🧍","mapa":"img/mapas/t36.jpg","fichas":[],"secuencias":[]},"37":{"id":37,"title":"السكتة الدماغية","lead":"أعراض عصبية مفاجئة ناتجة عن انسداد أحد الأوعية الدماغية أو تمزقه. التحريك المبكر والتدريب المتكرر الموجه نحو المهام هما أساس التحسن الوظيفي.","sheet":{"kind":"condition","items":[{"h":"الصورة المرضية","t":"سكتة إقفارية (تخثرية تصلبية، أو صمية قلبية، أو جوبية)، ونزف دماغي، ونزف تحت العنكبوتية. تعتمد الأعراض على موقع الآفة وحجمها."},{"h":"الأعراض الرئيسية","t":"خزل نصفي، واضطراب الحس، وتشنج عضلي، وحبسة، وإهمال نصفي، وعسر التلفظ، وعسر البلع، إضافة إلى اضطراب الانتباه وغيره من اضطرابات الوظائف القشرية العليا."},{"h":"محاور التقييم","t":"الخزل: مراحل برونستروم، وSIAS، وFMA؛ التشنج العضلي: MAS؛ التوازن: BBS؛ ADL: FIM."},{"h":"التأهيل حسب المرحلة","t":"المرحلة الحادة: تحريك مبكر مع إدارة المخاطر. المرحلة تحت الحادة: تدريب موجه نحو المهام وتعليم المشي. المرحلة المزمنة: الحفاظ على النشاط والمشاركة."},{"h":"الاحتياطات والموانع","t":"في المرحلة الحادة راقب تقلبات ضغط الدم ومستوى الوعي والأعراض العصبية. سحب الذراع المصابة أو المساعدة الخاطئة يسببان ألم الكتف."},{"h":"دواعي الإحالة الطبية","t":"أبلغ فورًا عند انخفاض مستوى الوعي، أو تفاقم مفاجئ للخزل أو لعسر التلفظ، أو صداع شديد، أو قيء، أو تغير مفاجئ في ضغط الدم."}]},"keypoints":["ابدأ التحريك وأوقفه وفق تعليمات الطبيب ومعايير الإيقاف","لا تسحب الكتف المصاب، واحمِه بالوضعيات الصحيحة","في الإهمال النصفي: مهام توجه الانتباه نحو الجانب المهمل وتعديل البيئة","أساس التحسن الوظيفي هو التدريب المتكرر الموجه نحو المهام","قيّم استخدام الجبيرة تدريجيًا حسب القدرة على المشي والأهداف"],"case":{"text":"رجل عمره 68 عامًا، بعد 3 أسابيع من سكتة إقفارية في منطقة الشريان المخي الأوسط الأيمن. خزل نصفي أيسر (الطرف السفلي: المرحلة III حسب برونستروم). يصطدم بكرسيه المتحرك كثيرًا بالأشياء على يساره، ويترك الطعام في النصف الأيسر من الطبق.","answer":"يُشتبه في إهمال نصفي أيسر، مع خطر مرتفع للسقوط والاصطدام. مهام تنمّي الانتباه نحو الجانب الأيسر، وتعديل البيئة، وتدريب تحت الإشراف. لا تسمح بالتنقل المستقل ما دام الإهمال قائمًا."},"questions":[{"level":"أساسي","q":"ما توزيع الخزل النصفي المميز للسكتة الإقفارية في منطقة الشريان المخي الأوسط؟","options":["غلبة الطرف السفلي","غلبة الطرف العلوي والوجه","خزل سفلي في الطرفين السفليين","خزل رباعي متماثل"],"answer":1,"exp":"يغذي الشريان المخي الأوسط السطح الوحشي لنصف الكرة، بما فيه القشرة الحركية للطرف العلوي والوجه، لذا تغلب إصابتهما. غلبة الطرف السفلي: الشريان المخي الأمامي."},{"level":"أساسي","q":"أي آفة تسبب الإهمال النصفي الأيسر في أغلب الأحيان؟","options":["الفص الجبهي الأيسر","المخيخ","الفص الجداري الأيمن","جذع الدماغ"],"answer":2,"exp":"ينشأ الإهمال الأيسر عادة عند إصابة نصف الكرة الأيمن، ولا سيما الفص الجداري الأيمن."},{"level":"متوسط","q":"في أي مرحلة من مراحل برونستروم تظهر التآزرات الحركية إراديًا وبشكل كامل؟","options":["المرحلة II","المرحلة IV","المرحلة VI","المرحلة III"],"answer":3,"exp":"III: تظهر التآزرات إراديًا وبشكل كامل. II: ردود فعل مصاحبة وبداية التآزرات. IV: الحركة المنفصلة ممكنة جزئيًا."},{"level":"متوسط","q":"بأي مقياس تقيس التشنج العضلي بعد السكتة الدماغية؟","options":["MAS","FIM","BBS","MMSE"],"answer":0,"exp":"يدرّج MAS التوتر العضلي حسب المقاومة للتحريك السلبي. يقيس FIM أنشطة ADL، وBBS التوازن، وMMSE الوظيفة المعرفية."},{"level":"سريري","q":"بعد سكتة دماغية يوجد خلع جزئي في الكتف المصاب، ويشكو المريض من ألم الكتف أثناء النقل. ماذا تفعل؟","options":["تساعده بالإمساك بذراعه المصابة","تدعم الكتف ولا تسحب الذراع","تثبته كليًا حتى يزول الألم","تجري إطالة سلبية قوية يوميًا"],"answer":1,"exp":"سحب الكتف المخلوع جزئيًا يسبب الألم والإصابة. احمِه بوسيلة دعم وبالوضعيات، وحافظ على مدى الحركة ضمن حدود خالية من الألم."},{"level":"سريري","q":"سكتة إقفارية حادة: أثناء التحريك يتفاقم عسر التلفظ والخزل فجأة. ماذا تفعل؟","options":["تواصل تدريب المشي","تواصل التدريب بعد راحة","تتوقف وتبلغ الطبيب فورًا","تعيد التقييم في اليوم التالي"],"answer":2,"exp":"التفاقم المفاجئ للأعراض العصبية قد يدل على امتداد الآفة أو تكرارها. أوقف التدريب، وأمّن المريض، وأبلغ الطبيب فورًا."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الأمراض العصبية","icono":"🧠","mapa":"img/mapas/t37.jpg","fichas":[],"secuencias":[]},"38":{"id":38,"title":"مرض باركنسون","lead":"مرض تنكسي عصبي مترقٍّ يسبب أعراضًا حركية نتيجة تنكس العصبونات الدوبامينية في المادة السوداء بالدماغ الأوسط. الأساس هو الحركة المعتمدة على المثيرات الخارجية (cue) والوقاية من السقوط.","sheet":{"kind":"condition","items":[{"h":"الصورة المرضية","t":"تتنكس العصبونات الدوبامينية في المادة السوداء، فينشأ نقص الدوبامين في الجسم المخطط ويختل التحكم الحركي. تترقى الأعراض ببطء."},{"h":"الأعراض الرئيسية","t":"رعاش ساكن، وصمل، وانعدام الحركة/بطء الحركة، وعدم ثبات وضعي. إضافة إلى التجمد (freezing)، والمشي بخطوات قصيرة، والانحناء للأمام، وأعراض غير حركية (مثل الإمساك)."},{"h":"محاور التقييم","t":"مرحلة Hoehn–Yahr، وMDS-UPDRS، وBBS، وTUG، وسرعة المشي، ووجود التجمد، وتاريخ السقوط، وتقلب مفعول الدواء خلال اليوم."},{"h":"مسار العلاج","t":"في المراحل المبكرة: الحفاظ على الحركة العامة والتحمل؛ ومع الترقي: تدريب المشي بمساعدة مثيرات بصرية/سمعية، وتمارين التوازن، والوقاية من السقوط، وتعديل البيئة."},{"h":"الاحتياطات والموانع","t":"وقّت التدريب حسب تقلب مفعول الدواء (wearing-off، خلل الحركة). وانتبه أيضًا لهبوط الضغط الانتصابي."},{"h":"دواعي الإحالة الطبية","t":"أبلغ عن التفاقم المفاجئ للأعراض، وقِصر مدة مفعول الدواء، والهلوسة، والسقوط المتكرر، وتفاقم عسر البلع، أو الحمى المرتفعة مع صمل شديد."}]},"keypoints":["وقّت التدريب في فترة «on» حين يكون الدواء فعالًا","المثيرات الخارجية (خطوط على الأرض، صوت إيقاعي) تقلل التجمد","درّب المريض على حركات بطيئة واسعة السعة بشكل متكرر","خطر السقوط مرتفع أثناء الالتفاف وأداء مهمة مزدوجة","تمارين بسط الجذع وتدويره لمواجهة الانحناء للأمام"],"case":{"text":"امرأة عمرها 72 عامًا، مرض باركنسون (Hoehn–Yahr III). تتجمد قدماها في الأبواب الضيقة وعند الالتفاف، وسقطت في المنزل عدة مرات. تشتد الأعراض عند زوال مفعول الدواء.","answer":"خطر السقوط مرتفع بسبب التجمد وعدم الثبات الوضعي. درّبها على المشي والالتفاف في فترة «on» بمثيرات بصرية/سمعية، وعدّلا بيئة السكن معًا. ناقش الأدوية مع الطبيب؛ ولا تعدّلها المريضة بنفسها."},"questions":[{"level":"أساسي","q":"أي بنية تتنكس أساسًا في مرض باركنسون؟","options":["المخيخ","المادة السوداء","القرن الأمامي للحبل الشوكي","القشرة الحركية"],"answer":1,"exp":"تتنكس العصبونات الدوبامينية في المادة السوداء؛ وانخفاض الدوبامين في الجسم المخطط يسبب الأعراض الحركية."},{"level":"أساسي","q":"ما الذي يميز رعاش مرض باركنسون؟","options":["رعاش قصدي","يزداد مع الحركة","رعاش ساكن","يستمر أثناء النوم"],"answer":2,"exp":"يظهر في الراحة ويخف مع الحركة الإرادية. الرعاش القصدي يُرى في إصابات المخيخ."},{"level":"متوسط","q":"ما الذي يميز المرحلة III حسب Hoehn–Yahr؟","options":["ظهور عدم الثبات الوضعي","أعراض في جانب واحد فقط","كرسي متحرك أو ملازمة السرير","أعراض ثنائية مع منعكسات وضعية سليمة"],"answer":0,"exp":"III: أعراض ثنائية مع عدم ثبات وضعي. I: جانب واحد؛ II: ثنائية مع منعكسات وضعية سليمة؛ V: كرسي متحرك أو ملازمة السرير."},{"level":"متوسط","q":"بماذا يمكن تقليل التجمد؟","options":["المشي بعينين مغمضتين","زيادة سرعة المشي فجأة","المشي المتكرر في ممر ضيق","مثير بصري مثل خطوط على الأرض"],"answer":3,"exp":"المثيرات الخارجية (خطوط على الأرض، صوت المسرّع الإيقاعي) تقلل التجمد وتحسّن طول الخطوة."},{"level":"سريري","q":"مريض باركنسون يتناول الدواء صباحًا وظهرًا؛ في آخر العصر يتباطأ ويتعثر التدريب. ماذا تفعل؟","options":["تزيد كمية التدريب بعد الظهر","تنقل التدريب إلى فترة «on»","يعدّل المريض الجرعة بنفسه","توقف العلاج الطبيعي"],"answer":1,"exp":"يُشتبه في ظاهرة wearing-off. وقّت التدريب في الفترة الفعالة، وأبلغ الطبيب بالتقلب. الطبيب هو من يضبط الأدوية."},{"level":"سريري","q":"مريض باركنسون أوقف دواءه فجأة؛ ظهرت حمى مرتفعة وصمل شديد واضطراب في الوعي. ماذا تفعل؟","options":["تنتظر مع حركة خفيفة","تزيد الإطالة","تتوقف وتبلغ الطبيب فورًا","تعيد التقييم في اليوم التالي"],"answer":2,"exp":"الحمى والصمل واضطراب الوعي بعد الإيقاف المفاجئ للدواء توحي بمتلازمة خبيثة (حالة شبيهة بـNMS) تتطلب رعاية عاجلة. أبلغ الطبيب فورًا."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الأمراض العصبية","icono":"🧠","mapa":"img/mapas/t38.jpg","fichas":[],"secuencias":[]},"39":{"id":39,"title":"التصلب المتعدد","lead":"التهاب يتلف غمد المايلين في الجهاز العصبي المركزي؛ وكثيرًا ما تتناوب الانتكاسات وفترات الهدأة. الأساس هو ضبط جرعة الحمل مع مراعاة سرعة التعب وارتفاع حرارة الجسم.","sheet":{"kind":"condition","items":[{"h":"الصورة المرضية","t":"مرض مناعي ذاتي: تتكون بؤر زوال المايلين في الدماغ والحبل الشوكي والعصب البصري، منتشرة زمانيًا ومكانيًا. أكثر شيوعًا لدى البالغين الشباب، ولا سيما النساء."},{"h":"الأعراض الرئيسية","t":"اضطراب البصر (التهاب العصب البصري)، وضعف عضلي، واضطراب الحس، وتشنج عضلي، ورنح، وسرعة التعب، واضطراب وظيفة المثانة والأمعاء، وعلامة ليرميت وغيرها."},{"h":"محاور التقييم","t":"EDSS، واختبار القوة العضلية اليدوي، وMAS، والتوازن، والقدرة على المشي، ودرجة التعب. تحقق أيضًا من تغير الأعراض خلال اليوم وبتأثير الحرارة."},{"h":"مسار العلاج","t":"في الانتكاس: راحة وتمارين ROM لطيفة؛ وفي الهدأة: تمارين هوائية وتقوية وتوازن، مكيّفة حسب التعب وبشكل تدريجي."},{"h":"الاحتياطات والموانع","t":"ارتفاع حرارة الجسم يفاقم الأعراض مؤقتًا (ظاهرة أوتهوف): تجنب البيئة الحارة والإجهاد الزائد، وأدرج فترات راحة."},{"h":"دواعي الإحالة الطبية","t":"تدهور بصري جديد، أو خدر أو شلل جديد، أو تفاقم مفاجئ للأعراض يستمر أكثر من 24 ساعة قد يدل على انتكاس: أبلغ الطبيب."}]},"keypoints":["تدرّب في بيئة باردة وتجنب ارتفاع حرارة الجسم","عند التعب الشديد خفف الحمل وخذ فترات راحة","طبّق برامج تمارين مختلفة في الانتكاس وفي الهدأة","أدرج تقنيات حفظ الطاقة في التدريب على ADL","عالج التشنج العضلي بالإطالة والوضعيات"],"case":{"text":"امرأة عمرها 32 عامًا، تصلب متعدد (في الهدأة). أثناء التدريب في صالة رياضية حارة ازداد ضعف الطرف السفلي وخدره، لكنه زال خلال نحو 30 دقيقة بعد الراحة والتبريد.","answer":"الأرجح تفاقم مؤقت للأعراض بسبب ارتفاع حرارة الجسم (ظاهرة أوتهوف). تابع في بيئة باردة، مع فترات راحة وشدة أقل. إن لم تتحسن بالراحة واستمرت الأعراض ففكّر في الانتكاس وأبلغ الطبيب."},"questions":[{"level":"أساسي","q":"أي بنية تتضرر أساسًا في التصلب المتعدد؟","options":["مايلين الأعصاب الطرفية","مايلين الجهاز العصبي المركزي","الموصل العصبي العضلي","الألياف العضلية الهيكلية"],"answer":1,"exp":"يتضرر غمد المايلين في الدماغ والحبل الشوكي والعصب البصري، أي في الجهاز العصبي المركزي. زوال المايلين الطرفي يحدث مثلًا في متلازمة غيلان-باريه."},{"level":"أساسي","q":"أي ظاهرة تعني التفاقم المؤقت للأعراض مع ارتفاع حرارة الجسم؟","options":["علامة ليرميت","علامة رومبرغ","منعكس بابنسكي","ظاهرة أوتهوف"],"answer":3,"exp":"ظاهرة أوتهوف: تسوء الأعراض مؤقتًا مع ارتفاع حرارة الجسم. علامة ليرميت: ألم كالصدمة الكهربائية يسري عبر الظهر إلى الأطراف عند ثني الرقبة."},{"level":"متوسط","q":"ما العلاج الطبيعي المناسب في انتكاس التصلب المتعدد؟","options":["تقوية عالية الشدة","تدريب هوائي طويل المدة","تمارين ROM لطيفة","التدريب في بيئة حارة"],"answer":2,"exp":"في الانتكاس يكون الالتهاب نشطًا، فتجنب الإجهاد الزائد؛ والأولوية لتمارين مدى الحركة اللطيفة والوضعيات."},{"level":"متوسط","q":"أي علامة: عند ثني الرقبة يسري ألم كالصدمة الكهربائية عبر الظهر إلى الأطراف؟","options":["علامة ليرميت","ظاهرة أوتهوف","منعكس هوفمان","علامة ترندلنبرغ"],"answer":0,"exp":"علامة ليرميت شائعة في آفات الحبل الشوكي العنقي، وهي من العلامات المميزة للتصلب المتعدد."},{"level":"سريري","q":"مريضة تصلب متعدد تتعب بشدة في المساء ويصبح مشيها غير ثابت. بماذا تنصح؟","options":["أن تزيد الحركة في المساء","أن توزع النشاط على أفضل أوقات اليوم","أن تستمر دون راحة","أن تتدرب في غرفة دافئة"],"answer":1,"exp":"تعامل مع سرعة التعب بمنهج حفظ الطاقة: وزّع النشاط على أفضل أوقات اليوم، وأدرج فترات راحة مخططة."},{"level":"سريري","q":"مريضة تصلب متعدد في الهدأة: منذ أيام تدهور في بصر إحدى العينين وخدر جديد في الطرف السفلي. ماذا تفعل؟","options":["تزيد شدة التدريب","تضيف العلاج الحراري","تبلغ الطبيب للاشتباه في انتكاس","تعيد التقييم بعد شهر"],"answer":2,"exp":"العرض العصبي الجديد المستمر قد يدل على انتكاس. لا تزد الحمل، وأبلغ الطبيب في أقرب وقت."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الأمراض العصبية","icono":"🧠","mapa":"img/mapas/t39.jpg","fichas":[],"secuencias":[]},"40":{"id":40,"title":"إصابة الحبل الشوكي","lead":"تضر إصابة الحبل الشوكي بالوظائف الحركية والحسية والذاتية تحت مستوى الإصابة. المحور هو تحديد أهداف تناسب الوظائف المتبقية والوقاية من المضاعفات.","sheet":{"kind":"condition","items":[{"h":"الصورة المرضية","t":"تنتج عن السقوط أو حوادث السير أو المرض؛ ونميز بين الإصابة الكاملة وغير الكاملة. الإصابة العنقية تسبب الشلل الرباعي، والإصابة الصدرية القطنية تسبب الشلل السفلي."},{"h":"الأعراض الرئيسية","t":"تحت مستوى الإصابة: شلل حركي واضطراب الحس، واضطراب وظيفة المثانة والأمعاء، واضطراب ذاتي (هبوط الضغط الانتصابي، اضطراب تنظيم الحرارة)، وتشنج عضلي."},{"h":"محاور التقييم","t":"حدد المستوى العصبي ودرجة AIS وفق معايير ASIA؛ وافحص قوة العضلات المفتاحية والحس لكل قطعة. قيّم ADL بمقياس FIM أو SCIM."},{"h":"مسار العلاج","t":"في المرحلة الحادة: إدارة التنفس، والوضعيات، والحفاظ على ROM؛ وفي المرحلة تحت الحادة: تقوية العضلات المتبقية وتدريب ADL: الجلوس، والنقل، ودفع الكرسي المتحرك."},{"h":"الاحتياطات والموانع","t":"في الإصابة فوق Th6 انتبه لخلل المنعكسات الذاتي. علّم تخفيف الضغط للوقاية من قرح الفراش؛ ومع هبوط الضغط الانتصابي: الرفع التدريجي إلى الوقوف."},{"h":"دواعي الإحالة الطبية","t":"أبلغ عن الارتفاع المفاجئ لضغط الدم مع صداع وتعرق واحمرار الوجه، والتدهور العصبي، والحمى، وتفاقم قرحة الفراش، وتورم الطرف السفلي (اشتباه خثار وريدي عميق)."}]},"keypoints":["المستوى العصبي: أدنى قطعة ما زالت وظيفتها سليمة","في إصابة C6 استخدم تأثير التينوديسيس للإمساك","في خلل المنعكسات الذاتي: أجلس المريض وأزل المحفز (مثل امتلاء المثانة)","امنع قرح الفراش بحركات منتظمة لتخفيف الضغط","في الإصابة العنقية قيّم وظيفة التنفس وساعد على إخراج البلغم"],"case":{"text":"رجل عمره 25 عامًا، إصابة كاملة عند C6 (AIS A)، بعد شهرين من الحادث. أثناء التدريب ظهر فجأة صداع شديد واحمرار في الوجه وتعرق، وارتفع ضغط الدم كثيرًا. وقد مضى الموعد المقرر للقسطرة.","answer":"يُشتبه في خلل المنعكسات الذاتي بسبب امتلاء المثانة. أوقف التدريب، وأجلسه (مع رفع الرأس)، وأرخِ الملابس، وابحث عن السبب المحفز وأزله، وأبلغ الطبيب والممرضة فورًا. لا تتركه ينتظر مستلقيًا."},"questions":[{"level":"أساسي","q":"ما العضلة المفتاحية لمستوى C7 التي تتيح النقل بالدفع (push-up)؟","options":["العضلة ذات الرأسين العضدية","العضلة ثلاثية الرؤوس العضدية","العضلة الحرقفية القطنية","العضلة رباعية الرؤوس الفخذية"],"answer":1,"exp":"العضلة المفتاحية لـC7 هي ثلاثية الرؤوس العضدية (بسط المرفق). ذات الرأسين العضدية لـC5، والحرقفية القطنية لـL2، ورباعية الرؤوس الفخذية لـL3."},{"level":"أساسي","q":"في أي مستوى إصابة يُستخدم تأثير التينوديسيس للإمساك؟","options":["C4","Th6","C6","L3"],"answer":2,"exp":"في إصابة C6 يمكن بسط الرسغ؛ ومع البسط تنثني الأصابع سلبيًا (تأثير التينوديسيس)، ويُستفاد من ذلك في الإمساك."},{"level":"متوسط","q":"ماذا تعني الدرجة A في مقياس ASIA للإعاقة (AIS)؟","options":["غير كاملة، يبقى الحس فقط","وظيفة حركية متبقية جزئيًا","سليم عصبيًا","لا وظيفة حركية ولا حسية حتى في S4–5"],"answer":3,"exp":"AIS A: إصابة كاملة، لا وظيفة حركية ولا حسية حتى في أدنى القطع العجزية (S4–5). AIS B: غير كاملة، يبقى الحس فقط."},{"level":"متوسط","q":"في أي مستوى إصابة يشيع خلل المنعكسات الذاتي؟","options":["Th6 وما فوقه","Th12 وما تحته","L3 وما تحته","ذيل الفرس"],"answer":0,"exp":"في الإصابة فوق Th6 تؤدي المحفزات تحت الآفة (مثل امتلاء المثانة) إلى استجابة ودية مفرطة وارتفاع مفاجئ في ضغط الدم."},{"level":"سريري","q":"مريض بإصابة C6: عند زيادة زاوية الطاولة المائلة يظهر دوار وشحوب وهبوط في الضغط. ماذا تفعل؟","options":["تواصل الرفع ليعتاد","تعيد الطاولة فورًا إلى الوضع الأفقي","تواصل التدريب","تثني رقبته للأمام وهو جالس"],"answer":1,"exp":"يُشتبه في هبوط الضغط الانتصابي. أعد الطاولة، وتحقق من الأعراض وضغط الدم. الوقاية: حزام بطني، وجوارب ضاغطة، ورفع تدريجي إلى الوقوف."},{"level":"سريري","q":"مريض بإصابة صدرية كاملة على كرسي متحرك: احمرار عجزي لا يبهت بالضغط ويستمر. ماذا تفعل؟","options":["تدلك الاحمرار بقوة","تعوّده على جلوس أطول","تراجع طريقة تخفيف الضغط وتكراره","لا داعي لفعل شيء"],"answer":2,"exp":"الاحمرار المستمر علامة مبكرة لقرحة الفراش. راجع تخفيف الضغط ووسادة الجلوس، وأبلغ الفريق المعالج. تدليك الاحمرار يفاقم تلف الأنسجة."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الأمراض العصبية","icono":"🧠","mapa":"img/mapas/t40.jpg","fichas":[],"secuencias":[]},"41":{"id":41,"title":"إصابات الأعصاب الطرفية","lead":"يتضرر العصب الطرفي بسبب رضّ أو انضغاط، فتنخفض الوظيفة الحركية والحسية والذاتية في منطقة تعصيبه. من المهم متابعة شدة الإصابة ومسار التجدد.","sheet":{"kind":"condition","items":[{"h":"الصورة المرضية","t":"تصنيف سيدون: اضطراب توصيل مؤقت (neurapraxia)، وانقطاع المحور العصبي (axonotmesis)، وانقطاع العصب الكامل (neurotmesis)."},{"h":"الأعراض الرئيسية","t":"شلل رخو وضمور في العضلات المعصّبة، واضطراب الحس واضطراب التعرق في منطقة التعصيب. المنعكسات الوترية منخفضة أو غائبة."},{"h":"محاور التقييم","t":"اختبار القوة العضلية اليدوي، وفحص الحس (اللمس، الألم، التمييز بين نقطتين)، وتغير موقع علامة تينيل، ونتائج تخطيط العضلات ودراسة التوصيل العصبي."},{"h":"مسار العلاج","t":"امنع الإطالة المفرطة للعضلات المشلولة بجبيرة، وحافظ على مدى الحركة. ومع تقدم إعادة التعصيب انتقل تدريجيًا من التمرين النشط المساعَد إلى التقوية."},{"h":"الاحتياطات والموانع","t":"في منطقة فقدان الحس احذر الحروق وإصابات الضغط. تجنب إجهاد العضلات المشلولة والإطالة المفرطة بعد خياطة العصب."},{"h":"دواعي الإحالة الطبية","t":"أبلغ عن التقدم المفاجئ للشلل، أو الألم أو التورم الشديد، أو تغير لون الجلد، أو غياب التحسن بعد المدة المتوقعة."}]},"keypoints":["انتقال علامة تينيل نحو البعيد علامة على تجدد العصب","في اليد والقدم المتدليتين امنع التقفع والإطالة المفرطة بجبيرة","علّم المريض أن يراقب منطقة الحس المنخفض بعينيه ويحميها","يتقدم التحسن من العضلات القريبة من الإصابة نحو البعيدة","بعد خياطة العصب التزم بمدة التثبيت التي حددها الطبيب"],"case":{"text":"رجل عمره 45 عامًا: منذ كسر في جسم عظم العضد لا يستطيع بسط رسغه وأصابعه. الحس منخفض على ظهر اليد بين الإبهام والسبابة. بسط المرفق ممكن.","answer":"يُشتبه في شلل العصب الكعبري (يد متدلية) على مستوى جسم العضد. امنع الإطالة المفرطة والتقفع بجبيرة تثبت الرسغ في عطف ظهري، وحافظ على ROM. تابع التحسن بعلامة تينيل واختبار العضلات؛ وإن تأخر فأبلغ الطبيب."},"questions":[{"level":"أساسي","q":"شلل أي عصب يسبب اليد المتدلية؟","options":["العصب المتوسط","العصب الزندي","العصب الكعبري","العصب العضلي الجلدي"],"answer":2,"exp":"يعصّب العصب الكعبري باسطات الرسغ والأصابع؛ وعند شلله يتعذر بسط الرسغ وتنشأ اليد المتدلية."},{"level":"أساسي","q":"شلل أي عصب يسبب الوضع المخلبي للإصبعين IV–V؟","options":["العصب الزندي","العصب الكعبري","العصب الإبطي","العصب الفخذي"],"answer":0,"exp":"في شلل العصب الزندي تُشل العضلات بين العظام والعضلات الدودية للإصبعين IV–V، فيتخذ البنصر والخنصر وضعًا مخلبيًا."},{"level":"متوسط","q":"حسب سيدون، في أي حالة يبقى المحور العصبي سليمًا ويضطرب التوصيل مؤقتًا فقط؟","options":["Neurotmesis","Neurapraxia","Axonotmesis","تنكس والر"],"answer":1,"exp":"الـneurapraxia اضطراب توصيل مؤقت مع بقاء استمرارية المحور العصبي؛ لا يصاحبه تنكس والر ويُشفى بسرعة نسبيًا."},{"level":"متوسط","q":"أي موجودة تصلح لمتابعة تجدد العصب الطرفي؟","options":["زيادة المنعكسات الوترية","منعكس بابنسكي","الصمل","انتقال موقع علامة تينيل"],"answer":3,"exp":"النقر على طرف المحور العصبي المتجدد يثير خدرًا منتشرًا؛ وانتقال هذه النقطة نحو البعيد علامة على التجدد."},{"level":"سريري","q":"بعد جبيرة جبسية للساق يتعذر العطف الظهري للكاحل بسبب ضغط على رأس الشظية. ماذا تفعل؟","options":["تثبت الكاحل في عطف أخمصي","تعالج القدم المتدلية بجبيرة الكاحل والقدم","تقوي العضلة المشلولة بمقاومة كبيرة","تطبق حرارة قوية على منطقة الحس المنخفض"],"answer":1,"exp":"في القدم المتدلية الناتجة عن شلل العصب الشظوي المشترك تمنع جبيرة الكاحل والقدم التعثر والتقفع في العطف الأخمصي. الحرارة على منطقة الحس المنخفض تسبب خطر الحروق."},{"level":"سريري","q":"بعد جرح في الجانب الراحي من الرسغ يتعذر تقابل الإبهام، وتضمر عضلات الرانفة. إصابة أي عصب هي الأرجح؟","options":["العصب الزندي","الفرع السطحي للعصب الكعبري","العصب المتوسط","العصب العضلي الجلدي"],"answer":2,"exp":"يعصّب العصب المتوسط عضلات الرانفة (مثل العضلة المقابلة للإبهام)؛ وعند شلله يصعب التقابل وتنشأ يد القرد."}],"seccion":"الإصابات وإعادة التأهيل","grupo":"الأمراض العصبية","icono":"🧠","mapa":"img/mapas/t41.jpg","fichas":[],"secuencias":[]},"42":{"id":42,"title":"العلاج اليدوي (طريقة ميتلاند)","lead":"نظام يعتمد على فحص الحركات الإضافية للمفصل وعلى حركات سلبية متذبذبة مصنفة في درجات، يؤثر في الألم ومدى الحركة. من سماته تكرار الفحص وإعادة الفحص.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"يخفف الألم ويحسن حركية المفصل باستخدام الحركات الإضافية للمفصل. تختار التقنية وشدتها بناءً على استجابة المريض."},{"h":"التقنيات والأنواع الرئيسية","t":"حركات سلبية متذبذبة في الدرجات I–IV. الدرجة V دفعة (thrust) عالية السرعة صغيرة السعة، أي تقويم يدوي."},{"h":"دواعي الاستعمال","t":"ألم مفصلي المنشأ، وتقييد الحركة بسبب قِصر المحفظة أو الأربطة (ألم أسفل الظهر، ألم الرقبة، الكتف المتجمد وغيرها)."},{"h":"الموانع والاحتياطات","t":"لا يُطبق عند الكسر، أو الورم الخبيث، أو العدوى، أو المرحلة الحادة لمرض التهابي، أو هشاشة العظام الشديدة، أو عرض عصبي مترقٍّ، أو الاشتباه في إصابة وعائية عنقية."},{"h":"نصائح التطبيق","t":"عند غلبة الألم اختر الدرجات I–II، وعند غلبة التيبس III–IV. تحقق من العلامات المقارنة قبل العلاج وبعده لتقدير الأثر."},{"h":"الأدلة العلمية","t":"قد يخفف الألم على المدى القصير عند دمجه بالتمارين العلاجية. أثره طويل المدى محدود عند استخدامه وحده."}]},"keypoints":["للألم الدرجات I–II، وللتيبس III–IV","قدّر الأثر بالعلامات المقارنة قبل العلاج وبعده","افحص الحركة الإضافية حسب الفرق بين الجانبين والشعور النهائي","استبعد العلامات الحمراء قبل تطبيق التقنية","حافظ على مدى الحركة المكتسب بتمارين منزلية"],"case":{"text":"رجل عمره 50 عامًا، تيبس مزمن في الجانب الأيمن من الرقبة. ألمه في الراحة ضئيل؛ وفي نهاية الدوران إلى اليمين يشعر بمقاومة وألم خفيف. لا توجد علامات حمراء.","answer":"التيبس يغلب على الألم، لذا يمكن النظر في الدرجات III–IV التي تدخل المقاومة. أعد فحص ROM الدوران والألم قبل العلاج وبعده، وانقل المكتسب إلى تمارين منزلية. لا تطبق دفعة قوية دون فحص."},"questions":[{"level":"أساسي","q":"أي وصف صحيح للدرجة IV حسب ميتلاند؟","options":["سعة كبيرة قبل المقاومة","سعة صغيرة في بداية المدى","سعة صغيرة في نهاية المدى","سعة كبيرة داخل المقاومة"],"answer":2,"exp":"الدرجة IV حركة صغيرة السعة داخل المقاومة في نهاية مدى الحركة. سعة صغيرة في بداية المدى: I؛ سعة كبيرة داخل المقاومة: III."},{"level":"أساسي","q":"أي درجة تختار أساسًا لتسكين الألم؟","options":["الدرجات I–II","الدرجات III–IV","الدرجة V فقط","الدرجة IV فقط"],"answer":0,"exp":"تجري الدرجات I–II في المدى السابق للمقاومة، وتُستخدم أساسًا لتسكين الألم. أما III–IV فللتيبس وتقييد الحركة."},{"level":"متوسط","q":"أي تقنية تعني الدرجة V حسب ميتلاند؟","options":["سعة كبيرة قبل المقاومة","دفعة عالية السرعة صغيرة السعة","شد مستمر","عجن الأنسجة الرخوة"],"answer":1,"exp":"الدرجة V دفعة عالية السرعة صغيرة السعة تُجرى في نهاية مدى الحركة، أي تقويم يدوي."},{"level":"متوسط","q":"ماذا تقارن قبل العلاج وبعده لتقدير الأثر؟","options":["القيم المخبرية","نتائج التصوير","تغير وزن الجسم","العلامات المقارنة (asterisk)"],"answer":3,"exp":"قبل العلاج سجّل الأعراض ومدى الحركة القابلة للتكرار كعلامات مقارنة، ثم تحقق من التغير بعده."},{"level":"سريري","q":"مريض بألم حاد أسفل الظهر: ألم شديد عند التحريك وتوتر عضلي دفاعي. بأي درجة تبدأ؟","options":["الدرجة IV","الدرجة V","الدرجات I–II","الدرجة III"],"answer":2,"exp":"عند الألم الشديد وزيادة التفاعلية خفف الألم بالدرجات I–II التي لا تدخل المقاومة."},{"level":"سريري","q":"مريض بألم الرقبة: عند تدوير الرقبة يظهر دوار وازدواج الرؤية وعسر التلفظ. ماذا تفعل؟","options":["تتوقف وتبلغ الطبيب","تقوّي الدرجة IV","تحاول التحسين بدفعة","تزيد عدد التكرارات"],"answer":0,"exp":"الدوار وازدواج الرؤية وعسر التلفظ علامات تشير إلى إصابة وعائية عنقية. أوقف العلاج اليدوي وأبلغ الطبيب."}],"seccion":"العلاجات والتدخلات","grupo":"التقنيات والعلاج بالوسائل الفيزيائية","icono":"🤲","mapa":"img/mapas/t42.jpg","fichas":[],"secuencias":[]},"43":{"id":43,"title":"التيسير العصبي العضلي للحس العميق (PNF)","lead":"ينشّط الاستجابات العصبية العضلية بتنبيه المستقبلات الحسية العميقة. من سماته الأنماط الحركية الحلزونية القطرية، ويُستخدم لتحسين القوة العضلية والتوافق ومدى الحركة.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"ييسّر الاستجابة الحركية بتنبيه المستقبلات الحسية العميقة، ويحسن القوة العضلية والتوافق والثبات ومدى الحركة."},{"h":"التقنيات والأنواع الرئيسية","t":"الأنماط القطرية لحزام الكتف وحزام الحوض والأطراف، مع بدء الحركة الإيقاعي، والانقباض ثم الاسترخاء (hold–relax)، والتثبيت الإيقاعي، وتقنيات أخرى."},{"h":"دواعي الاستعمال","t":"الحالات العصبية المركزية والعظمية وإصابات الرياضة، عند وجود ضعف عضلي، أو اضطراب التوافق، أو تقييد الحركة، أو عدم ثبات المفصل."},{"h":"الموانع والاحتياطات","t":"لا يُطبق في الكسر غير الملتئم، أو في منطقة ما بعد الجراحة حيث لم يُسمح بالمقاومة بعد، أو عند الألم الشديد. مع الخطر القلبي الوعائي انتبه لحبس النفس."},{"h":"نصائح التطبيق","t":"اجمع بين التلامس اليدوي، والتوجيه اللفظي، والتغذية الراجعة البصرية، والشد/التقريب، والإطالة، والمقاومة المثلى، والتوقيت. لا تعِق المقاومة سلاسة الحركة."},{"h":"الأدلة العلمية","t":"تفيد التقارير بأنه يحسن مدى الحركة والوظيفة العضلية. يعتمد الأثر على الحالة والهدف؛ ويُطبق مع تمارين علاجية أخرى."}]},"keypoints":["في تقييد الحركة بسبب الألم: الانقباض ثم الاسترخاء (hold–relax)","إذا صعب بدء الحركة: بدء الحركة الإيقاعي","لتكن المقاومة «مثلى»: لا تعيق سلاسة الحركة","في التوقيت الطبيعي تبدأ الحركة من الجزء البعيد","تجنب حبس النفس، وليتنفس المريض باستمرار"],"case":{"text":"امرأة عمرها 60 عامًا، تقييد في التبعيد بعد التهاب حول مفصل الكتف. الألم شديد عند الحركة، ويزداد التوتر العضلي الدفاعي مع الإطالة السلبية.","answer":"لتقييد الحركة المصحوب بالألم تناسب تقنية الانقباض ثم الاسترخاء التي تستخدم الانقباض متساوي القياس. طبّقها دون زيادة الألم، وقِس ROM قبلها وبعدها. تجنب الإطالة السلبية القوية المتكررة."},"questions":[{"level":"أساسي","q":"ما الذي يميز الأنماط الحركية في PNF؟","options":["حركة في مستوى واحد وخط مستقيم","حركة حلزونية قطرية","حركة متساوية الحركية فقط","حركة سلبية فقط"],"answer":1,"exp":"أنماط PNF حركات حلزونية قطرية تجمع مكونات الثني–البسط، والتقريب–التبعيد، والدوران."},{"level":"أساسي","q":"أي عنصر أساسي في PNF ينقل اتجاه الحركة عبر يد أخصائي العلاج الطبيعي؟","options":["التنبيه البارد","التنبيه الكهربائي","التلامس اليدوي","الموجات فوق الصوتية"],"answer":2,"exp":"يوجّه التلامس اليدوي انقباض المريض العضلي واتجاه حركته بضغط يعمل في اتجاه الحركة."},{"level":"متوسط","q":"أي تقنية PNF تطبق إذا صعب على المريض بدء الحركة؟","options":["الانقباض ثم الاسترخاء","الشد ثم الاسترخاء","التثبيت الإيقاعي","بدء الحركة الإيقاعي"],"answer":3,"exp":"يتدرج بدء الحركة الإيقاعي: سلبي ← نشط مساعَد ← نشط ← مقاوَم، فيساعد على بدء الحركة وتعلمها."},{"level":"متوسط","q":"أي تقنية تزيد ثبات المفصل بانقباضات متساوية القياس متناوبة؟","options":["التثبيت الإيقاعي","بدء الحركة الإيقاعي","الشد ثم الاسترخاء","الإطالة المتكررة"],"answer":0,"exp":"في التثبيت الإيقاعي تنقبض المجموعات العضلية المتضادة بالتناوب انقباضًا متساوي القياس دون حركة، ما يزيد الثبات."},{"level":"سريري","q":"ثني الركبة مقيد بسبب الألم. أي تقنية PNF مناسبة لتحسين مدى الحركة؟","options":["الشد ثم الاسترخاء","الانقباض ثم الاسترخاء","الإطالة المتكررة","بدء الحركة الإيقاعي"],"answer":1,"exp":"في تقنية الانقباض ثم الاسترخاء يتبع الانقباضَ متساوي القياس للعضلة المقيِّدة استرخاءٌ؛ وتُطبق في تقييد الحركة المصحوب بالألم."},{"level":"سريري","q":"أثناء تمرين PNF بالمقاومة يحبس المريض نفسه ويحمرّ وجهه. ماذا تفعل؟","options":["تزيد المقاومة أكثر","تزيد عدد التكرارات","تطلب منه ألا يحبس نفسه","تطلب إيقاعًا أسرع"],"answer":2,"exp":"حبس النفس يرفع ضغط الدم. اضبط المقاومة، واطلب منه أداء التمرين مع التنفس المستمر."}],"seccion":"العلاجات والتدخلات","grupo":"التقنيات والعلاج بالوسائل الفيزيائية","icono":"🤲","mapa":"img/mapas/t43.jpg","fichas":[],"secuencias":[]},"44":{"id":44,"title":"العلاج الكهربائي","lead":"يخفف الألم أو يثير الانقباض العضلي بالتنبيه الكهربائي. يُختار نوع التيار ومعاييره حسب الهدف، ويجب دائمًا التحقق من موانع الاستعمال.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"تسكين الألم، والحفاظ على القوة العضلية وزيادتها بإثارة الانقباض العضلي، وإعادة تعلم الحركة، وتقليل الوذمة."},{"h":"التقنيات والأنواع الرئيسية","t":"TENS (التنبيه الكهربائي للعصب عبر الجلد)، وNMES (التنبيه الكهربائي العصبي العضلي)، وFES (التنبيه الكهربائي الوظيفي)، والتيار المتداخل، والتيار النبضي عالي الجهد وغيرها."},{"h":"دواعي الاستعمال","t":"الألم الحاد والمزمن، وضعف العضلات بعد الجراحة أو التثبيت، وتيسير العضلات المصابة بالخزل بعد السكتة الدماغية، وتنبيه القدم المتدلية أثناء المشي."},{"h":"الموانع والاحتياطات","t":"يُتجنب مع منظم ضربات القلب وغيره من الأجهزة الإلكترونية المزروعة، وعلى البطن وأسفل الظهر لدى الحامل، وفوق الجيب السباتي، وفي المناطق الورمية أو ذات الجلد المتضرر أو اضطراب الحس."},{"h":"نصائح التطبيق","t":"تحقق من حالة الجلد والحس؛ واضبط موضع القطب وحجمه، والتردد، وعرض النبضة، والشدة، ومدة العلاج حسب الهدف."},{"h":"الأدلة العلمية","t":"تفيد التقارير بفائدته في ضعف العضلة الرباعية بعد الجراحة وفي التحسن الوظيفي بعد السكتة الدماغية. نتائج أثره على الألم متضاربة."}]},"keypoints":["قبل العلاج تحقق من حالة الجلد ومن أي اضطراب في الحس","اسأل دائمًا في التاريخ المرضي عن الأجهزة الإلكترونية المزروعة","للألم اختر TENS، ولإثارة الانقباض العضلي اختر NMES","بعد العلاج لاحظ وجود احمرار أو سخونة تحت القطب","ادمج التنبيه الكهربائي بالتمرين النشط"],"case":{"text":"رجل عمره 65 عامًا، بعد جراحة استبدال مفصل الركبة. الانقباض الإرادي للعضلة الرباعية ضعيف، وعند SLR لا تنبسط الركبة كليًا (عجز البسط). لا يوجد منظم ضربات قلب ولا تغيرات جلدية.","answer":"لضعف الرباعية وقصور انقباضها يمكن النظر في NMES مع التمرين النشط. ضع الأقطاب بعيدًا عن الجرح الجراحي، وراقب تفاعل الجلد والألم. لا تطبق التيار على الجرح ولا على منطقة الحس المنخفض."},"questions":[{"level":"أساسي","q":"أي علاج كهربائي يستخدم تنبيهًا بمستوى حسي أساسًا لتسكين الألم؟","options":["FES","TENS","NMES","الموجات فوق الصوتية"],"answer":1,"exp":"ينبه TENS الأعصاب الحسية عبر الجلد بهدف تسكين الألم. أما NMES فيثير الانقباض العضلي، وFES يساعد الحركة."},{"level":"أساسي","q":"أي علاج كهربائي ينبه العضلة بتوقيت متزامن مع الحركة (كالمشي) ليعوّض الوظيفة؟","options":["TENS","الموجات فوق الصوتية","FES","الكمادات الساخنة"],"answer":2,"exp":"ينبه FES (التنبيه الكهربائي الوظيفي) العضلات بإيقاع الحركة ويعوّض الوظيفة، مثلًا في القدم المتدلية أثناء المشي."},{"level":"متوسط","q":"ما مانع استعمال العلاج الكهربائي من بين التالي؟","options":["ألم مزمن أسفل الظهر","ضعف عضلي بعد الجراحة","القدم المتدلية","منظم ضربات قلب مزروع"],"answer":3,"exp":"قد تتعطل الأجهزة الإلكترونية المزروعة بتأثير التيار، لذا تُعد مانعًا. الخيارات الأخرى دواعٍ للاستعمال."},{"level":"متوسط","q":"أي طريقة تقاطع تيارين متوسطي التردد لينشأ تنبيه منخفض التردد في العمق؟","options":["التيار المتداخل","TENS","FES","الرحلان الأيوني"],"answer":0,"exp":"يقاطع التيار المتداخل تيارين متوسطي التردد مختلفي التردد؛ فينشأ في العمق تنبيه منخفض التردد يساوي الفرق بينهما."},{"level":"سريري","q":"بعد استبدال مفصل الركبة الانقباض الإرادي للرباعية ضعيف. ما الاختيار المناسب؟","options":["العلاج الحراري فقط","NMES مع التمرين النشط","قطب على الجرح الجراحي","الراحة حتى يعود الانقباض"],"answer":1,"exp":"يُطبق NMES في قصور انقباض الرباعية بعد الجراحة، مع التمرين النشط. ضع القطب بعيدًا عن الجرح."},{"level":"سريري","q":"بعد التنبيه الكهربائي يُرى احمرار وفقاعة مكان القطب. ماذا تفعل؟","options":["تواصل بشدة أكبر","تلصقه في المكان نفسه مجددًا","تتوقف وتفحص الجلد وتبلغ","تنتظر مع التدفئة"],"answer":2,"exp":"الاحمرار والفقاعة تحت القطب قد يدلان على إصابة جلدية. أوقف العلاج، ووثّق حالة الجلد، وأبلغ."}],"seccion":"العلاجات والتدخلات","grupo":"التقنيات والعلاج بالوسائل الفيزيائية","icono":"🤲","mapa":"img/mapas/t44.jpg","fichas":[],"secuencias":[]},"45":{"id":45,"title":"الموجات فوق الصوتية والليزر والحرارة والبرودة","lead":"تؤثر في الألم وحالة الأنسجة بالحرارة أو الموجات الصوتية أو الضوء أو التبريد. تقرر التدفئة أو التبريد حسب المرحلة والهدف، وتتحقق من موانع الاستعمال.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"تسكين الألم، وخفض التوتر العضلي، وتحسين قابلية الأنسجة للإطالة، وتخفيف التورم الالتهابي الحاد؛ قبل التمارين العلاجية أو بعدها."},{"h":"التقنيات والأنواع الرئيسية","t":"الموجات فوق الصوتية (مستمرة، نبضية)، والليزر منخفض القدرة، والعلاج الحراري السطحي (كمادات ساخنة، بارافين)، والإنفاذ الحراري بالموجات الدقيقة، والعلاج بالبرودة (كمادات الثلج وغيرها)."},{"h":"دواعي الاستعمال","t":"الحرارة: الألم المزمن، والتيبس، والتقفع؛ البرودة: الألم والتورم بعد إصابة حادة؛ الموجات فوق الصوتية: منها تحسين قابلية الأنسجة الرخوة للإطالة."},{"h":"الموانع والاحتياطات","t":"تُتجنب الحرارة في الالتهاب الحاد، والميل للنزف، والمناطق الورمية؛ والموجات فوق الصوتية على العين، وبطن الحامل، وغضروف النمو؛ والبرودة في المنطقة المصابة بظاهرة رينو."},{"h":"نصائح التطبيق","t":"قبل العلاج تحقق من الجلد ومن الإحساس بالحرارة والبرودة، وراقب الجلد أثناءه. حرّك رأس جهاز الموجات فوق الصوتية باستمرار، ولا تتوقف عند نقطة واحدة."},{"h":"الأدلة العلمية","t":"تُستخدم لتسكين الألم على المدى القصير مكمّلةً للتمارين العلاجية. أثرها المستقل محدود حسب أغلب التقارير؛ والعنصر الأساسي هو العلاج بالحركة."}]},"keypoints":["للتورم والسخونة الحادين البرودة، وللتيبس المزمن الحرارة","تحقق مسبقًا من الإحساس بالحرارة والبرودة، وتجنب مناطق اضطراب الحس","حرّك رأس جهاز الموجات فوق الصوتية دون توقف","بعد العلاج الحراري تناسبه الإطالة والعلاج بالحركة","العلاج الفيزيائي مكمّل للعلاج بالحركة"],"case":{"text":"رجل عمره 22 عامًا، أصيب بالتواء انقلابي في الكاحل أثناء لعب كرة القدم؛ اليوم التالي للإصابة. حول الكعب الوحشي تورم وسخونة وألم عند الضغط، وألم شديد عند التحميل. استبعد الطبيب الكسر.","answer":"توجد علامات التهابية حادة، لذا خفف الألم والتورم بالعلاج بالبرودة والضغط والرفع. الحرارة في هذه المرحلة قد تزيد التورم، فتجنبها. للوقاية من إصابة التجمد راقب الجلد أثناء العلاج."},"questions":[{"level":"أساسي","q":"أي علاج فيزيائي تطبق لتقليل التورم والألم الحادين؟","options":["الكمادات الساخنة","البارافين","العلاج بالبرودة","الإنفاذ الحراري بالموجات الدقيقة"],"answer":2,"exp":"تسبب البرودة تضيق الأوعية، فتقلل الألم والتورم الحادين. الخيارات الأخرى علاجات حرارية تُتجنب في الالتهاب الحاد."},{"level":"أساسي","q":"أيّها من العلاجات الحرارية السطحية؟","options":["الإنفاذ الحراري بالموجات الدقيقة","الكمادات الساخنة","الموجات فوق الصوتية المستمرة","الليزر منخفض القدرة"],"answer":1,"exp":"تدفّئ الكمادات الساخنة والبارافين الأنسجة السطحية بدءًا من الجلد. أما الإنفاذ بالموجات الدقيقة والموجات فوق الصوتية المستمرة فعلاج حراري عميق."},{"level":"متوسط","q":"أي منطقة يُمنع فيها العلاج بالموجات فوق الصوتية؟","options":["العضلة رباعية الرؤوس الفخذية","محيط الكتف","العضلة ثلاثية الرؤوس الربلية","مقلة العين"],"answer":3,"exp":"مقلة العين منطقة يُمنع فيها العلاج بالموجات فوق الصوتية. وتُتجنب أيضًا بطن الحامل، وغضروف النمو، والمنطقة الورمية."},{"level":"متوسط","q":"ما الطريقة الصحيحة لتطبيق الموجات فوق الصوتية؟","options":["تحريك الرأس باستمرار","تثبيت الرأس عند نقطة واحدة","التطبيق دون جل","الاستمرار رغم الألم"],"answer":0,"exp":"إذا ثبت الرأس في مكانه تتركز الحرارة وقد تسبب تلف الأنسجة، لذا تُطبق مع الجل وبتحريك مستمر."},{"level":"سريري","q":"التواء الكاحل، اليوم التالي للإصابة: تورم وسخونة واضحان. ما العلاج الفيزيائي المناسب؟","options":["الكمادات الساخنة","البرودة والضغط والرفع","البارافين","الإنفاذ الحراري بالموجات الدقيقة"],"answer":1,"exp":"عند وجود علامات التهابية حادة خفف الألم والتورم بالبرودة والضغط والرفع. الحرارة قد تزيد التورم."},{"level":"سريري","q":"انخفض الإحساس في القدم بسبب اعتلال الأعصاب السكري؛ ومخطط لكمادات ساخنة على القدم. ماذا تفعل؟","options":["تطبقها بحرارة أعلى ولمدة قصيرة","تطبقها بالطريقة المعتادة","لا تطبق الحرارة على منطقة الحس المنخفض","تطبقها طويلًا أثناء النوم"],"answer":2,"exp":"منطقة اضطراب الحس لا تدرك الحرارة جيدًا، وخطر الحروق كبير. تجنب العلاج الحراري واختر طريقة أخرى."}],"seccion":"العلاجات والتدخلات","grupo":"التقنيات والعلاج بالوسائل الفيزيائية","icono":"🤲","mapa":"img/mapas/t45.jpg","fichas":[],"secuencias":[]},"46":{"id":46,"title":"العلاج المائي والتدليك والتصريف اللمفاوي اليدوي","lead":"يستخدم العلاج المائي قوة طفو الماء وضغطه وحرارته، ويؤثر التدليك والتصريف اللمفاوي اليدوي في الأنسجة الرخوة باليد. الأساس هو الموازنة الدقيقة بين دواعي الاستعمال وموانعه.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"يساعد العلاج المائي الحركة وتسكين الألم بقوة الطفو وضغط الماء والحرارة. يخفف التدليك التوتر العضلي، ويقلل التصريف اللمفاوي اليدوي الوذمة اللمفاوية."},{"h":"التقنيات والأنواع الرئيسية","t":"الحمام الدوامي، وحوض هابارد، والتمارين في المسبح. التدليك: المسح، والعجن، والضغط وغيرها. في الوذمة اللمفاوية: العلاج الفيزيائي المركب للوذمة (العناية بالجلد، والتصريف اليدوي، والضغط، والحركة)."},{"h":"دواعي الاستعمال","t":"أمراض المفاصل وما بعد الجراحات التي تتطلب تقييد التحميل، والألم وزيادة التوتر العضلي، والوذمة اللمفاوية الثانوية (مثل ما بعد جراحة الأورام)، والوذمة اللمفاوية الأولية."},{"h":"الموانع والاحتياطات","t":"الحمى، والعدوى الحادة (مثل التهاب النسيج الخلوي)، والخثار الوريدي العميق الحاد، والجرح المفتوح، وقصور القلب غير المعاوض. في الماء يزيد الضغط الهيدروستاتيكي عبء القلب."},{"h":"نصائح التطبيق","t":"ابدأ التصريف اللمفاوي من الجهة المركزية للمنطقة الوذمية، بضغط خفيف يحرك الجلد فقط. في التمارين المائية تحقق من حرارة الماء والمدة والحالة والعلامات الحيوية."},{"h":"الأدلة العلمية","t":"في الوذمة اللمفاوية يُوصى بالعلاج المركب الذي يشمل الضغط. أثر التدليك وحده محدود، لذا يُطبق مع التمارين العلاجية."}]},"keypoints":["قوة الطفو تخفف التحميل؛ ويتغير العبء مع عمق الماء","الضغط الهيدروستاتيكي يساعد العود الوريدي لكنه يُجهد القلب","ابدأ التصريف اللمفاوي من الجهة المركزية وبضغط خفيف","احمرار أو سخونة أو حمى: اشتبه في عدوى وتوقف","في الوذمة اللمفاوية: علاج مركب يشمل الضغط"],"case":{"text":"امرأة عمرها 65 عامًا. وذمة لمفاوية ثانوية بعد جراحة سرطان الثدي؛ محيط الطرف العلوي المصاب أكبر من السليم. لا احمرار ولا سخونة ولا حمى، ولم يُشخَّص خثار وريدي عميق.","answer":"مع غياب علامات العدوى والخثار يُستطب العلاج المركب. اجمع بين العناية بالجلد، والتصريف اليدوي بضغط خفيف بدءًا من الجهة المركزية، والضغط، والحركة تحت الضغط. عند الاحمرار أو الحمى توقف وأحِلها إلى الطبيب."},"questions":[{"level":"أساسي","q":"أي خاصية للماء تقلل عبء وزن الجسم على المفاصل؟","options":["قوة الطفو","اللزوجة","الحرارة النوعية","التوتر السطحي"],"answer":0,"exp":"تعمل قوة الطفو عكس وزن الجسم، فتقلل التحميل. اللزوجة مقاومة للحركة، والحرارة النوعية ترتبط بالأثر الحراري."},{"level":"أساسي","q":"في التصريف اللمفاوي اليدوي، أي منطقة تعالج أولًا؟","options":["الجزء البعيد الأشد وذمة","الجزء المركزي من المنطقة الوذمية","أطراف أصابع اليدين والقدمين","الجزء الأشد ألمًا فقط"],"answer":1,"exp":"تصرّف أولًا الجزء المركزي (العقد اللمفاوية، جهة الجذع) لتفتح الطريق، ثم تتقدم نحو البعيد."},{"level":"متوسط","q":"ما أبرز موانع التصريف اللمفاوي اليدوي؟","options":["وذمة لمفاوية ثانوية مزمنة","وذمة لمفاوية في الطرف العلوي بمرحلة المداومة","خثار وريدي عميق حاد","جفاف خفيف في الجلد"],"answer":2,"exp":"في الخثار الوريدي العميق الحاد قد تنفصل الخثرة، لذا يُمنع. الوذمة اللمفاوية المزمنة من دواعي الاستعمال، وجفاف الجلد يُعالج بالعناية بالجلد."},{"level":"متوسط","q":"ما الذي ليس جزءًا من العلاج المركب للوذمة اللمفاوية؟","options":["العناية بالجلد","التصريف اللمفاوي اليدوي","العلاج بالضغط","إبقاء الطرف المصاب في راحة دائمة"],"answer":3,"exp":"عناصر العلاج المركب: العناية بالجلد، والتصريف اليدوي، والضغط، والتمارين تحت الضغط. التثبيت الطويل ليس جزءًا منه."},{"level":"سريري","q":"امرأة في الستينيات، وذمة في الذراع بعد جراحة سرطان الثدي. أثناء التصريف يظهر فجأة احمرار وسخونة وحمى في الطرف. ماذا تفعل؟","options":["تزيد ضغط التصريف","توقف العلاج وتبلغ الطبيب","تضيف العلاج الحراري","تواصل بضغط أقوى"],"answer":1,"exp":"علامات تدل على عدوى حادة (مثل التهاب النسيج الخلوي). أوقف التصريف والضغط والعلاج الحراري، وأحِلها إلى الطبيب فورًا."},{"level":"سريري","q":"رجل في السبعينيات، قصور القلب مع ضيق النفس حتى في الراحة. تفكر في تمارين المسبح. ما القرار الصحيح؟","options":["عبء القلب يزيد، فنسّق مع الطبيب","يمكن أداؤها دون قيود بسبب الطفو","أداؤها في ماء عميق ولمدة طويلة","أداؤها في ماء أدفأ"],"answer":0,"exp":"في الماء يزيد الضغط الهيدروستاتيكي العود الوريدي وعبء القلب. في قصور القلب غير المستقر نسّق دواعي الاستعمال مع الطبيب."}],"seccion":"العلاجات والتدخلات","grupo":"التقنيات والعلاج بالوسائل الفيزيائية","icono":"🤲","mapa":"img/mapas/t46.jpg","fichas":[],"secuencias":[]},"47":{"id":47,"title":"شريط الكينيزيو","lead":"يُلصق شريط مرن على الجلد لإعطاء تنبيه حسي ومساعدة حركة المفصل. اعرف أساسيات اللصق والوقاية من مشكلات الجلد، واستخدمه مكمّلًا للتمارين العلاجية.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"يساعد النشاط العضلي بالتنبيه الحسي عبر الجلد، ويوجه حركة المفصل، ويحسن الوعي بالقوام، وقد يساعد على تقليل الوذمة والكدمة. التثبيت القوي ليس هدفًا."},{"h":"التقنيات والأنواع الرئيسية","t":"الأشكال: I وY وX والمروحة (لمفاوي). هناك لصق موجه للعضلة، ولدعم المفصل، وللوذمة. للتثبيت نستخدم شريطًا غير مرن (صلبًا)."},{"h":"دواعي الاستعمال","t":"المساعدة على تخفيف الألم والتورم بعد إصابة رياضية، وإعادة تعلم استخدام العضلة، والوعي بالقوام ومحاذاة المحاور، إلى جانب التمارين العلاجية."},{"h":"الموانع والاحتياطات","t":"إصابة الجلد، والعدوى، والإكزيما، وحساسية سابقة من الشريط، والاشتباه في خثار وريدي عميق، والمسن ذو الجلد الهش. في منطقة اضطراب الحس يصعب ملاحظة مشكلة الجلد."},{"h":"نصائح التطبيق","t":"ليكن الجلد نظيفًا وجافًا، وقُصّ الزوايا مستديرة. ألصق الطرفين دون شد. جرّب أولًا بقطعة صغيرة، واطلب نزعه فورًا عند الحكة أو الاحمرار."},{"h":"الأدلة العلمية","t":"حسب أغلب الدراسات أثره على الألم قصير المدى ومحدود، لذا فهو ليس علاجًا مستقلًا بل مكمّل للتمارين العلاجية."}]},"keypoints":["هدف الشريط المرن الدعم لا التثبيت","ضع الطرفين على الجلد دون شد","جلد نظيف وجاف؛ وقُصّ الزوايا مستديرة","عند الحكة أو الاحمرار يجب نزعه فورًا","أثره محدود، فادمجه بالتمارين العلاجية"],"case":{"text":"رجل عمره 22 عامًا، بعد 3 أيام من التواء انقلابي في الكاحل. يُرى تورم وكدمة حول الكعب الوحشي، وألم خفيف عند التحميل. لم يُستخدم له الشريط من قبل، ولا تاريخ لمرض جلدي.","answer":"افحص أولًا حالة الجلد، وألصق قطعة تجريبية صغيرة. للتورم استخدم شكل المروحة بشد قليل، إلى جانب التمارين العلاجية. لا تقل إن الشريط سيعالج الإصابة؛ واطلب نزعه عند الحكة أو الاحمرار."},"questions":[{"level":"أساسي","q":"بأي شد تلصق طرفي الشريط المرن؟","options":["بأقصى مط","بشد قوي للطرفين فقط","دون شد","مع قرص الجلد"],"answer":2,"exp":"تضع الطرفين (المرساتين) على الجلد دون شد. الشد في الطرفين يسحب الجلد ويؤدي إلى انفصال الشريط وتهيج الجلد."},{"level":"أساسي","q":"ما الشكل الذي تقص فيه الشريط إلى ذراعين وتحيط بهما ببطن العضلة؟","options":["شكل I","شكل X","شكل المروحة","شكل Y"],"answer":3,"exp":"تثبت قاعدة شكل Y عند نقطة واحدة، وتحيط بالذراعين ببطن العضلة. شكل المروحة يُقص إلى شرائط رفيعة تنتشر على الوذمة."},{"level":"متوسط","q":"عند أي علامة يجب نزع الشريط فورًا بعد اللصق؟","options":["حكة أو احمرار في موضع اللصق","توتر عضلي خفيف بعد التدريب","انتباه أسهل لقوامه","شعوره بأن الحركة أسهل"],"answer":0,"exp":"الحكة والاحمرار علامتا تهيج جلدي (مثل حساسية الشريط). للوقاية من التفاقم اطلب نزعه فورًا."},{"level":"متوسط","q":"ماذا تختار إذا أردت تقييد حركة المفصل بقوة وتثبيته؟","options":["شريط مرن بشكل I","شريط غير مرن (صلب)","شريط مرن بشكل المروحة","شكل Y دون شد"],"answer":1,"exp":"للتثبيت القوي يلزم شريط غير مرن. الشريط المرن بالكاد يعيق الحركة؛ وهدفه الدعم والتنبيه الحسي."},{"level":"سريري","q":"رجل في العشرينيات، تخطط لشريط على تورم ما بعد التواء الكاحل. ما أهم ما تتحقق منه قبل اللصق؟","options":["سرعة المشي","النبض في الراحة","حالة الجلد وحساسية سابقة من الشريط","القدم الأمهر"],"answer":2,"exp":"قبل اللصق افحص إصابة الجلد والإكزيما والحساسية السابقة من الشريط. عند وجود مشكلة جلدية لا تلصق الشريط."},{"level":"سريري","q":"امرأة في الثلاثينيات تقول بعد لصق الشريط على كتفها: «الألم أقل». ماذا تقول لها؟","options":["تجدد النسيج وتعافت تمامًا","الأثر غالبًا مؤقت ويلزم مع التمارين","يجب أن تلبسه دائمًا","زادت قوتها العضلية فورًا"],"answer":1,"exp":"أثر الشريط قصير المدى ومحدود. لا ترفع التوقعات؛ واشرح أنه مكمّل للتمارين العلاجية."}],"seccion":"العلاجات والتدخلات","grupo":"التقنيات والعلاج بالوسائل الفيزيائية","icono":"🤲","mapa":"img/mapas/t47.jpg","fichas":[],"secuencias":[]},"48":{"id":48,"title":"التمارين العلاجية","lead":"جوهر العلاج الطبيعي: بتمارين موصوفة نحسن القوة العضلية والمرونة والتحمل والتوازن لتتحسن أنشطة ADL. اعرف مبادئ التحميل ومعايير الإيقاف لتتقدم بأمان.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"تحسين مدى الحركة، والقوة العضلية، والتحمل العضلي والعام، والمرونة، والتوازن، والتوافق، لتتحسن الحركات الأساسية وأنشطة ADL والمشاركة."},{"h":"التقنيات والأنواع الرئيسية","t":"تمرين ROM (سلبي، نشط مساعَد، نشط)، والتقوية (متساوية القياس، ومتساوية التوتر بنوعيها المركزي واللامركزي، ومتساوية الحركة)، والإطالة، والتدريب الهوائي، وتمارين التوازن والتوافق."},{"h":"دواعي الاستعمال","t":"على نطاق واسع: أمراض الجهاز الحركي، وما بعد الجراحات، والأمراض العصبية والباطنية، ومتلازمة قلة النشاط، وفقدان الوظيفة لدى كبار السن."},{"h":"الموانع والاحتياطات","t":"مرض قلبي غير مستقر، وارتفاع ضغط غير مضبوط، والتهاب حاد، وكسر غير مثبت: حذر أو مانع. تحقق من معايير إيقاف التحميل."},{"h":"نصائح التطبيق","t":"اضبط الحمل وفق مبادئ الحمل الزائد والخصوصية والانعكاسية، وراقب الشعور الذاتي بالجهد والعلامات الحيوية. لاحظ التعويض؛ ولا يحبس المريض نفسه."},{"h":"الأدلة العلمية","t":"في كثير من أمراض الجهاز الحركي والأمراض المزمنة يُعد التمرين العلاجي الأساس الموصى به للعلاج. يعتمد الأثر على إمكانية الاستمرار في البرنامج."}]},"keypoints":["ابنِ الحمل وفق مبادئ الحمل الزائد والخصوصية والانعكاسية","في المرحلة المبكرة بعد الجراحة ابدأ بتمرين متساوي القياس لا يحرك المفصل","تجنب حبس النفس (الكبس)، وليتنفس المريض باستمرار","لاحظ التعويض، وليعمل المريض بحركة صحيحة","ألم صدري، أو عرق بارد، أو ضيق نفس شديد: توقف فورًا وأبلغ"],"case":{"text":"امرأة عمرها 72 عامًا، بعد 3 أسابيع من استبدال مفصل الركبة. قوة العضلة الرباعية بدرجة 3: تحرك نشطًا في كامل مدى الحركة لكنها لا تتحمل مقاومة. علاماتها الحيوية مستقرة.","answer":"ابدأ بالحركة النشطة ضد الجاذبية، ثم أضف تدريجيًا مقاومة خفيفة. راقب التعويض والألم، وتجنب حبس النفس. لا تعطِ حملًا أقصى منذ اليوم الأول."},"questions":[{"level":"أساسي","q":"ما شكل الانقباض الذي تولد فيه العضلة توترًا وهي تستطيل؟","options":["انقباض مركزي","انقباض لا مركزي","انقباض متساوي القياس","انقباض متساوي الحركة"],"answer":1,"exp":"في الانقباض اللامركزي تولد العضلة قوة أثناء استطالتها. وفي المركزي أثناء قصرها، وفي متساوي القياس دون تغير في طولها."},{"level":"أساسي","q":"وفق أي مبدأ يجب إعطاء حمل أكبر من المعتاد اليومي لزيادة القوة العضلية؟","options":["مبدأ الخصوصية","مبدأ الانعكاسية","مبدأ الحمل الزائد","مبدأ التفريد"],"answer":2,"exp":"وفق مبدأ الحمل الزائد ينشأ التكيف استجابةً لمنبه يتجاوز الحمل المعتاد."},{"level":"متوسط","q":"أي تمرين يقوي دون حركة المفصل، لذا يناسب المرحلة المبكرة بعد الجراحة؟","options":["تمرين متساوي القياس","تمرين متساوي الحركة","تمرين القفز","تمرين لا مركزي بحمل كبير"],"answer":0,"exp":"في التمرين متساوي القياس تنقبض العضلة دون تحريك المفصل، فيحمي المفصل والجرح، لذا يمكن أداؤه مبكرًا."},{"level":"متوسط","q":"ما الذي يجب تجنبه أثناء تمرين التقوية؟","options":["التنفس المستمر","مراقبة التعويض","الإحماء","حبس النفس"],"answer":3,"exp":"حبس النفس (الكبس) يرفع ضغط الدم فجأة. وخاصة لدى كبار السن ومرضى القلب، ليتنفس المريض باستمرار."},{"level":"سريري","q":"رجل في السبعينيات، قوة العضلة الرباعية بدرجة 3. كيف تبدأ التقوية؟","options":["تمرين متساوي الحركة بأقصى مقاومة","حركة نشطة ضد الجاذبية وتحميل تدريجي","بالتحريك السلبي فقط","تمرين قفز عالي الشدة"],"answer":1,"exp":"الدرجة 3 تعني الحركة في كامل المدى ضد الجاذبية. ابدأ بالحركة النشطة، وأضف تدريجيًا مقاومة خفيفة."},{"level":"سريري","q":"رجل في الستينيات، أثناء الدراجة الثابتة يظهر ألم صدري وعرق بارد. ماذا تفعل؟","options":["توقف التمرين، وتقيس العلامات الحيوية، وتبلغ الطبيب","تخفف الحمل وتواصل","تواصل بالحمل نفسه بعد راحة","تنتقل إلى الإطالة"],"answer":0,"exp":"الألم الصدري والعرق البارد من معايير الإيقاف وقد يدلان على مرض قلبي. أوقف فورًا، وقِس العلامات الحيوية، وأبلغ الطبيب."}],"seccion":"العلاجات والتدخلات","grupo":"العلاج بالحركة والتخصصات","icono":"🩺","mapa":"img/mapas/t48.jpg","fichas":[],"secuencias":[{"nombre":"الجسر","rotulo":"يقوّي","texto":"عضلات الأرداف وأوتار الركبة الخلفية","frames":["img/mov/ponte-1.jpg","img/mov/ponte-2.jpg","img/mov/ponte-3.jpg"]},{"nombre":"رفع الساق المستقيمة","rotulo":"يقوّي","texto":"العضلة رباعية الرؤوس","frames":["img/mov/elevacao-1.jpg","img/mov/elevacao-2.jpg","img/mov/elevacao-3.jpg"]},{"nombre":"القرفصاء","rotulo":"يقوّي","texto":"العضلة رباعية الرؤوس وعضلات الأرداف","frames":["img/mov/agachamento-1.jpg","img/mov/agachamento-2.jpg","img/mov/agachamento-3.jpg"]}]},"49":{"id":49,"title":"العلاج الطبيعي التنفسي","lead":"يحسن التهوية ويقلل ضيق النفس بتعليم تقنيات التنفس، والمساعدة على إخراج الإفرازات، والتمارين العلاجية. له دور محوري في COPD وفي الوقاية من المضاعفات الرئوية بعد الجراحة.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"تحسين التهوية، وتسهيل تنظيف المسالك الهوائية، وتقليل ضيق النفس، وتحسين القدرة على تحمل الجهد وأنشطة ADL، والوقاية من المضاعفات الرئوية بعد الجراحة."},{"h":"التقنيات والأنواع الرئيسية","t":"التنفس بالشفتين المزمومتين، والتنفس الحجابي، والتصريف الوضعي، والزفير القسري وتعليم السعال، ومساعدة التنفس، وتدريب عضلات التنفس، وتمارين التحمل العام والتقوية."},{"h":"دواعي الاستعمال","t":"أمراض الجهاز التنفسي المزمنة (مثل COPD)، والالتهاب الرئوي، وقبل جراحات الصدر والبطن وبعدها، واضطراب التهوية بسبب مرض عصبي عضلي، وتوسع القصبات مع إفرازات كثيرة."},{"h":"الموانع والاحتياطات","t":"يُتجنب التصريف بوضعية الرأس للأسفل عند ارتفاع الضغط داخل القحف، أو عدم استقرار الدورة الدموية، أو نفث الدم. انتبه للاسترواح الصدري غير المعالج واضطراب النظم الشديد؛ وتابع SpO2 والأعراض."},{"h":"نصائح التطبيق","t":"حدد موقع الإفرازات بالتسمع ونتائج التصوير، واختر الوضعية وفقه. تابع SpO2 ومعدل التنفس والنبض ومقياس بورغ المعدل؛ واجعل الحركة متوافقة مع إيقاع التنفس."},{"h":"الأدلة العلمية","t":"في COPD يُوصى بالتأهيل التنفسي القائم على التمارين العلاجية لتقليل ضيق النفس وتحسين القدرة على تحمل الجهد."}]},"keypoints":["التنفس بالشفتين المزمومتين يمنع انخماص المسالك الهوائية أثناء الزفير","في التصريف الوضعي تكون القطعة الرئوية ذات الإفرازات للأعلى","الزفير القسري: زفير قوي وسريع مع مزمار مفتوح","تُتجنب وضعية الرأس للأسفل عند ارتفاع الضغط داخل القحف أو نفث الدم","في COPD أساس التأهيل التنفسي هو التمرين العلاجي"],"case":{"text":"رجل عمره 74 عامًا، COPD، دون علاج منزلي بالأكسجين. ضيق نفس شديد عند المشي وارتداء الملابس؛ وتنخفض SpO2 بعد الحركة المتعجلة. إفرازاته قليلة، وحالته في الراحة مستقرة.","answer":"علّمه التنفس بالشفتين المزمومتين وتنظيم وتيرة الحركة، ثم نفّذ تمارين التحمل وتقوية الطرفين السفليين مع متابعة SpO2 وضيق النفس. اطلب منه ألا يستعجل وهو يحبس نفسه."},"questions":[{"level":"أساسي","q":"في COPD، أي تقنية تنفس تعلّمها لمنع انخماص المسالك الهوائية أثناء الزفير؟","options":["تنفس صدري سريع وسطحي","حبس النفس","التنفس بالشفتين المزمومتين","فرط التهوية"],"answer":2,"exp":"يضيف التنفس بالشفتين المزمومتين مقاومة للزفير، فيحافظ على الضغط في المسالك الهوائية، ويمنع الانخماص، ويسهل الزفير."},{"level":"أساسي","q":"في أي طريقة تضع القطعة الرئوية ذات الإفرازات للأعلى لتساعد الجاذبية على تحريكها؟","options":["الزفير القسري","التصريف الوضعي","تدريب عضلات التنفس","التنفس بالشفتين المزمومتين"],"answer":1,"exp":"في التصريف الوضعي تكون القطعة ذات الإفرازات للأعلى، فتحرك الجاذبية الإفرازات نحو المسالك الهوائية المركزية."},{"level":"متوسط","q":"ما التقنية التي تحرك فيها الإفرازات بزفير قوي وسريع مع مزمار مفتوح؟","options":["كبت السعال","التنفس الحجابي","مناورة فالسالفا","الزفير القسري (huffing)"],"answer":3,"exp":"الزفير القسري زفير مجهد مع مزمار مفتوح؛ يحرك الإفرازات بارتفاع في الضغط داخل الصدر أقل من السعال."},{"level":"متوسط","q":"في أي حالة يُتجنب التصريف الوضعي بوضعية الرأس للأسفل؟","options":["ارتفاع الضغط داخل القحف","توسع القصبات المزمن","التهاب رئوي مع إفرازات كثيرة","انخماص الفص السفلي"],"answer":0,"exp":"وضعية الرأس للأسفل ترفع الضغط داخل القحف، لذا تُتجنب عند ارتفاعه. الحالات الأخرى قد تكون من دواعي التصريف."},{"level":"سريري","q":"رجل في السبعينيات، COPD. أثناء المشي يزداد ضيق النفس وتنخفض SpO2. ماذا تعلّمه؟","options":["أن يمشي سريعًا لينتهي بسرعة","التنفس بالشفتين المزمومتين وتنظيم وتيرة الحركة","أن يتحرك وهو يحبس نفسه","أن يتوقف عن المشي كليًا"],"answer":1,"exp":"ليجعل وتيرة الحركة متوافقة مع التنفس، وليستخدم التنفس بالشفتين المزمومتين. الخمول التام يسرّع فقدان اللياقة."},{"level":"سريري","q":"مريض في اليوم الأول بعد جراحة في البطن. ما الذي يساعد في الوقاية من المضاعفات الرئوية بعد الجراحة؟","options":["الراحة في السرير عدة أيام","إهمال تمارين التنفس بسبب الألم","التحريك المبكر وتعليم التنفس العميق والسعال","وضعية الرأس للأسفل لمدة طويلة"],"answer":2,"exp":"التحريك المبكر وتعليم التنفس العميق والسعال (مع دعم الجرح) مهمان للوقاية من الانخماص والالتهاب الرئوي."}],"seccion":"العلاجات والتدخلات","grupo":"العلاج بالحركة والتخصصات","icono":"🩺","mapa":"img/mapas/t49.jpg","fichas":[],"secuencias":[]},"50":{"id":50,"title":"إعادة التأهيل القلبي","lead":"برنامج مركب يجمع التمارين العلاجية وتثقيف المريض والإرشاد في نمط الحياة. يهدف إلى تحسين القدرة على تحمل الجهد وجودة الحياة والوقاية من الانتكاس. السلامة أولًا.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"تحسين القدرة على تحمل الجهد وجودة الحياة، وتصحيح عوامل خطر الشريان التاجي، والوقاية من الانتكاس وإعادة الدخول، وتقليل القلق، والمساعدة على العودة إلى العمل والمجتمع."},{"h":"التقنيات والأنواع الرئيسية","t":"تدريب هوائي (مشي، دراجة ثابتة)، وتدريب بالمقاومة، وتثقيف المريض، وإرشاد في نمط الحياة (تناول الدواء، والغذاء، والإقلاع عن التدخين). يتقدم في ثلاث مراحل: حادة، وتأهيل، ومداومة."},{"h":"دواعي الاستعمال","t":"بعد احتشاء عضلة القلب الحاد، والذبحة الصدرية، وبعد جراحة القلب، وقصور القلب المزمن، وأمراض الأوعية الكبيرة، ومرض الشرايين الطرفية. الشرط هو استقرار الحالة."},{"h":"الموانع والاحتياطات","t":"الذبحة غير المستقرة، واضطراب النظم غير المضبوط، وقصور القلب غير المعاوض، والتضيق الأبهري الشديد العرضي، والتهاب عضلة القلب الحاد: التمرين العلاجي ممنوع."},{"h":"نصائح التطبيق","t":"اضبط الشدة حسب العتبة اللاهوائية (AT) من اختبار الجهد القلبي الرئوي أو حسب الشعور الذاتي بالجهد. مع حاصرات بيتا بالكاد يرتفع النبض: راقب الأعراض وضغط الدم وتخطيط القلب أيضًا."},{"h":"الأدلة العلمية","t":"في مرض الشريان التاجي وقصور القلب المزمن توصي الإرشادات بالتأهيل القلبي المركب الذي يشمل التمارين العلاجية."}]},"keypoints":["التمرين والتثقيف والإرشاد في نمط الحياة معًا","اضبط الشدة حسب AT أو الشعور الذاتي بالجهد","مع حاصرات بيتا لا تقرر بناءً على النبض وحده","ألم صدري، أو تغير ST، أو اضطراب النظم: توقف","زيادة مفاجئة في الوزن أو وذمة: اشتبه في تفاقم قصور القلب"],"case":{"text":"رجل عمره 63 عامًا، بعد علاج احتشاء عضلة القلب الحاد، يتمرن في العيادات الخارجية ضمن مرحلة التأهيل. يتناول حاصرات بيتا. أثناء الدراجة الثابتة لا يشكو من أعراض صدرية، لكن نبضه بالكاد يرتفع.","answer":"تُضعف حاصرات بيتا استجابة النبض، لذا لا ترفع الحمل بناءً على النبض وحده: قرر حسب الشعور الذاتي بالجهد وضغط الدم وتخطيط القلب. عند ألم صدري أو تغير ST توقف وأبلغ الطبيب."},"questions":[{"level":"أساسي","q":"ما الذي ليس جزءًا من التأهيل القلبي؟","options":["التمرين العلاجي","تثقيف المريض","تصحيح عوامل خطر الشريان التاجي","الراحة الدائمة في السرير"],"answer":3,"exp":"التأهيل القلبي برنامج مركب يشمل التمرين، وتثقيف المريض، والإرشاد في نمط الحياة، والدعم النفسي. الراحة الطويلة في السرير تؤدي إلى فقدان اللياقة."},{"level":"أساسي","q":"أي مؤشر مستخرج من اختبار الجهد القلبي الرئوي تستخدمه لضبط الشدة؟","options":["اختبار القوة العضلية اليدوي","العتبة اللاهوائية (AT)","مدى الحركة","قوة القبضة"],"answer":1,"exp":"العتبة اللاهوائية (AT) مؤشر شائع لشدة التدريب الهوائي؛ وتُحدد باختبار الجهد القلبي الرئوي."},{"level":"متوسط","q":"ما مانع التمرين العلاجي من بين التالي؟","options":["قصور قلب مزمن مستقر","مرحلة التأهيل بعد جراحة المجازة","الذبحة غير المستقرة","المرحلة المستقرة بعد الاحتشاء"],"answer":2,"exp":"الذبحة غير المستقرة مانع للتمرين العلاجي. أما قصور القلب المزمن المستقر ومرحلة التأهيل بعد الجراحة أو الاحتشاء فمن دواعي الاستعمال."},{"level":"متوسط","q":"لدى مريض يتناول حاصرات بيتا، ما المفيد لتقدير الشدة؟","options":["الشعور الذاتي بالجهد (مقياس بورغ)","النبض وحده","وزن الجسم","حرارة الجسم"],"answer":0,"exp":"تثبط حاصرات بيتا ارتفاع النبض، فقد تضبط حملًا مفرطًا إن اعتمدت على النبض وحده. استخدم الشعور الذاتي بالجهد أيضًا."},{"level":"سريري","q":"رجل في الستينيات، مرحلة التأهيل بعد الاحتشاء. أثناء تمرين المشي يظهر ألم صدري وانخفاض ST. ماذا تفعل؟","options":["تزيد سرعة المشي","تواصل وتراقب","بالحمل نفسه بعد تعويض السوائل","توقف التمرين وتبلغ الطبيب"],"answer":3,"exp":"الألم الصدري وانخفاض ST علامة إيقاف تشير إلى إقفار عضلة القلب. أوقف التمرين فورًا وأبلغ الطبيب."},{"level":"سريري","q":"امرأة في السبعينيات، قصور قلب مزمن. خلال أيام زاد وزنها فجأة وتفاقمت وذمة الساقين وضيق النفس. ماذا تفعل؟","options":["تزيد الشدة","تشتبه في تفاقم قصور القلب وتبلغ الطبيب","تدرّبها بالطريقة المعتادة","تضيف تدريب التقوية فقط"],"answer":1,"exp":"زيادة الوزن في وقت قصير والوذمة وتزايد ضيق النفس علامات تفاقم قصور القلب. أجّل التمرين وأبلغ الطبيب."}],"seccion":"العلاجات والتدخلات","grupo":"العلاج بالحركة والتخصصات","icono":"🩺","mapa":"img/mapas/t50.jpg","fichas":[],"secuencias":[]},"51":{"id":51,"title":"صحة قاع الحوض وصحة المرأة","lead":"يتناول سلس البول وهبوط أعضاء الحوض الناتجين عن خلل وظيفة عضلات قاع الحوض، والتغيرات الجسدية بعد الحمل والولادة. الأساس هو تعليم الانقباض الصحيح وفحص العلامات الحمراء.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"تحسين قوة عضلات قاع الحوض وتحملها وتوافقها، وتخفيف السلس وهبوط الأعضاء؛ ومعالجة ألم أسفل الظهر والحوض ووظيفة الجذع بعد الحمل والولادة."},{"h":"التقنيات والأنواع الرئيسية","t":"تمارين قاع الحوض، والتغذية الراجعة الحيوية، وتعليم التحكم في الضغط داخل البطن والتنفس، وتعليم القوام والحركة، والإرشاد في نمط الحياة (عادات التبول، والتحكم في الوزن وغيرها)."},{"h":"دواعي الاستعمال","t":"السلس الإجهادي والمختلط، وهبوط أعضاء الحوض الخفيف، وضعف قاع الحوض بعد الولادة، وتباعد عضلتي البطن المستقيمتين، والسلس لدى الرجال بعد استئصال البروستاتا الجذري."},{"h":"الموانع والاحتياطات","t":"يتطلب الفحص الداخلي (المهبلي) تدريبًا متخصصًا وشرحًا وافيًا وموافقة. في أواخر الحمل قد يسبب الاستلقاء الطويل على الظهر متلازمة الوريد الأجوف. بيلة دموية، أو حمى، أو خدر العجان: إلى الطبيب."},{"h":"نصائح التطبيق","t":"تحقق من انقباض الضغط والرفع؛ ولتتجنب المريضة شد عضلات البطن والألية والمقربات والكبس. لتتدرب على انقباضات سريعة ومستمرة، بطريقة يمكن مواصلتها في الحياة اليومية."},{"h":"الأدلة العلمية","t":"في السلس الإجهادي تمارين قاع الحوض هي الخيار الأول للعلاج المحافظ. يعتمد الأثر على مواظبة المريضة."}]},"keypoints":["علّم عضلات قاع الحوض بتوجيه «اضغطي وارفعي للأعلى»","الكبس وشد عضلات الألية تعويض يجب تجنبه","تسرب عند السعال أو العطس: سلس إجهادي","في أواخر الحمل قد يسبب الاستلقاء الطويل على الظهر هبوط الضغط","اضطراب تبول مفاجئ أو خدر العجان: إحالة فورية للفحص الطبي"],"case":{"text":"امرأة عمرها 38 عامًا، بعد عام من الولادة. يتسرب البول عند السعال والعطس. عند الجلوس من الاستلقاء يبرز خط البطن الأوسط. لا بيلة دموية ولا حمى ولا اضطراب حس في منطقة العجان.","answer":"تفكر في سلس إجهادي وتباعد عضلتي البطن المستقيمتين. علّمها الانقباض الصحيح لقاع الحوض والتحكم في الضغط داخل البطن دون كبس. تجنب التكرار المفاجئ والكثير لتمارين الجلوس القوية."},"questions":[{"level":"أساسي","q":"ما العضلة الرئيسية في قاع الحوض؟","options":["العضلة الحرقفية القطنية","العضلة الألوية الكبرى","العضلة الرافعة للشرج","العضلة المستقيمة الفخذية"],"answer":2,"exp":"تشكل العضلة الرافعة للشرج مع العضلة العصعصية الحجاب الحوضي، وهي العضلة الرئيسية في قاع الحوض. البقية عضلات حول الورك."},{"level":"أساسي","q":"في أي نوع من السلس يتسرب البول عند ارتفاع الضغط داخل البطن بالسعال أو العطس؟","options":["السلس الإلحاحي","السلس الإجهادي","السلس بالفيضان","السلس الوظيفي"],"answer":1,"exp":"في السلس الإجهادي يكون إغلاق الإحليل غير كافٍ عند ارتفاع الضغط داخل البطن. أما السلس الإلحاحي فيصاحبه إلحاح شديد للتبول."},{"level":"متوسط","q":"كيف تعلّم انقباض تمارين قاع الحوض بشكل صحيح؟","options":["بحبس النفس والكبس البطني","بضغط عضلات الألية بقوة","بدفع البطن للأمام","ضغط الإحليل والمهبل والمستقيم ورفعها"],"answer":3,"exp":"لتقبض عضلات قاع الحوض بحركة ضغط ورفع. الكبس وشد عضلات الألية ودفع البطن للأمام تعويض."},{"level":"متوسط","q":"إلامَ يجب الانتباه إذا استلقت طويلًا على ظهرها في أواخر الحمل؟","options":["متلازمة الوريد الأجوف (هبوط الضغط الاستلقائي)","تحسن تباعد عضلتي البطن","تضخم عضلات قاع الحوض","زوال السلس"],"answer":0,"exp":"في أواخر الحمل وفي الاستلقاء على الظهر يضغط الرحم على الوريد الأجوف السفلي وقد ينخفض ضغط الدم. اقلبها مثلًا إلى الاستلقاء الجانبي."},{"level":"سريري","q":"امرأة عمرها 38 عامًا، بعد عام من الولادة يتسرب البول عند السعال ويبرز خط البطن الأوسط عند الجلوس. ما التدخل المناسب؟","options":["تمارين جلوس قوية كثيرة يوميًا","تمارين قاع الحوض والتحكم في الضغط داخل البطن","تقليل تناول السوائل بشدة","نصيحة بالراحة فقط"],"answer":1,"exp":"الأرجح سلس إجهادي وتباعد عضلتي البطن المستقيمتين. ابدأ بالانقباض الصحيح لقاع الحوض والتحكم في الضغط داخل البطن."},{"level":"سريري","q":"امرأة في الخمسينيات تتلقى العلاج لألم أسفل الظهر. أبلغت فجأة عن صعوبة في التبول وخدر في العجان. ماذا تفعل؟","options":["تزيد تمارين قاع الحوض","تنتظر حتى الجلسة التالية","تبلغ الطبيب فورًا","تجري إطالة قطنية"],"answer":2,"exp":"اضطراب التبول المفاجئ واضطراب الحس في العجان علامة حمراء تشير إلى متلازمة ذيل الفرس. إحالة فورية للفحص الطبي."}],"seccion":"العلاجات والتدخلات","grupo":"العلاج بالحركة والتخصصات","icono":"🩺","mapa":"img/mapas/t51.jpg","fichas":[],"secuencias":[]},"52":{"id":52,"title":"العلاج الطبيعي للأطفال","lead":"مجال يدعم النمو الحركي للطفل ونشاطه ومشاركته. يقوم على معرفة النمو الطبيعي، ويتقدم باللعب وبالتعاون مع الأسرة.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"تعزيز النمو الحركي، واكتساب الحركات الأساسية والتنقل، والوقاية من الأضرار الثانوية (التقفع، التشوه)، وتوسيع المشاركة في المنزل والروضة والمدرسة، ودعم الأسرة."},{"h":"التقنيات والأنواع الرئيسية","t":"المقاربة العصبية النمائية، والتدريب الموجه نحو المهام، والحركة باللعب، وإدارة الوضعيات، والجبائر، واستخدام أدوات دعم الجلوس والمشاية، وتدريب الأسرة."},{"h":"دواعي الاستعمال","t":"الشلل الدماغي، وتأخر النمو، ومتلازمة داون، والسنسنة المشقوقة، والحثل العضلي من نوع دوشين، والخدج منخفضو وزن الولادة، والأمراض العظمية."},{"h":"الموانع والاحتياطات","t":"في الشلل الدماغي التشنجي من المهم مراقبة الخلع الجزئي والكامل للورك. في الحثل العضلي تجنب الحمل الكبير الذي يترك تعبًا. انتبه لنوبات الصرع وللتعب."},{"h":"نصائح التطبيق","t":"للتقييم استخدم GMFM وGMFCS والمنعكسات البدائية وردود الفعل الوضعية. تدرّب في لعب ممتع، وشارك الأهداف اليومية مع الأسرة ليمكن الاستمرار في المنزل."},{"h":"الأدلة العلمية","t":"تدعم الأدلة التدريب الموجه نحو المهام المبني على أهداف واضحة، والتدخل بالتعاون مع الأسرة. الممارسة اليومية أهم من التقنيات المنفردة."}]},"keypoints":["الموعد المتوقع للتحكم في الرأس عمر 3–4 أشهر","يصنف GMFCS الحركات الكبرى في الشلل الدماغي إلى 5 مستويات","في الشلل الدماغي التشنجي افحص خلع الورك بانتظام","في الحثل العضلي تجنب الحمل الكبير الذي يترك تعبًا","شارك الهدف مع الأسرة، وتدرّب باللعب"],"case":{"text":"طفل عمره 5 سنوات، شلل مزدوج تشنجي. يتنقل في المنزل بالمشاية، لكن المشي على رؤوس الأصابع لافت. ترغب الأسرة في أن «يتمكن من التنقل مع أصدقائه في الروضة».","answer":"اجعل رغبة الأسرة هدفًا يوميًا: اربط تدريب التنقل بالمشاية باللعب وبأنشطة الروضة. امنع قِصر العضلة ثلاثية الرؤوس الربلية، وفكّر في الجبيرة، وافحص الورك. لا تتمسك بتسلسل النمو الطبيعي وحده."},"questions":[{"level":"أساسي","q":"متى يُتوقع اكتساب التحكم في الرأس؟","options":["في عمر شهر واحد","في عمر 3–4 أشهر","في عمر 7–8 أشهر","في عمر 12 شهرًا"],"answer":1,"exp":"يُتوقع التحكم في الرأس نحو عمر 3–4 أشهر. ويليه التقلب، والجلوس، والوقوف بالتمسك، والمشي المستقل."},{"level":"أساسي","q":"أي مقياس يصنف قدرة الحركات الكبرى لدى الطفل المصاب بالشلل الدماغي إلى 5 مستويات؟","options":["GMFM","MRC","FIM","GMFCS"],"answer":3,"exp":"يصنف GMFCS قدرة الحركات الكبرى إلى 5 مستويات. أما GMFM فيقيس وظيفة الحركات الكبرى بالدرجات."},{"level":"متوسط","q":"أي حركة تتجنبها في الحثل العضلي من نوع دوشين؟","options":["حركة بحمل كبير تترك تعبًا","تمرين ROM","تمرين التنفس","الحركة باللعب"],"answer":0,"exp":"تتضرر الألياف العضلية بسهولة، لذا تجنب الحمل الكبير الذي يترك تعبًا شديدًا. الوقاية من التقفع وتمارين التنفس مهمة."},{"level":"متوسط","q":"في الشلل الدماغي التشنجي، أي مضاعفة من المهم فحصها بانتظام؟","options":["تمزق الرباط الصليبي الأمامي","تمزق الكفة المدورة","الخلع الجزئي والكامل للورك","التواء الكاحل"],"answer":2,"exp":"بسبب تشنج العضلات حول الورك واختلال توازنها يشيع الخلع الجزئي والكامل للورك، لذا يلزم فحص منتظم."},{"level":"سريري","q":"طفل عمره 4 سنوات، شلل مزدوج تشنجي. كيف تحدد هدف المشي بشكل صحيح؟","options":["أخصائي العلاج الطبيعي يقرر وحده","تحدد هدفًا يوميًا بالاشتراك مع الأسرة","وفق تسلسل النمو الطبيعي حصرًا","تدرّبه بالتكرار فقط دون لعب"],"answer":1,"exp":"شارك الهدف مع الأسرة، واربطه بنشاط محدد في المنزل أو الروضة. اللعب يساعد على استمرار التدريب."},{"level":"سريري","q":"طفل عمره 7 سنوات، حثل عضلي من نوع دوشين، يزداد صعود الدرج صعوبة عليه. ما المنهج الحركي الصحيح؟","options":["نشاط دون إرهاق، ووقاية من التقفع","تقوية لا مركزية بحمل كبير","منع كل حركة","تمشيته يوميًا حتى الإنهاك التام"],"answer":0,"exp":"الحمل المفرط قد يسرّع تلف العضلات. حافظ على النشاط بقدر لا يترك تعبًا، وواصل الوقاية من التقفع."}],"seccion":"العلاجات والتدخلات","grupo":"العلاج بالحركة والتخصصات","icono":"🩺","mapa":"img/mapas/t52.jpg","fichas":[],"secuencias":[]},"53":{"id":53,"title":"العلاج الطبيعي لكبار السن","lead":"يتمحور حول فقدان الوظيفة المرتبط بالشيخوخة، والوهن (frailty)، وساركوبينيا (نقص الكتلة العضلية)، والسقوط. نساعد المسن، بناءً على التقييم، على مواصلة الحركة بأمان مع الحفاظ على اعتماده على نفسه ومشاركته.","sheet":{"kind":"method","items":[{"h":"الهدف","t":"الحفاظ على ADL ووظائف إدارة الحياة والمشاركة وتحسينها؛ والوقاية من السقوط؛ والوقاية من الوهن وساركوبينيا وتحسينهما؛ والوقاية من متلازمة قلة النشاط؛ وتخفيف العبء عن مقدمي الرعاية."},{"h":"التقنيات والأنواع الرئيسية","t":"تقوية الطرف السفلي والجذع، وتمارين التوازن، وتدريب المشي، والتدريب بمهمة مزدوجة، وتدريب الجلوس والوقوف والانتقال، واختيار الأدوات المساعدة، وتعديل بيئة السكن."},{"h":"دواعي الاستعمال","t":"الوهن، وساركوبينيا، وبعد سقوط سابق أو كسر أو جراحة، وقلة النشاط بسبب مرض مزمن، وفقدان اللياقة الناتج عن الإقامة في المستشفى، ودعم نشاط المصابين بالخرف."},{"h":"الموانع والاحتياطات","t":"انتبه لهبوط الضغط الانتصابي، وكسر الفقرات الناتج عن هشاشة العظام، والآثار الجانبية لتعدد الأدوية، والجفاف، والجلد الهش، والتدهور المعرفي. ألم مفاجئ أو تغير الأعراض: إلى الطبيب."},{"h":"نصائح التطبيق","t":"قيّم بـTUG، والوقوف على ساق واحدة، والنهوض من الكرسي، وسرعة المشي، وقوة القبضة، وحدد أهدافًا فردية. ارفع الحمل تدريجيًا، وشجع على المواظبة مع الاهتمام بالتغذية."},{"h":"الأدلة العلمية","t":"برامج الحركة التي تشمل عناصر التوازن والتقوية فعالة في الوقاية من السقوط لدى المسنين المقيمين في منازلهم. المهم أن يمكن الاستمرار فيها."}]},"keypoints":["من معايير فريد للوهن تباطؤ سرعة المشي","ساركوبينيا: نقص الكتلة العضلية مع نقص القوة أو الوظيفة البدنية","الوقاية من السقوط: التوازن والقوة العضلية معًا","عند التحريك بعد استلقاء طويل انتبه لهبوط الضغط الانتصابي","في هشاشة العظام يُشتبه في كسر الفقرات عند ألم الظهر المفاجئ"],"case":{"text":"امرأة عمرها 82 عامًا، سقطت مرتين في العام الماضي. زمن TUG طويل، ولا تنهض من الكرسي إلا بالاستناد إلى يديها. تُعالج من هشاشة العظام، ولا تشكو من ألم الظهر. تعيش وحدها، ونادرًا ما تخرج من المنزل.","answer":"خطر السقوط مرتفع. اجمع تدريجيًا بين تمارين التوازن وتقوية الطرف السفلي، وعدّل بيئة السكن، وهيّئ فرصًا للخروج. لا تنصح بالراحة، ولا تعطِ حملًا كبيرًا منذ اليوم الأول."},"questions":[{"level":"أساسي","q":"أيّها من ضمن معايير فريد للوهن؟","options":["ضعف البصر","ارتفاع ضغط الدم","تباطؤ سرعة المشي","زيادة طول القامة"],"answer":2,"exp":"عناصر معايير فريد الخمسة: نقص الوزن، والإنهاك، وانخفاض النشاط، وتباطؤ المشي، وانخفاض القوة العضلية (قوة القبضة)."},{"level":"أساسي","q":"ما الحالة التي تنخفض فيها الكتلة العضلية مع الشيخوخة وتسوء القوة العضلية أو الوظيفة البدنية؟","options":["ساركوبينيا","هشاشة العظام","الفُصال العظمي","هبوط الضغط الانتصابي"],"answer":0,"exp":"في ساركوبينيا يصاحب نقصَ الكتلة العضلية تدهورٌ في القوة العضلية أو الوظيفة البدنية. أما هشاشة العظام فهي نقص الكتلة العظمية."},{"level":"متوسط","q":"ماذا يقيس اختبار TUG (Timed Up and Go)؟","options":["قوة القبضة","حركة تشمل النهوض والمشي والالتفاف","الوظيفة المعرفية فقط","وظيفة التنفس"],"answer":1,"exp":"يقيس TUG الزمن الذي يحتاجه المريض لينهض من الكرسي، ويمشي، ويلتفت، ويعود، ويجلس؛ ويقيّم التنقل وخطر السقوط."},{"level":"متوسط","q":"بعد استلقاء طويل، إلامَ يجب الانتباه خاصة عند أول جلوس أو وقوف للمسن؟","options":["تمزق الكفة المدورة","انخفاض حرارة الجسم","تقفع الأصابع","هبوط الضغط الانتصابي"],"answer":3,"exp":"بعد الاستلقاء الطويل يضعف تنظيم ضغط الدم، فينخفض بسهولة عند الجلوس والوقوف. تابع الأعراض وضغط الدم."},{"level":"سريري","q":"امرأة في الثمانينيات، سقطت سابقًا، زمن TUG طويل، وقوة الطرف السفلي منخفضة. ما التدخل المناسب؟","options":["التوازن وتقوية الطرف السفلي معًا","الإطالة فقط","النصح بالراحة","تقوية بحمل أقصى منذ اليوم الأول"],"answer":0,"exp":"في الوقاية من السقوط تكون الحركة التي تجمع عناصر التوازن والتقوية فعالة. ارفع الحمل تدريجيًا."},{"level":"سريري","q":"امرأة عمرها 85 عامًا، هشاشة العظام. بعد سقوط خفيف على المقعدة ظهر فجأة ألم شديد في الظهر. ماذا تفعل؟","options":["تزيد تمارين ثني الجذع","تنتظر مع العلاج الحراري","تحيلها إلى الطبيب لفحص تصويري","تجري إطالة لعضلات الظهر"],"answer":2,"exp":"لدى المسن المصاب بهشاشة العظام يُشتبه في كسر انضغاطي في الفقرات عند ألم الظهر المفاجئ بعد رض بسيط. لا تواصل التمارين، وأحِلها إلى الطبيب."}],"seccion":"العلاجات والتدخلات","grupo":"العلاج بالحركة والتخصصات","icono":"🩺","mapa":"img/mapas/t53.jpg","fichas":[],"secuencias":[]},"54":{"id":54,"title":"حالات سريرية","lead":"مسار التفكير السريري: من التاريخ المرضي تضع فرضية، وتتحقق منها بالفحص، وبعد تلخيص النتائج وتفسيرها تحدد الهدف والعلاج. وبإعادة الفحص تراجع باستمرار.","sheet":{"kind":"basics","items":[{"h":"التاريخ المرضي","t":"اسأل عن الشكوى الرئيسية، ومسار ظهورها، وموضع الألم وطبيعته، والعوامل المفاقمة والمخففة، والسوابق المرضية، والأدوية، وظروف الحياة، والرغبات. وافحص العلامات الحمراء أيضًا."},{"h":"وضع الفرضيات","t":"بناءً على التاريخ المرضي اجمع عدة أسباب وحالات مرضية محتملة، وقرر ما يجب التحقق منه بالفحص. لا تلتزم فورًا بتفسير واحد."},{"h":"الفحص","t":"تحقق من الفرضية بالمعاينة، والجس، وقياس ROM، وفحص القوة العضلية، والاختبارات الخاصة، والفحص العصبي، وتحليل الحركة. لاحظ الفرق بين الجانبين وقابلية التكرار."},{"h":"التلخيص والتفسير","t":"رتب النتائج في إطار ICF (وظائف الجسم، والنشاط، والمشاركة، والبيئة)، وفكّر في العلاقات بين المشكلات وترتيب أولوياتها."},{"h":"تحديد الأهداف","t":"حدد بالاشتراك مع المريض والأسرة أهدافًا قصيرة وطويلة المدى، محددة وقابلة للقياس ومقيدة بزمن. المهم الأهداف المرتبطة بمواقف الحياة اليومية."},{"h":"العلاج وإعادة الفحص","t":"اختر التدخل وفق الأهداف، وأعد فحص التغير بالمؤشرات نفسها. إن لم يحدث تحسن فعُد إلى الفرضية والفحص."}]},"keypoints":["افحص العلامات الحمراء دائمًا أثناء أخذ التاريخ المرضي","ضع عدة فرضيات، وتحقق من كل منها بالفحص","رتب المشكلات في إطار ICF","ليكن الهدف مشتركًا مع المريض، وقابلًا للقياس، ومقيدًا بزمن","إن لم يحدث تحسن فأعد التفكير بدءًا من الفرضية والفحص"],"case":{"text":"رجل عمره 68 عامًا، فُصال عظمي في الركبتين. تؤلمه ركبته اليمنى عند المشي؛ وضعفت العضلة الرباعية اليمنى، وبسط الركبة مقيد. رغبته: «أريد أن أتمشى مع حفيدي إلى الحديقة القريبة».","answer":"رتب الألم، والضعف العضلي، وتقييد الحركة، ومحدودية المشي، وحدد المشي إلى الحديقة هدفًا بموعد زمني. نفّذ تمارين التقوية وROM، وأعد الفحص حسب الألم والمسافة المقطوعة. لا تقرر بناءً على نتيجة التصوير وحدها."},"questions":[{"level":"أساسي","q":"في مسار التفكير السريري، ما الذي يلي التاريخ المرضي؟","options":["بدء العلاج","وضع الفرضية","تحديد الهدف نهائيًا","إرشادات الخروج"],"answer":1,"exp":"بناءً على المعلومات من التاريخ المرضي تضع فرضية عن السبب والحالة المرضية، وتختار الفحوص التي تتحقق منها."},{"level":"أساسي","q":"ما الطريقة الصحيحة لتحديد الهدف؟","options":["أخصائي العلاج الطبيعي يقرر وحده","صياغة مجردة","دون موعد زمني","هدف قابل للقياس ومقيد بزمن"],"answer":3,"exp":"ليكن الهدف مشتركًا مع المريض والأسرة، ومحددًا، وقابلًا للقياس، ومقيدًا بزمن. وبذلك يمكن تقدير التغير عند إعادة الفحص."},{"level":"متوسط","q":"حسب ICF، أين تصنف «لا يستطيع صعود الدرج»؟","options":["النشاط","المشاركة","وظائف الجسم وبنيته","العوامل البيئية"],"answer":0,"exp":"الفعل الذي يؤديه الفرد، كصعود الدرج، يدخل ضمن «النشاط». أما المشاركة في الأدوار الاجتماعية فهي «المشاركة»."},{"level":"متوسط","q":"ماذا تفعل إن لم يحدث تحسن عند إعادة الفحص بعد التدخل؟","options":["تواصل العلاج نفسه","تتجاوز الفحص","تراجع الفرضية والفحص","تنسب ذلك إلى قلة جهد المريض"],"answer":2,"exp":"إن لم يحدث تحسن فراجع صحة الفرضية والفحص، وأعد التفكير في تفسير الحالة والتدخل."},{"level":"سريري","q":"رجل في الخمسينيات: ألم جانبي في الكتف في المدى الأوسط للرفع، واختبار هوكينز-كينيدي إيجابي، وROM السلبي سليم. بماذا تشتبه؟","options":["الكتف المتجمد","الانحشار تحت الأخرم","اعتلال الجذر العصبي العنقي","متلازمة مخرج الصدر"],"answer":1,"exp":"القوس المؤلم في المدى الأوسط للرفع واختبار هوكينز-كينيدي الإيجابي يشيران إلى الانحشار تحت الأخرم. في الكتف المتجمد يكون ROM السلبي مقيدًا أيضًا."},{"level":"سريري","q":"امرأة في الستينيات، ألم أسفل الظهر؛ لديها سابقة ورم، وألم ليلي، ونقص وزن غير مفسر. ماذا تفعل؟","options":["تبدأ تمارين العمود القطني","تجري تقويمًا يدويًا","تنتظر مع العلاج الحراري","تبلغ الطبيب وتطلب فحصًا"],"answer":3,"exp":"سابقة الورم والألم الليلي ونقص الوزن علامة حمراء تشير إلى مرض خطير. إحالة فورية للفحص الطبي قبل العلاج."}],"seccion":"العلاجات والتدخلات","grupo":"حالات سريرية","icono":"🧩","mapa":"img/mapas/t54.jpg","fichas":[],"secuencias":[]}}};
